const i=JSON.parse('{"work":{"id":"shiji","schoolId":"histories","title":"《史記》","genreStrategy":"parallel","sourceNote":"版本來源自通行本及校勘附記。","chapterIds":["shiji_ch-1","shiji_ch-2"],"totalChars":8637},"chapters":[{"id":"shiji_ch-1","workId":"shiji","order":1,"title":"五帝本紀","difficulty":4,"estimatedMinutes":16,"passageIds":["shiji_ch-1_p-1","shiji_ch-1_p-2","shiji_ch-1_p-3","shiji_ch-1_p-4","shiji_ch-1_p-5","shiji_ch-1_p-6","shiji_ch-1_p-7","shiji_ch-1_p-8","shiji_ch-1_p-9","shiji_ch-1_p-10","shiji_ch-1_p-11","shiji_ch-1_p-12","shiji_ch-1_p-13","shiji_ch-1_p-14","shiji_ch-1_p-15","shiji_ch-1_p-16","shiji_ch-1_p-17","shiji_ch-1_p-18","shiji_ch-1_p-19","shiji_ch-1_p-20","shiji_ch-1_p-21","shiji_ch-1_p-22","shiji_ch-1_p-23","shiji_ch-1_p-24","shiji_ch-1_p-25","shiji_ch-1_p-26","shiji_ch-1_p-27","shiji_ch-1_p-28","shiji_ch-1_p-29"],"tags":[]},{"id":"shiji_ch-2","workId":"shiji","order":2,"title":"夏本紀","difficulty":4,"estimatedMinutes":14,"passageIds":["shiji_ch-2_p-1","shiji_ch-2_p-2","shiji_ch-2_p-3","shiji_ch-2_p-4","shiji_ch-2_p-5","shiji_ch-2_p-6","shiji_ch-2_p-7","shiji_ch-2_p-8","shiji_ch-2_p-9","shiji_ch-2_p-10","shiji_ch-2_p-11","shiji_ch-2_p-12","shiji_ch-2_p-13","shiji_ch-2_p-14","shiji_ch-2_p-15","shiji_ch-2_p-16","shiji_ch-2_p-17","shiji_ch-2_p-18","shiji_ch-2_p-19","shiji_ch-2_p-20","shiji_ch-2_p-21","shiji_ch-2_p-22","shiji_ch-2_p-23","shiji_ch-2_p-24","shiji_ch-2_p-25","shiji_ch-2_p-26","shiji_ch-2_p-27","shiji_ch-2_p-28","shiji_ch-2_p-29","shiji_ch-2_p-30","shiji_ch-2_p-31","shiji_ch-2_p-32","shiji_ch-2_p-33","shiji_ch-2_p-34","shiji_ch-2_p-35"],"tags":[]}],"passages":[{"id":"shiji_ch-1_p-1","chapterId":"shiji_ch-1","order":1,"canonicalText":"黃帝者，少典之子，姓公孫，名曰軒轅。生而神靈，弱而能言，幼而徇齊，長而敦敏，成而聰明。","sentenceIds":["shiji_ch-1_p-1_s-1","shiji_ch-1_p-1_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"黃帝是少典部落國君的兒子，姓公孫，名叫軒轅。他生來就稟賦神異非凡，嬰兒襁褓之時就能開口說話，幼年時思維敏捷迅速（徇齊），長大後敦厚勤勉篤實（敦敏），成年之後更是聰穎睿智博達通明！","analysis":"【題解與背景】\\n本段選自《史記》〈五帝本紀〉第 1 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「黃帝者少典之子姓公孫名曰軒轅生而神靈弱而能言……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「黃」、「帝」、「少」、「典」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《史記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"shiji_ch-1_p-2","chapterId":"shiji_ch-1","order":2,"canonicalText":"軒轅之時，神農氏世衰。諸侯相侵伐，暴虐百姓，而神農氏弗能徵。於是軒轅乃習用干戈，以徵不享，諸侯鹹來賓從。而蚩尤最為暴，莫能伐。炎帝欲侵陵諸侯，諸侯鹹歸軒轅。軒轅乃修德振兵，治五氣，蓺五種，撫萬民，度四方，教熊羆貔貅貙虎，以與炎帝戰於阪泉之野。三戰，然後得其志。蚩尤作亂，不用帝命。於是黃帝乃徵師諸侯，與蚩尤戰於涿鹿之野，遂禽殺蚩尤。而諸侯鹹尊軒轅為天子，代神農氏，是為黃帝。天下有不順者，黃帝從而徵之，平者去之，披山通道，未嘗寧居。","sentenceIds":["shiji_ch-1_p-2_s-1","shiji_ch-1_p-2_s-2","shiji_ch-1_p-2_s-3","shiji_ch-1_p-2_s-4","shiji_ch-1_p-2_s-5","shiji_ch-1_p-2_s-6","shiji_ch-1_p-2_s-7","shiji_ch-1_p-2_s-8","shiji_ch-1_p-2_s-9","shiji_ch-1_p-2_s-10","shiji_ch-1_p-2_s-11"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"軒轅的時，神農氏世衰。諸侯相侵伐，暴虐百姓，並且神農氏弗能徵。於是軒轅於是習用干戈用徵不享，諸侯鹹來賔從。並且蚩尤最為暴，莫能伐。炎帝欲侵陵諸侯，諸侯鹹歸軒轅。軒轅於是修德振兵，治五氣，藝五種，撫萬民，度四方，教熊羆貔貅貙虎，用和炎帝戰於阪泉的野。三戰，然後得他志。蚩尤作亂，不用帝命。於是黃帝於是徵師諸侯，和蚩尤戰於涿鹿的野，遂禽殺蚩尤。並且諸侯鹹尊軒轅為天子，代神農氏，是為黃帝。天下人有不順的人們，黃帝從並且徵的，平的人去的，披山通道，未嘗寧居。","analysis":"【主題與背景】本段「軒轅之時，神農氏世衰。諸...」立足於當時的時代脈絡，集中探討了諸侯相關的核心議題。這反映出在歷史演變中，社會制度與思想的激烈碰撞。\\n【詞義與名物】作者使用了「諸侯」等關鍵字眼，這在古代文獻中通常用來描述特定的歷史名物。透過「帝軒」的使用，文章進一步勾勒出當時的文化特色。\\n【史家寄託】透過對諸侯的描寫，作者寄寓了深沉的歷史反思。這段敘述不僅是客觀紀錄，更隱含了對國家興亡與人事變遷的警世意味。"}},{"id":"shiji_ch-1_p-3","chapterId":"shiji_ch-1","order":3,"canonicalText":"東至於海，登丸山，及岱宗。西至於空桐，登雞頭。南至於江，登熊、湘。北逐葷粥，合符釜山，而邑於涿鹿之阿。遷徙往來無常處，以師兵為營衛。官名皆以雲命，為雲師。置左右大監，監於萬國。萬國和，而鬼神山川公卿壇墠及西泰躋召，所從古以來。","sentenceIds":["shiji_ch-1_p-3_s-1","shiji_ch-1_p-3_s-2","shiji_ch-1_p-3_s-3","shiji_ch-1_p-3_s-4","shiji_ch-1_p-3_s-5","shiji_ch-1_p-3_s-6","shiji_ch-1_p-3_s-7","shiji_ch-1_p-3_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"東至在海，登丸山，及岱宗。西至在空桐，登雞頭。南至在江，登熊、湘。北逐葷粥，合符釜山，並且邑在涿鹿的阿。遷徙往來無常處，用師兵為營衞。官名都用雲命，為雲師。置左右大監，監在萬國家。萬國和，並且鬼神山川封禪和為多焉。獲寶鼎，迎日推策。舉風後、力牧、常先、大鴻用治民。順天地的紀，幽明的佔，死生的說，存亡的難。時播百穀草木，淳化鳥獸蟲蛾，旁羅日月星辰水波土石金玉，勞勤心力耳目，節用水火材物。有土德的瑞，故號黃帝。","analysis":"【主題與背景】針對至登的現象，這段文獻「東至於海，登丸山，及岱宗...」提供了深刻的視角。其背後的歷史情境，凸顯了各方勢力對於國家治理的多元思考。\\n【詞義與名物】文中的「至登」代表了當時特有的社會階層或制度規範，而「山為」則具體指涉了相關的器物與理念。這些詞彙精準呈現了古人的生活實態。\\n【史家寄託】這不僅是一段關於山為的歷史記載，更體現了史學家對至登現象的深刻批判。字裡行間流露出對理想政治與社會秩序的嚮往。"}},{"id":"shiji_ch-1_p-4","chapterId":"shiji_ch-1","order":4,"canonicalText":"黃帝二十五子，其得姓者十四人。","sentenceIds":["shiji_ch-1_p-4_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"黃帝一生共生育了二十五位兒子，其中建立功德獲賜獨立姓氏並開枝散葉傳承後代的共有十四人。","analysis":"【題解與背景】\\n本段選自《史記》〈五帝本紀〉第 4 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「黃帝二十五子其得姓者十四人……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「黃」、「帝」、「二」、「十」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《史記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"shiji_ch-1_p-5","chapterId":"shiji_ch-1","order":5,"canonicalText":"黃帝居於軒轅之丘，而娶於西陵之女，是為嫘祖。嫘祖為黃帝正妃，生二子，其後皆有天下：其一曰玄囂，是為青陽，青陽降居江水；其二曰昌意，降居若水。昌意娶蜀山氏女，曰昌僕，生高陽，高陽有聖德。黃帝崩，葬橋山。其孫昌意之子高陽立，是為帝顓頊也。","sentenceIds":["shiji_ch-1_p-5_s-1","shiji_ch-1_p-5_s-2","shiji_ch-1_p-5_s-3","shiji_ch-1_p-5_s-4","shiji_ch-1_p-5_s-5","shiji_ch-1_p-5_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"黃帝居住在軒轅之丘，娶了西陵氏的女兒，這就是嫘祖。嫘祖是黃帝的正妃，生了兩個兒子，他們的後代都曾經取得天下：第一個兒子叫玄囂，也就是青陽，青陽後來降居在江水流域；第二個兒子叫昌意，後來降居在若水流域。昌意娶了蜀山氏的女兒，名叫昌僕，生下了高陽，高陽擁有聖明高尚的品德。黃帝駕崩後，安葬在橋山。他的孫子、也就是昌意的兒子高陽繼承了帝位，這就是顓頊帝。","analysis":"【訓詁與名物】「軒轅之丘」相傳為黃帝的出生地或都城。「嫘祖」相傳為教民養蠶繅絲的始祖。「正妃」指元配夫人。「降居」指皇子被分封或遷居到其他地方。「江水」與「若水」皆為古代河流名。「崩」為古代帝王死亡的專稱。「高陽」即顓頊帝的名字。\\n【章法與結構】本段為《史記》中標準的帝王世系與生平紀事。文字極為平實簡練，按時間順序，從黃帝的居住地、婚姻、子嗣繁衍，一直寫到黃帝駕崩及其孫子高陽（顓頊）繼位。雖然沒有華麗的辭藻，但條理清晰，為後世梳理中華民族始祖的血脈傳承提供了基礎的歷史框架。\\n【思想與義理】這段記載不僅是歷史的追溯，更蘊含了司馬遷建構中華大一統史觀的企圖。透過將上古各部族的領袖（如玄囂、昌意、顓頊）皆納入黃帝的血脈世系中（「其後皆有天下」），《史記》實際上在文化與政治上確立了「黃帝」作為中華民族共同始祖的神聖地位，強化了華夏文明同源共祖的歷史凝聚力。"}},{"id":"shiji_ch-1_p-6","chapterId":"shiji_ch-1","order":6,"canonicalText":"帝顓頊高陽者，黃帝之孫而昌意之子也。靜淵以有謀，疏通而知事；養材以任地，載時以象天，依鬼神以制義，治氣以教化，潔誠以祭祀。北至於幽陵，南至於交阯，西至於流沙，東至於蟠木。動靜之物，大小之神，日月所照，莫不祗勵。","sentenceIds":["shiji_ch-1_p-6_s-1","shiji_ch-1_p-6_s-2","shiji_ch-1_p-6_s-3","shiji_ch-1_p-6_s-4","shiji_ch-1_p-6_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"帝顓頊高陽的人們，黃帝的孫並且昌意的子啊。靜淵用有謀，疏通並且知事；養材用任地，載時用象天，依鬼神用制義，治氣用教化，絜誠用祭祀。北至在幽陵，南至在交阯，西至在流沙，東至在蟠木。動靜的物，大小的神，日月所照，莫不砥屬。","analysis":"【主題與背景】本段「帝顓頊高陽者，黃帝之孫而...」立足於當時的時代脈絡，集中探討了至帝相關的核心議題。這反映出在歷史演變中，社會制度與思想的激烈碰撞。\\n【詞義與名物】文中的「至帝」代表了當時特有的社會階層或制度規範，而「靜神」則具體指涉了相關的器物與理念。這些詞彙精準呈現了古人的生活實態。\\n【史家寄託】這不僅是一段關於靜神的歷史記載，更體現了史學家對至帝現象的深刻批判。字裡行間流露出對理想政治與社會秩序的嚮往。"}},{"id":"shiji_ch-1_p-7","chapterId":"shiji_ch-1","order":7,"canonicalText":"帝顓頊生子曰窮蟬。顓頊崩，而玄囂之孫高辛立，是為帝嚳。","sentenceIds":["shiji_ch-1_p-7_s-1","shiji_ch-1_p-7_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"顓頊帝生了一個兒子名叫窮蟬。顓頊駕崩後，玄囂的孫子高辛繼承了帝位，這就是帝嚳。","analysis":"【訓詁與名物】「窮蟬」為顓頊之子，據《史記》記載，他是舜的祖先。「玄囂」是黃帝的長子。「高辛」是人名，即後來的帝嚳。「崩」是古代帝王死亡的稱謂。「立」指繼承帝位。\\n【章法與結構】這是一段極度精簡的世系交替紀錄。第一句交代了顓頊的後代（窮蟬，為日後舜的出場埋下伏筆）；第二句直接切換到政權的轉移，說明顓頊死後，帝位並未傳給兒子，而是傳給了同屬黃帝世系的玄囂之孫高辛。短短二十餘字，便完成了一個時代的交接。\\n【思想與義理】此段記載反映了上古時期帝位傳承的複雜性。帝位並未在顓頊的直系子孫中延續，而是轉移到了黃帝另一支血脈（玄囂系）的高辛身上。這暗示了在早期部落聯盟時代，所謂的「帝位」繼承，可能並非嚴格的父死子繼，而是具有某種程度的家族內推舉或實力博弈的成分，但總體上仍維持在「黃帝子孫」這個大的血緣框架之內。"}},{"id":"shiji_ch-1_p-8","chapterId":"shiji_ch-1","order":8,"canonicalText":"帝嚳高辛者，黃帝之曾孫也。高辛父曰蟜極，蟜極父曰玄囂，玄囂父曰黃帝。自玄囂與蟜極皆不得在位，至高辛即帝位。高辛於顓頊為族子。","sentenceIds":["shiji_ch-1_p-8_s-1","shiji_ch-1_p-8_s-2","shiji_ch-1_p-8_s-3","shiji_ch-1_p-8_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"帝嚳高辛，是黃帝的曾孫。高辛的父親名叫蟜極，蟜極的父親名叫玄囂，玄囂的父親就是黃帝。從玄囂到蟜極，這兩代人都沒有登上帝位，直到高辛才繼承了帝位。高辛論輩分是顓頊的同族侄子。","analysis":"【訓詁與名物】「曾孫」指孫子的兒子。「不得在位」意指未能繼承帝位，可能只是部族首領或未掌握天下共主之權。「族子」指同族的晚輩，高辛的祖父玄囂與顓頊的父親昌意是親兄弟，故高辛為顓頊的堂侄。\\n【章法與結構】本段旨在詳細考證並確認帝嚳（高辛）的血脈淵源。首句先點明其為黃帝曾孫的總身份；接著運用連珠式的回溯句型（A父曰B，B父曰C），層層上推，將其血脈牢牢地連結至黃帝；最後補充說明其家族兩代未即位的背景，並釐清他與前任帝王顓頊的親屬關係，敘事邏輯極其嚴密。\\n【思想與義理】這段考證文字再次突顯了司馬遷在《五帝本紀》中建構「黃帝一系」大一統史觀的核心意圖。透過詳細梳理玄囂、蟜極至高辛的傳承脈絡，司馬遷向讀者證明：無論帝位如何流轉（從昌意系的顓頊回到玄囂系的高辛），天下的統治權始終沒有外流，全是黃帝的血脈。這為漢代乃至後世的「正統」觀念奠定了重要的歷史理論基礎。"}},{"id":"shiji_ch-1_p-9","chapterId":"shiji_ch-1","order":9,"canonicalText":"高辛生而神靈，自言其名。普施利物，不於其身。聰以知遠，明以察微。順天之義，知民之急。仁而威，惠而信，修身而天下服。取地之財而節用之，撫教萬民而利誨之，歷日月而迎送之，明鬼神而敬事之。其德莫大焉。","sentenceIds":["shiji_ch-1_p-9_s-1","shiji_ch-1_p-9_s-2","shiji_ch-1_p-9_s-3","shiji_ch-1_p-9_s-4","shiji_ch-1_p-9_s-5","shiji_ch-1_p-9_s-6","shiji_ch-1_p-9_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"高辛生並且神靈，自言他名。普施利物，不於他身。聦用知遠，明用察微。順天的義，知民的急。仁並且威，惠並且信，脩身並且天下人服。取地的財並且節用的，撫教萬民並且利誨的，曆日月並且迎送的，明神並且敬事的。他色鬱郁，他德嶷嶷。他動啊時，他服啊士。帝嚳溉執中並且徧天下，日月所照，風雨所至，莫不從服。","analysis":"【主題與背景】在春秋戰國至秦漢的歷史進程中，本段文字「高辛生而神靈，自言其名。...」主要講述了天服與神利的關聯。它揭示了當時政治局勢下的特定風貌。\\n【詞義與名物】文中的「天服」代表了當時特有的社會階層或制度規範，而「神利」則具體指涉了相關的器物與理念。這些詞彙精準呈現了古人的生活實態。\\n【史家寄託】藉由分析天服與不身的互動，本段傳達了作者對歷史規律的洞察。這正是古人「以史為鑑」精神的具體展現，具有深遠的教育意義。"}},{"id":"shiji_ch-1_p-10","chapterId":"shiji_ch-1","order":10,"canonicalText":"帝嚳娶陳鋒氏女，生放勛。娶娵訾氏女，生摯。帝嚳崩，而摯代立。帝摯立，不善（崩），而弟放勛立，是為帝堯。","sentenceIds":["shiji_ch-1_p-10_s-1","shiji_ch-1_p-10_s-2","shiji_ch-1_p-10_s-3","shiji_ch-1_p-10_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"帝嚳娶陳鋒氏女，生放勛。娶娵訾氏女，生摯。帝嚳崩，並且摯代立。帝摯立，不善，崩，並且弟放勳立，是為帝堯。","analysis":"【主題與背景】針對帝摯的現象，這段文獻「帝嚳娶陳鋒氏女，生放勛。...」提供了深刻的視角。其背後的歷史情境，凸顯了各方勢力對於國家治理的多元思考。\\n【詞義與名物】在此，我們必須特別注意「立嚳」與「娶氏」的時代含義。這些字眼不僅僅是字面上的意思，更包含了傳統禮法與社會結構的深層內涵。\\n【史家寄託】透過對帝摯的描寫，作者寄寓了深沉的歷史反思。這段敘述不僅是客觀紀錄，更隱含了對國家興亡與人事變遷的警世意味。"}},{"id":"shiji_ch-1_p-11","chapterId":"shiji_ch-1","order":11,"canonicalText":"帝堯者，放勛。其仁如天，其知如神。就之如日，望之如雲。富而不驕，貴而不舒。黃收純衣，彤車乘白馬。能明馴德，以親九族。九族既睦，便章百姓。百姓昭明，合和萬國。","sentenceIds":["shiji_ch-1_p-11_s-1","shiji_ch-1_p-11_s-2","shiji_ch-1_p-11_s-3","shiji_ch-1_p-11_s-4","shiji_ch-1_p-11_s-5","shiji_ch-1_p-11_s-6","shiji_ch-1_p-11_s-7","shiji_ch-1_p-11_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"用現代漢語來說：帝堯的人們，放勳。他仁如天，他知如神。就的如日，望的如雲。富並且不驕，貴並且不舒。黃收純衣，彤車乘白馬。能明馴德，用親九族。九族旣睦，便章百姓。百姓昭明，合和萬國家。","analysis":"【主題與背景】本段「帝堯者，放勳。其仁如天，...」立足於當時的時代脈絡，集中探討瞭如不相關的核心議題。這反映出在歷史演變中，社會制度與思想的激烈碰撞。\\n【詞義與名物】在此，我們必須特別注意「明九」與「族百」的時代含義。這些字眼不僅僅是字面上的意思，更包含了傳統禮法與社會結構的深層內涵。\\n【史家寄託】藉由分析如不與族百的互動，本段傳達了作者對歷史規律的洞察。這正是古人「以史為鑑」精神的具體展現，具有深遠的教育意義。"}},{"id":"shiji_ch-1_p-12","chapterId":"shiji_ch-1","order":12,"canonicalText":"乃命羲、和，敬順昊天，數法日月星辰，敬授民時。分命羲仲，居鬱夷，曰暘谷。敬道日出，便程東作。日中，星鳥，以殷仲春。厥民析，鳥獸孳尾。申命羲叔，居南交。便程南為，敬致。日永，星火，以正仲夏。厥民因，鳥獸希革。申命和仲，居西土，曰昧谷。敬道日入，便程西成。夜中，星虛，以正仲秋。厥民夷易，鳥獸毛毨。申命和叔，居北方，曰幽都。便在伏物。日短，星昴，以正仲冬。厥民燠，鳥獸氄毛。歲三百六十六日，以閏月正四時。信飭百官，眾功皆興。","sentenceIds":["shiji_ch-1_p-12_s-1","shiji_ch-1_p-12_s-2","shiji_ch-1_p-12_s-3","shiji_ch-1_p-12_s-4","shiji_ch-1_p-12_s-5","shiji_ch-1_p-12_s-6","shiji_ch-1_p-12_s-7","shiji_ch-1_p-12_s-8","shiji_ch-1_p-12_s-9","shiji_ch-1_p-12_s-10","shiji_ch-1_p-12_s-11","shiji_ch-1_p-12_s-12","shiji_ch-1_p-12_s-13","shiji_ch-1_p-12_s-14","shiji_ch-1_p-12_s-15","shiji_ch-1_p-12_s-16","shiji_ch-1_p-12_s-17","shiji_ch-1_p-12_s-18","shiji_ch-1_p-12_s-19"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"用現代漢語來說：於是命羲、和，敬順昊天，數法日月星辰，敬授民時。分命羲仲，居鬱夷，說暘谷。敬道日出，便程東作。日中，星鳥，用殷中春。他民析，鳥獸字微。申命羲叔，居南交。便程南譌，敬致。日永，星火，用正中夏。他民因，鳥獸希革。申命和仲，居西土，說昧谷。敬道日入，便程西成。夜中，星虛，用正中秋。他民夷易，鳥獸毛毨。申命和叔；居北方，說幽都。便在伏物。日短，星昂，用正中冬。他民燠，鳥獸氄毛。歲三百六十六日，用閏月正四時。信飭百官，衆功都興。","analysis":"【主題與背景】本段「乃命羲、和，敬順昊天，數...」立足於當時的時代脈絡，集中探討了日中相關的核心議題。這反映出在歷史演變中，社會制度與思想的激烈碰撞。\\n【詞義與名物】在此，我們必須特別注意「命敬」與「星民」的時代含義。這些字眼不僅僅是字面上的意思，更包含了傳統禮法與社會結構的深層內涵。\\n【史家寄託】這不僅是一段關於命敬的歷史記載，更體現了史學家對日中現象的深刻批判。字裡行間流露出對理想政治與社會秩序的嚮往。"}},{"id":"shiji_ch-1_p-13","chapterId":"shiji_ch-1","order":13,"canonicalText":"堯曰：「誰可順此事？」放齊曰：「嗣子丹朱開明。」堯曰：「籲！頑兇，不用。」堯又曰：「誰可者？」讙兜曰：「便窮共工，部聚用事，可。」堯曰：「共工善言而意色，恭天，欺慢，不可。」堯又曰：「嗟，四嶽，湯湯洪水滔天，浩浩懷山襄陵，下民其憂，有能使治者？」皆曰鯀可。堯曰：「鯀負命毀族，不可。」嶽曰：「異哉，試不可用而已。」堯乃聽嶽，用鯀治水。九年而水不息，功用不成。","sentenceIds":["shiji_ch-1_p-13_s-1","shiji_ch-1_p-13_s-2","shiji_ch-1_p-13_s-3","shiji_ch-1_p-13_s-4","shiji_ch-1_p-13_s-5","shiji_ch-1_p-13_s-6","shiji_ch-1_p-13_s-7","shiji_ch-1_p-13_s-8","shiji_ch-1_p-13_s-9","shiji_ch-1_p-13_s-10","shiji_ch-1_p-13_s-11","shiji_ch-1_p-13_s-12","shiji_ch-1_p-13_s-13"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"其大意是：堯說：誰可順此事？放齊說：嗣子丹朱開明。堯說：籲！頑兇，不用。堯又說：誰可的人們？讙兜說：共工旁聚布功，可用。堯說：共工善言，他用僻，似恭漫天，不可。堯又說：嗟，四嶽，湯湯洪水滔天，浩浩懷山襄陵，下民他憂，有能使治的人？都說鯀可。堯說：鯀負命毀族，不可。嶽說：異哉，試不可用並且已。堯於是聽嶽用鯀。九載，功用不成。","analysis":"【主題與背景】針對堯可的現象，這段文獻「堯曰：「誰可順此事？」放...」提供了深刻的視角。其背後的歷史情境，凸顯了各方勢力對於國家治理的多元思考。\\n【詞義與名物】作者使用了「堯可」等關鍵字眼，這在古代文獻中通常用來描述特定的歷史名物。透過「用不」的使用，文章進一步勾勒出當時的文化特色。\\n【史家寄託】藉由分析堯可與嶽鯀的互動，本段傳達了作者對歷史規律的洞察。這正是古人「以史為鑑」精神的具體展現，具有深遠的教育意義。"}},{"id":"shiji_ch-1_p-14","chapterId":"shiji_ch-1","order":14,"canonicalText":"堯曰：「嗟！四嶽：朕在位七十載，汝能庸命，踐朕位？」嶽應曰：「鄙德忝帝位。」堯曰：「悉舉貴戚及疏遠隱匿者。」眾皆言於堯曰：「有矜在民間，曰虞舜。」堯曰：「然，朕聞之。其何如？」嶽曰：「盲者子。父頑，母嚚，弟傲，能和以孝，烝烝治，不格姦。」","sentenceIds":["shiji_ch-1_p-14_s-1","shiji_ch-1_p-14_s-2","shiji_ch-1_p-14_s-3","shiji_ch-1_p-14_s-4","shiji_ch-1_p-14_s-5","shiji_ch-1_p-14_s-6","shiji_ch-1_p-14_s-7","shiji_ch-1_p-14_s-8","shiji_ch-1_p-14_s-9","shiji_ch-1_p-14_s-10"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"帝堯深情地對四嶽大臣說：唉！諸位四嶽長官：寡人在天子大位上已經操勞了整整七十年，你們之中有誰能夠順應承擔天命，前來繼承接替寡人的天子帝位？四嶽長官惶恐推辭回答說：我們德行淺薄鄙陋，不敢玷污褻瀆至高天子神聖大位！帝堯說：那麼就請諸位毫無保留地全面推薦賢才，無論是王室貴戚，還是身處草野民間極端偏僻隱沒的貧寒賢士，一概皆可舉薦！滿朝大臣群臣一致向帝堯異口同聲稟報說：在民間有一位至今未婚的單身賢士（有矜在民間），名叫虞舜！帝堯說：是的，寡人也曾聽聞過他的美名。他究竟為人如何呢？四嶽長官回答說：他是個雙目失明的盲老人的兒子。他的父親愚頑兇暴，他的繼母言行邪僻狡詐，他的弟弟象為人狂妄傲慢；然而舜卻能夠始終如一用至純至孝感化調和整個家庭，使全家日益走向和睦美好，從來沒有陷入邪惡姦惡之中！","analysis":"【題解與背景】\\n本段選自《史記》〈五帝本紀〉第 14 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「堯曰嗟四嶽朕在位七十載汝能庸命踐朕位嶽應曰鄙……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「堯」、「嗟」、「四」、「嶽」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《史記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"shiji_ch-1_p-15","chapterId":"shiji_ch-1","order":15,"canonicalText":"堯善之，乃使舜慎和五典，五典能從。乃遍入百官，百官時序。賓於四門，四門穆穆，諸侯遠方賓客皆敬。堯乃試舜五典百官，皆修。","sentenceIds":["shiji_ch-1_p-15_s-1","shiji_ch-1_p-15_s-2","shiji_ch-1_p-15_s-3","shiji_ch-1_p-15_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"帝堯聽聞後深表讚賞，於是委派虞舜慎重調和並推行父義、母慈、兄友、弟恭、子孝五種人倫常理（慎和五典），天下百姓皆心悅誠服自覺遵從！隨後帝堯讓舜全面參與協調中央各級官署百官事務，百官職守井井有條運轉井然有序！帝堯又任命舜在明堂四方大門接待四方諸侯朝覲貴賓（賓於四門），四方大門氣氛莊嚴穆穆肅敬，天下諸侯與遠方外邦使節賓客無不對舜肅然起敬由衷敬服！帝堯在五常倫理、百官行政與外交禮儀各個領域全面考驗虞舜，舜全部辦理得盡善盡美修明大治！","analysis":"【題解與背景】\\n本段選自《史記》〈五帝本紀〉第 15 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「堯善之乃使舜慎和五典五典能從乃遍入百官百官時……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「堯」、「善」、「使」、「舜」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《史記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"shiji_ch-1_p-16","chapterId":"shiji_ch-1","order":16,"canonicalText":"於是帝堯老，命舜攝行天子之政，以觀天命。舜乃在璿璣玉衡，以齊七政。遂類於上帝，禋於六宗，望於山川，遍於羣神。輯五瑞，擇吉月日，見四嶽諸牧，班瑞。","sentenceIds":["shiji_ch-1_p-16_s-1","shiji_ch-1_p-16_s-2","shiji_ch-1_p-16_s-3","shiji_ch-1_p-16_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"到了這時帝堯年事已高，正式命令虞舜代行攝理天子最高政務（攝行天子之政），以此全面考察體察上天天命。虞舜即位攝政之後，首先運用觀測天象的璿璣玉衡天文儀器，以此整飭調齊日、月與金、木、水、火、土五大行星的運行節奏（以齊七政）！隨後在天地神壇舉行類祭祭祀至高皇天上帝，舉行純潔的禋祭祭祀天地六宗神祇，遙望名山大川舉行望祭，普遍祭祀天下各方神靈！虞舜收聚天下諸侯所持有的玉珪玉璧五種信物（輯五瑞），挑選良辰吉日，在朝堂上親自接見四嶽長官與九州各路州牧，將審核合格的信物重新頒發賜還給諸侯（班瑞）！","analysis":"【題解與背景】\\n本段選自《史記》〈五帝本紀〉第 16 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「於是帝堯老命舜攝行天子之政以觀天命舜乃在璿璣……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「是」、「帝」、「堯」、「老」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《史記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"shiji_ch-1_p-17","chapterId":"shiji_ch-1","order":17,"canonicalText":"讙兜進言共工，堯曰不可而試之工師，共工果淫闢。四嶽舉鯀治鴻水，堯以為不可，嶽彊請試之，試之而無功，故百姓不便。三苗在江淮、荊州數為亂。於是舜歸而言於帝，請流共工於幽陵，以變北狄；放驩兜於崇山，以變南蠻；遷三苗於三危，以變西戎；殛鯀於羽山，以變東夷：四罪而天下鹹服。","sentenceIds":["shiji_ch-1_p-17_s-1","shiji_ch-1_p-17_s-2","shiji_ch-1_p-17_s-3","shiji_ch-1_p-17_s-4","shiji_ch-1_p-17_s-5","shiji_ch-1_p-17_s-6","shiji_ch-1_p-17_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"堯立七十年得舜，二十年並且老，令舜攝行天子的政，薦的於天。堯闢位凡二十八年並且崩。百姓悲哀，如喪父母。三年，四方莫舉樂，用思堯。堯知子丹朱的不肖，不足授天下人，於是於是權授舜。授舜，那麼天下得他利並且丹朱病；授丹朱，那麼天下病並且丹朱得他利。堯說終不用天下的病並且利一人們，並且卒授舜用天下。堯崩，三年的喪畢，舜讓闢丹朱於南河的南。諸侯朝覲的人不的丹朱並且的舜，獄訟的人不的丹朱並且的舜，謳歌的人不謳歌丹朱並且謳歌舜。舜說天啊，那並且後的中國家踐天子位焉，是為帝舜。","analysis":"【主題與背景】本段「堯立七十年得舜，二十年而...」立足於當時的時代脈絡，集中探討了舜天相關的核心議題。這反映出在歷史演變中，社會制度與思想的激烈碰撞。\\n【詞義與名物】在此，我們必須特別注意「丹朱」與「堯不」的時代含義。這些字眼不僅僅是字面上的意思，更包含了傳統禮法與社會結構的深層內涵。\\n【史家寄託】藉由分析舜天與堯不的互動，本段傳達了作者對歷史規律的洞察。這正是古人「以史為鑑」精神的具體展現，具有深遠的教育意義。"}},{"id":"shiji_ch-1_p-18","chapterId":"shiji_ch-1","order":18,"canonicalText":"堯立七十年得舜，二十年而老，令舜攝行天子之政，薦之於天。堯闢位凡二十八年而崩。百姓悲哀，如喪考妣。三年，四方莫舉樂，以思堯。堯知子丹朱之不肖，不足授天下，於是乃權授舜。授舜，則天下得其利而丹朱病；授丹朱，則天下病而丹朱得其利。堯曰：「終不以天下之病而利一人」，而卒以此天下授舜。堯崩，三年之喪畢，舜讓闢丹朱於南河之南。諸侯朝覲者不之丹朱而之舜，獄訟者不之丹朱而之舜，謳歌者不謳歌丹朱而謳歌舜。舜曰：「天也夫！」乃之中國踐天子位，是為帝舜。","sentenceIds":["shiji_ch-1_p-18_s-1","shiji_ch-1_p-18_s-2","shiji_ch-1_p-18_s-3","shiji_ch-1_p-18_s-4","shiji_ch-1_p-18_s-5","shiji_ch-1_p-18_s-6","shiji_ch-1_p-18_s-7","shiji_ch-1_p-18_s-8","shiji_ch-1_p-18_s-9","shiji_ch-1_p-18_s-10","shiji_ch-1_p-18_s-11","shiji_ch-1_p-18_s-12"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"帝堯在位七十年之際尋訪獲得了虞舜，又經過二十年考驗後帝堯年邁退居二線，命令虞舜全面攝理行使天子最高政務，並正式向上天祈禱推薦舜。帝堯避位讓政長達二十八年之後安詳崩殂。天下全體黎民百姓悲傷痛哭，如同失去了自己的親生父母一般哀慟（如喪考妣）！在長達三年的國喪之中，天下四方全體自覺停止演奏任何音樂娛樂，以此永恆緬懷悼念帝堯！帝堯深知自己的親生兒子丹朱品德不肖頑劣，根本不具備君臨天下的才德，於是在公私大義之間權衡將天下禪讓託付給了虞舜。傳位給虞舜，那麼全天下億萬黎民就能享有安康福祉而唯獨丹朱一人失落受損；若傳位給丹朱，那麼全天下黎民百姓都將遭受苦難災殃而唯獨丹朱一人享有私利。帝堯莊重宣告道：寡人身為天子，終究絕不能讓全天下黎民百姓遭受苦難來成全一個人的私利（終不以天下之病而利一人）！最終毅然將天子帝位與萬裏江山禪讓授給了虞舜！帝堯崩逝守滿三年之喪結束之後，虞舜為了表達對帝堯血脈的謙讓尊崇，主動退避居住在南河的南邊，將都城讓給丹朱。然而天下前來朝見朝覲的諸侯諸侯不去朝覲丹朱而爭相前往朝拜虞舜，天下打官司訴訟審案的百姓不找丹朱而爭相前來請求虞舜裁決，民間創作歌謠謳歌功德的萬民不謳歌丹朱而深情謳歌虞舜！虞舜由衷感嘆道：這真是偉大不可抗拒的民心天命啊（天也夫）！於是毅然重返中原帝都正式登基踐祚即天子位，這就是偉大的帝舜！","analysis":"【題解與背景】\\n本段選自《史記》〈五帝本紀〉第 18 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「堯立七十年得舜二十年而老令舜攝行天子之政……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「堯」、「立」、「七」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《史記》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：shiji_ch-1_p-18）。"}},{"id":"shiji_ch-1_p-19","chapterId":"shiji_ch-1","order":19,"canonicalText":"虞舜者，名曰重華。重華父曰瞽叟，瞽叟父曰橋牛，橋牛父曰句望，句望父曰敬康，敬康父曰窮蟬，窮蟬父曰帝顓頊，顓頊父曰昌意：以至舜七世矣。自從窮蟬以至順，皆微為庶人。","sentenceIds":["shiji_ch-1_p-19_s-1","shiji_ch-1_p-19_s-2","shiji_ch-1_p-19_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"用現代漢語來說：舜父瞽叟盲，並且舜母死，瞽叟更娶妻並且生象，象傲。瞽叟愛後妻子，常欲殺舜，舜避逃；及有小過，那麼受罪。順事父及後母和弟，日用篤謹，匪有懈。","analysis":"【主題與背景】在春秋戰國至秦漢的歷史進程中，本段文字「舜父瞽叟盲，而舜母死，瞽...」主要講述了舜瞽與叟父的關聯。它揭示了當時政治局勢下的特定風貌。\\n【詞義與名物】在此，我們必須特別注意「叟父」與「母妻」的時代含義。這些字眼不僅僅是字面上的意思，更包含了傳統禮法與社會結構的深層內涵。\\n【史家寄託】透過對舜瞽的描寫，作者寄寓了深沉的歷史反思。這段敘述不僅是客觀紀錄，更隱含了對國家興亡與人事變遷的警世意味。"}},{"id":"shiji_ch-1_p-20","chapterId":"shiji_ch-1","order":20,"canonicalText":"舜父瞽叟盲，而舜母死，瞽叟更娶妻而生象，象傲。瞽叟愛後妻子，常欲殺舜，舜避逃；及有小過，則受罪。順事父及後母與弟，日乾乾，便便，匪懈。","sentenceIds":["shiji_ch-1_p-20_s-1","shiji_ch-1_p-20_s-2","shiji_ch-1_p-20_s-3","shiji_ch-1_p-20_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"其大意是：舜，冀州的人們啊。舜耕歷山，漁雷澤，陶河濵，作什器於壽丘，就時於負夏。舜父瞽叟頑，母嚚，弟象傲，都欲殺舜。舜順適不失子道，兄弟孝慈。欲殺，不可得；即求，嘗在側。","analysis":"【主題與背景】本段「舜，冀州之人也。舜耕歷山...」立足於當時的時代脈絡，集中探討了舜於相關的核心議題。這反映出在歷史演變中，社會制度與思想的激烈碰撞。\\n【詞義與名物】在此，我們必須特別注意「弟欲」與「殺不」的時代含義。這些字眼不僅僅是字面上的意思，更包含了傳統禮法與社會結構的深層內涵。\\n【史家寄託】透過對舜於的描寫，作者寄寓了深沉的歷史反思。這段敘述不僅是客觀紀錄，更隱含了對國家興亡與人事變遷的警世意味。"}},{"id":"shiji_ch-1_p-21","chapterId":"shiji_ch-1","order":21,"canonicalText":"舜，冀州之人也。舜耕歷山，漁雷澤，陶河濱，作什器於壽丘，就時於負夏。舜父瞽叟頑，母嚚，弟象傲，皆欲殺舜。舜順適不失子道，兄弟孝慈。欲殺，不可得；即求，嘗在側。","sentenceIds":["shiji_ch-1_p-21_s-1","shiji_ch-1_p-21_s-2","shiji_ch-1_p-21_s-3","shiji_ch-1_p-21_s-4","shiji_ch-1_p-21_s-5","shiji_ch-1_p-21_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"虞舜是冀州人。舜年輕時曾在歷山開墾耕田，在雷澤湖泊捕魚，在黃河之濱燒製陶器，在壽丘打造各類生活日用木器雜物，在負夏市場經商趕集。舜的父親瞽叟頑劣暴戾，後母狡詐邪僻，弟弟象狂妄傲慢，全家皆三番五次密謀想要殺死虞舜。然而舜始終溫和順從竭力適應調和，絲毫不曾虧欠作為人子的至孝之道，對弟弟始終充滿兄長的友愛仁慈！當他們心生歹意企圖謀殺舜時，舜早已機敏走避讓他們無法下手；而一旦父母需要服侍召喚尋求舜時，舜立刻隨時恭敬侍奉在父母身邊！","analysis":"【題解與背景】\\n本段選自《史記》〈五帝本紀〉第 21 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「舜冀州之人也舜耕歷山漁雷澤陶河濱作什器於壽丘……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「舜」、「冀」、「州」、「人」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《史記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"shiji_ch-1_p-22","chapterId":"shiji_ch-1","order":22,"canonicalText":"舜年二十以孝聞。三十而帝堯問可用者，四嶽鹹薦虞舜，曰可。於是堯乃以二女妻舜以觀其內，使九男與處以觀其外。舜居媯汭，內行彌謹。堯二女不敢以貴驕事舜親戚，甚有婦道。堯九男皆益敦。舜耕歷山，歷山之人皆讓畔；漁雷澤，雷澤上人皆讓居；陶河濱，河濱器皆不苦窳。一年而所居成聚，二年成邑，三年成都。堯乃賜舜紵衣，與琴，為築倉廩，予牛羊。瞽叟尚復欲殺之，使舜上塗廩，瞽叟從下縱火焚廩。舜乃以兩笠自扞而下，去，得不死。後瞽叟又使舜穿井，舜穿井為匿空旁出。舜既入深，瞽叟與象共下土實井，舜從匿空出，去。瞽叟、象喜，以舜為已死。象曰：「本謀者象。」象與其父母分，於是曰：「舜妻堯二女，與琴，象取之。牛羊倉廩予父母。」象往入舜宮，舜在牀琴。象忪忪，恥相見。舜曰：「我思爾吏正！」舜復事瞽叟愛弟彌謹。","sentenceIds":["shiji_ch-1_p-22_s-1","shiji_ch-1_p-22_s-2","shiji_ch-1_p-22_s-3","shiji_ch-1_p-22_s-4","shiji_ch-1_p-22_s-5","shiji_ch-1_p-22_s-6","shiji_ch-1_p-22_s-7","shiji_ch-1_p-22_s-8","shiji_ch-1_p-22_s-9","shiji_ch-1_p-22_s-10","shiji_ch-1_p-22_s-11","shiji_ch-1_p-22_s-12","shiji_ch-1_p-22_s-13","shiji_ch-1_p-22_s-14","shiji_ch-1_p-22_s-15","shiji_ch-1_p-22_s-16","shiji_ch-1_p-22_s-17","shiji_ch-1_p-22_s-18","shiji_ch-1_p-22_s-19","shiji_ch-1_p-22_s-20","shiji_ch-1_p-22_s-21","shiji_ch-1_p-22_s-22","shiji_ch-1_p-22_s-23"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"虞舜二十歲時就因為卓越的孝行名揚天下。三十歲時帝堯向滿朝尋訪可堪託付天下的繼承人，四嶽大臣一致極力舉薦虞舜！於是帝堯把自己的兩個親生女兒娥皇與女英嫁給舜為妻，以此觀察他在家庭內部的品行操守（觀其內）；派遣九位親生兒子與舜朝夕相處共同共事，以此觀察他處理外部公務社會交往的才德（觀其外）！舜居住在媯水之濱，家庭操守內德更加謙遜嚴謹。帝堯的兩位金枝玉葉的公主在舜的感召下，絲毫不敢依仗皇室尊貴驕橫傲慢，極其恭敬地孝敬公婆事奉舜的親族，恪守崇高婦道！帝堯的九位皇子在舜的帶領下，為人品格全部日益純樸敦厚！舜在歷山耕田，歷山的農民深受感化互相謙讓田界田埂（皆讓畔）；舜在雷澤捕魚，雷澤的漁民爭相謙讓肥美居所；舜在黃河邊燒製陶器，黃河一帶生產的陶器全都堅固精美沒有粗製濫造的次品（皆不苦窳）！舜所居住生活的地方，第一年就聚集形成村落（成聚），第二年發展成市鎮（成邑），第三年繁榮成大都會（成都）！帝堯看在眼裡喜在心頭，賜給舜珍貴的細葛麻衣與古琴，為他修建了高大的糧倉，賞賜了大批牛羊。不料盲父瞽叟與弟弟象見財起意再度企圖謀害舜：瞽叟命令舜爬上高高的穀倉屋頂塗泥修繕，隨後瞽叟在地面暗中放火焚燒整個糧倉！舜臨危不亂，手持兩頂大斗笠當作翅膀滑翔降落到地面，安全撤離躲過死劫！後來瞽叟又命令舜下井淘井挖深水井，舜在挖井時機警地在井壁深處預先挖好了一條隱蔽的側向逃生通道（為匿空旁出）。當舜下到井底深處時，瞽叟與弟弟象在井口合力傾倒大量泥土石塊填埋水井，企圖將舜活埋！舜迅速從井壁側面的祕密通道爬出地面從容離去！瞽叟與象興高采烈，以為舜這次必定必死無疑了！弟弟象得意洋洋地說：當初策劃謀殺舜的主謀可是我象啊！象於是跟父母瓜分舜的遺產，大言不慚地說道：舜娶的帝堯兩個貌若天仙的女兒，以及帝堯賞賜的珍貴古琴，全都歸我象所有！牛羊牲畜與糧倉穀物就留給父母吧！象迫不及待大搖大擺走進舜的居所準備霸佔一切，走進寢殿一看，只見虞舜正神態自若安坐在牀上彈奏古琴！象頓時嚇得目瞪口呆驚慌失措（忪忪），羞愧難當無地自容！舜泰然自若微笑道：我正日夜思念牽掛著你前來輔佐我治理政務呢！自此之後，舜事奉盲父、關愛弟弟象更加恭敬真誠深厚！","analysis":"【題解與塗廩焚梯浚井掩土舜撫琴安坐象慚愧】本段為《五帝本紀》中最精彩傳神之戲劇性史詩名篇——帝堯二女九男考驗、歷山耕田一年成聚二年成邑三年成都、塗廩浚井兩度逃生、象入宮奪嫂見舜撫琴慚愧！\\n【詞義訓詁】「皆讓畔」：畔，田界；謙讓土地邊界；「不苦窳」：窳，音雨，粗劣；不粗製濫造；「兩笠自扞」：手持兩斗笠減緩落勢，古代降落傘雛形；「匿空旁出」：預挖側向逃生地道；「象忪忪」：忪忪，音松，驚恐不安、心虛慚愧。"}},{"id":"shiji_ch-1_p-23","chapterId":"shiji_ch-1","order":23,"canonicalText":"昔高陽氏有才子八人，世得其利，謂之「八愷」。高辛氏有才子八人，世謂之「八元」。此十六族者，世濟其美，不隕其名。至帝堯，堯未能舉。舜舉八愷，使主后土，以揆百事，莫不時序。舉八元，使布五教於四方，父義，母慈，兄友，弟恭，子孝，內平外成。","sentenceIds":["shiji_ch-1_p-23_s-1","shiji_ch-1_p-23_s-2","shiji_ch-1_p-23_s-3","shiji_ch-1_p-23_s-4","shiji_ch-1_p-23_s-5","shiji_ch-1_p-23_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"其大意是：昔帝鴻氏有不才子，掩義隱賊，好行兇慝，天下人謂的渾沌。少皡氏有不才子，毀信惡忠，崇飾惡言，天下謂的窮奇。顓頊氏有不才子，不可教訓，不知話言，天下謂的檮杌。此三族世憂的。至在堯，堯未能去。縉雲氏有不才子，貪於飲食，冒在貨賄，天下謂的饕餮。天下惡的，比的三兇。舜賔於四門，於是流四凶族，遷在四裔，用御螭魅，於是四門闢，言毋兇人們啊。","analysis":"【主題與背景】針對不天的現象，這段文獻「昔帝鴻氏有不才子，掩義隱...」提供了深刻的視角。其背後的歷史情境，凸顯了各方勢力對於國家治理的多元思考。\\n【詞義與名物】文中的「不天」代表了當時特有的社會階層或制度規範，而「下氏」則具體指涉了相關的器物與理念。這些詞彙精準呈現了古人的生活實態。\\n【史家寄託】這不僅是一段關於下氏的歷史記載，更體現了史學家對不天現象的深刻批判。字裡行間流露出對理想政治與社會秩序的嚮往。"}},{"id":"shiji_ch-1_p-24","chapterId":"shiji_ch-1","order":24,"canonicalText":"昔帝鴻氏有不才子，掩義隱賊，好行兇慝，天下謂之渾沌。少暤氏有不才子，毀信惡忠，崇飾惡言，天下謂之窮奇。顓頊氏有不才子，不可教訓，不知話言，天下謂之檮杌。此三族世憂之。至帝堯，堯未能去。縉雲氏有不才子，貪於飲食，冒於貨賄，天下謂之饕餮，天下惡之，比之三兇。舜賓於四門，乃流四兇族，遷於四裔，以禦螭魅，於是四門闢，言毋兇人也。","sentenceIds":["shiji_ch-1_p-24_s-1","shiji_ch-1_p-24_s-2","shiji_ch-1_p-24_s-3","shiji_ch-1_p-24_s-4","shiji_ch-1_p-24_s-5","shiji_ch-1_p-24_s-6","shiji_ch-1_p-24_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"從前帝鴻氏有個不成材的兒子，他掩蓋道義、暗中作惡，喜歡做兇狠邪惡的事，天下人稱他為渾沌。少皞氏也有個不成材的兒子，他毀棄信用、憎恨忠誠，喜歡編造與粉飾惡毒的謠言，天下人稱他為窮奇。顓頊氏也有個不成材的兒子，無法教導訓誡，聽不進好話，天下人稱他為檮杌。這三個家族讓世世代代的人都感到擔憂。到了帝堯的時代，堯也沒能除掉他們。縉雲氏也有個不成材的兒子，他極度貪戀喫喝，貪圖聚斂財物，天下人稱他為饕餮，天下人都厭惡他，把他和前面三個兇人並列。直到舜接受堯的任命，在四方城門迎接諸侯賓客時，才將這四凶家族流放，將他們驅逐到四方的邊遠地區，讓他們去抵禦深山老林中的妖魔鬼怪。從此之後，四方城門大開，據說天下再也沒有兇惡的壞人了。","analysis":"【訓詁與名物】「不才子」指不成材、品行惡劣的子弟。「掩義隱賊」指掩蓋仁義而暗藏害人之心。「兇慝」指兇惡邪僻。「話言」即善言、好話。「冒於貨賄」指貪圖財物。「四裔」指天下四方邊遠荒涼的地區。「螭魅」指山林中的魑魅魍魎等妖怪。\\n【章法與結構】本段採用了極為工整的排比結構來敘述「四凶」的由來。前四段分別以「某某氏有不才子」起頭，詳細描述其具體惡行（如掩義隱賊、毀信惡忠、貪於飲食等），最後結以天下人給予的惡名（渾沌、窮奇、檮杌、饕餮）。最後一段則集中敘述舜如何展現魄力，將四凶流放至邊疆，形成了先鋪墊危機、後解決問題的戲劇性結構。\\n【思想與義理】此段記載具有濃厚的神話色彩與政治象徵意義。「四凶」其實代表了上古社會中四股頑固、反動且破壞道德秩序的部族勢力。堯雖然聖明，但因過於仁慈或權力不足而「未能去」；而舜一上臺即果斷流放四凶，不僅展現了舜的政治魄力與果決，更象徵著「王道」在確立過程中，必須伴隨著對邪惡勢力的嚴厲懲處（流放邊疆以禦妖魔，亦是廢物利用的政治智慧）。這反映了儒家理想中「恩威並施」的聖王形象。"}},{"id":"shiji_ch-1_p-25","chapterId":"shiji_ch-1","order":25,"canonicalText":"舜入於大麓，烈風雷雨不迷，堯乃知舜之足授天下。堯老，使舜攝行天子政，巡狩。舜得舉用事二十年，而堯使攝政。攝政八年而堯崩。三年喪畢，讓丹朱，天下歸舜。","sentenceIds":["shiji_ch-1_p-25_s-1","shiji_ch-1_p-25_s-2","shiji_ch-1_p-25_s-3","shiji_ch-1_p-25_s-4","shiji_ch-1_p-25_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"虞舜接受帝堯最後一項神聖考驗：隻身深入原始險惡的太行山茫茫山麓密林之中（入於大麓），遭遇狂暴的狂風暴雨雷霆霹靂，舜心志堅定從容不迫絲毫沒有迷失方向！帝堯至此徹底確信虞舜的大智大勇與神聖天命完全足以託付整個天下！帝堯年事已高，正式命令虞舜代行天子政務主持巡狩天下。虞舜被舉薦參與國政二十年之後，帝堯正式令其全面攝政；攝政八年之後帝堯安詳崩逝。守滿三年國喪之後，舜主動退讓避居南河將帝位讓給丹朱，然而天下諸侯與萬民萬眾一心全部歸順擁戴虞舜！","analysis":"【題解與背景】\\n本段選自《史記》〈五帝本紀〉第 25 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「舜入於大麓烈風雷雨不迷堯乃知舜之足授天下堯老……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「舜」、「入」、「大」、「麓」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《史記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"shiji_ch-1_p-26","chapterId":"shiji_ch-1","order":26,"canonicalText":"此二十二人鹹成厥功：皋陶為大理，平，民各伏得其實；伯夷主禮，上下鹹讓；垂主工師，百工緻功；益主虞，山澤闢；棄主稷，百穀熟；契主司徒，百姓親；龍主賓客，遠人至；十二牧行而九州莫敢闢違；唯禹之功為大，披九山，通九川，陂九澤，決九河，定九州，各以其職來貢，不失厥宜。方五千裏，至於荒服。南撫交阯、北發，西戎、析支、渠廋、氐、羌，北山戎、發、息慎，東長、鳥夷，四海之內鹹戴帝舜之功。","sentenceIds":["shiji_ch-1_p-26_s-1","shiji_ch-1_p-26_s-2","shiji_ch-1_p-26_s-3","shiji_ch-1_p-26_s-4","shiji_ch-1_p-26_s-5","shiji_ch-1_p-26_s-6","shiji_ch-1_p-26_s-7","shiji_ch-1_p-26_s-8","shiji_ch-1_p-26_s-9","shiji_ch-1_p-26_s-10","shiji_ch-1_p-26_s-11"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"虞舜朝廷所任命的這二十二位內閣公卿重臣各自建立了卓越的歷史功勳：\\n皋陶擔任最高司法大法官（大理），執法公正嚴明平允，百姓服罪各得實情公道！伯夷掌管國家禮樂禮儀（主禮），朝野上下內外人人互相謙讓彬彬有禮！垂掌管國家工部工程（工師），天下百工各盡其能工程精湛！伯益掌管國家林業與自然生態（主虞），名山大川澤國得到全面開發保護！后稷（棄）掌管農業部（主稷），天下五穀豐登顆粒歸倉！契掌管教育部（司徒），天下萬民親睦團結！龍掌管外交接待部（主賓客），四方遠夷外邦使節源源不斷前來朝覲！十二州牧認真巡視履行職責，九州各地沒有任何人敢於違抗法紀法令！而在這全體重臣之中，唯獨大禹所立下的功勞最為崇高偉大！大禹劈開九座名山、疏通九條大江大河、修築九大湖泊堤壩、疏浚黃河九條支流入海、劃定天下九州疆界，使各地諸侯各按其本地物產進貢朝廷，絲毫不失其法度分寸！大漢天下疆域縱橫方圓五千裏，一直延伸到最遠的荒服邊陲：向南安撫交阯、北發，向西恩澤西戎、析支、渠廋、氐、羌等部族，向北威震山戎、息慎，向東撫育長夷、鳥夷，四海之內天下萬民無不崇敬歌戴帝舜與群臣的浩瀚聖德與蓋世功勳！","analysis":"【題解與背景】\\n本段選自《史記》〈五帝本紀〉第 26 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「此二十二人鹹成厥功皋陶為大理平民各伏得其實伯……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「此」、「二」、「十」、「二」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《史記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"shiji_ch-1_p-27","chapterId":"shiji_ch-1","order":27,"canonicalText":"舜年二十以孝聞，年三十堯舉之，年五十攝行天子事，年五十八堯崩，年六十一代堯踐帝位。踐帝位三十九年，南巡狩，崩於蒼梧之野。葬於江南九嶷，是為零陵。舜之踐帝位，載天子旗，往朝父瞽叟，夔夔齋慄，顧問敬肅，如子道。封弟象為諸侯。舜子商均亦不肖，舜乃預薦禹於天。十七年而崩。三年喪畢，禹亦乃讓商均，如舜讓丹朱之故。諸侯歸之，然後禹踐天子位。堯子丹朱，舜子商均，皆有疆土，以奉先祀。服其服，禮樂如之。以客見天子，天子弗臣，示不敢專也。","sentenceIds":["shiji_ch-1_p-27_s-1","shiji_ch-1_p-27_s-2","shiji_ch-1_p-27_s-3","shiji_ch-1_p-27_s-4","shiji_ch-1_p-27_s-5","shiji_ch-1_p-27_s-6","shiji_ch-1_p-27_s-7","shiji_ch-1_p-27_s-8","shiji_ch-1_p-27_s-9","shiji_ch-1_p-27_s-10","shiji_ch-1_p-27_s-11","shiji_ch-1_p-27_s-12"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"虞舜二十歲時就以崇高孝行聞名遐邇，三十歲時得到帝堯破格拔擢舉薦，五十歲時代理攝行天子最高政務，五十八歲時帝堯崩逝，六十一歲時正式接替帝堯踐祚登基即天子大位！虞舜在天子大位上執政整整三十九年，晚年親自前往南方巡狩視察，最終在蒼梧的曠野之中安詳逝世崩殂。遺體安葬在江南九嶷山，這就是著名的零陵！虞舜登基踐祚之後，乘坐著天子專屬車駕、插著天子旌旗回鄉朝拜看望盲父瞽叟；在老父親面前舜依然如同當年一樣戰戰兢兢小心翼翼（夔夔齋慄），言談舉止無比恭敬整肅，完全恪守著為人兒子的至孝之道！舜封賞弟弟象為一方諸侯。虞舜的兒子商均同樣資質不肖不具備統治天下的才德，虞舜於是預先將大禹正式推薦向上天祈告為繼承人。十七年後虞舜崩逝。守滿三年國喪之後，大禹同樣主動避居將王位讓給商均，正如當年虞舜讓給丹朱一樣！然而天下諸侯全部主動前來歸附大禹，大禹隨後才正式登基踐祚即天子位！帝堯的兒子丹朱、帝舜的兒子商均，朝廷皆封給他們專屬的封國疆土，用來祭祀先祖宗廟。允許他們在封國內穿戴先王特有的冠冕服飾，使用先王專屬的禮樂制度；當他們前來朝見天子時，天子以平等貴賓之禮相待而不把他們當作普通臣下看待（天子弗臣），以此向天下昭示天下乃天下人之天下、天子不敢專權自私！","analysis":"【題解與背景】\\n本段選自《史記》〈五帝本紀〉第 27 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「舜年二十以孝聞年三十堯舉之年五十攝行天子事年……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「舜」、「年」、「二」、「十」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《史記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"shiji_ch-1_p-28","chapterId":"shiji_ch-1","order":28,"canonicalText":"自黃帝至舜、禹，皆同姓而異其國號，以章明德。故黃帝為有熊，帝顓頊為高陽，帝嚳為高辛，帝堯為陶唐，帝舜為有虞。帝禹為夏後而別氏，姓姒氏。契為商，姓子氏。棄為周，姓姬氏。","sentenceIds":["shiji_ch-1_p-28_s-1","shiji_ch-1_p-28_s-2","shiji_ch-1_p-28_s-3","shiji_ch-1_p-28_s-4","shiji_ch-1_p-28_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"用現代漢語來說：太史公說：學的人們多稱五帝，尚了。然尚書獨載堯用來；並且百家言黃帝，他文不雅馴，薦紳先生難言的孔子所傳宰予問五帝德及帝繫姓，儒的人或不傳。餘嘗西至空桐，北過涿鹿，東漸於海，南浮江淮了，至長老都各往往稱黃帝、堯、舜的處，風教固殊焉，緫的不離古文的人近是。予觀春秋、國家語，他發明五帝德、帝繫姓章了，顧弟弗深考，他所表見都不虛。書缺有間了，他軼於是時時見於他說。非好學深思，心知他意，固難為淺見寡聞道啊。餘並論次，擇他言尤雅的人，故著為本紀書首。","analysis":"【主題與背景】在春秋戰國至秦漢的歷史進程中，本段文字「太史公曰：學者多稱五帝，...」主要講述了帝不與五書的關聯。它揭示了當時政治局勢下的特定風貌。\\n【詞義與名物】文中的「帝不」代表了當時特有的社會階層或制度規範，而「五書」則具體指涉了相關的器物與理念。這些詞彙精準呈現了古人的生活實態。\\n【史家寄託】藉由分析帝不與言見的互動，本段傳達了作者對歷史規律的洞察。這正是古人「以史為鑑」精神的具體展現，具有深遠的教育意義。"}},{"id":"shiji_ch-1_p-29","chapterId":"shiji_ch-1","order":29,"canonicalText":"太史公曰：學者多稱五帝，尚矣。然尚書獨載堯以來；而百家言黃帝，其文不雅馴，薦紳先生難言之。孔子所傳宰予問五帝德及帝系姓，儒者或不傳。餘嘗西至空桐，北過涿鹿，東漸於海，南浮江淮矣，至長老皆各往往稱黃帝、堯、舜之處，風教固殊焉，總之不離古文者近是。予觀春秋、國語，其發明五帝德、帝系姓章矣，顧弟弗深考，其所表見皆不虛。書缺有間矣，其軼乃時時見於他說。非好學深思，心知其意，固難為淺見寡聞者道也。餘並論次，擇其言尤雅者，故著為本紀書首。","sentenceIds":["shiji_ch-1_p-29_s-1","shiji_ch-1_p-29_s-2","shiji_ch-1_p-29_s-3","shiji_ch-1_p-29_s-4","shiji_ch-1_p-29_s-5","shiji_ch-1_p-29_s-6","shiji_ch-1_p-29_s-7","shiji_ch-1_p-29_s-8","shiji_ch-1_p-29_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"太史公司馬遷總結感嘆道：天下學者大多稱頌崇奉五帝時代，那確實年代極其久遠崇高了！然而《尚書》這部儒家經典僅僅從帝堯時代開始記載；而先秦諸子百家談論黃帝的言論，文辭大多荒誕不經缺乏雅正考據（不雅馴），以至於朝廷士大夫縉紳學者們往往難以啟齒談論。孔子當年傳授給弟子宰予的《五帝德》與《帝系姓》文獻，許多墨守成規的儒生甚至不肯傳習。我司馬遷曾親自漫遊天下：向西抵達空桐山，向北走過涿鹿古戰場，向東漫遊至浩瀚大海，向南泛舟橫渡長江與淮河；所到之處當地的耆老鄉紳們，往往爭相為我指點講述黃帝、帝堯、虞舜當年在當地的遺跡與傳說；各地民間風俗教化雖然互有差異，但總體核心事實與古文經籍的記載是高度吻合接近真實的！我深入研讀《春秋》與《國語》，發現這兩部經典所闡發證明的《五帝德》與《帝系姓》是極其昭著明白的，只不過後世學者不肯深入縝密考證罷了，其中所表彰顯現的史實全部絕非虛妄捏造！古代典籍雖然歷經年代久遠殘缺散佚（書缺有間），但那些散佚的真實史實依然時常散見在各家傳述文獻之中。如果不是真正熱愛學術、深思熟慮、在心靈深處深刻領會歷史大意的人，本來就很難向那些淺見寡聞的人講清楚這個道理啊！我全面綜合考訂排列各家史料，嚴格挑選其中最為雅正可信的篇章，因此鄭重撰寫了這篇《五帝本紀》，安放在《史記》一百三十篇的最卷首！","analysis":"【題解與太史公曰五帝本紀史學方法論宣言】本段為司馬遷最偉大的史學考據方法論宣言——田野實地考察（西至空桐、北過涿鹿、東漸於海、南浮江淮）與文獻互證（考信於六藝、擇其言尤雅者），為中華上古文明修訂權威信史！\\n【詞義訓詁】「不雅馴」：文辭荒誕不合儒家雅正規範；「薦紳」：通縉紳，插笏於紳帶之官員士大夫；「西至空桐東漸於海」：司馬遷二十歲壯遊天下之田野實地調查；「書缺有間」：古籍殘缺不全；「擇其言尤雅者著為本紀書首」：確立信史標準。"}},{"id":"shiji_ch-2_p-1","chapterId":"shiji_ch-2","order":1,"canonicalText":"夏禹，名曰文命。禹之父曰鯀，鯀之父曰帝顓頊，顓頊之父曰昌意，昌意之父曰黃帝。禹者，黃帝之玄孫而帝顓頊之孫也。禹之曾大父昌意及父鯀皆不得在帝位，為人臣。","sentenceIds":["shiji_ch-2_p-1_s-1","shiji_ch-2_p-1_s-2","shiji_ch-2_p-1_s-3","shiji_ch-2_p-1_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"其大意是：夏禹，名說文命。禹的父說鯀，鯀的父說帝顓頊，顓頊的父說昌意，昌意的父說黃帝。禹的人們，黃帝的玄孫並且帝顓頊的孫啊。禹的曾大父昌意及父鯀都不得在帝位，為人臣子。","analysis":"【主題與背景】在春秋戰國至秦漢的歷史進程中，本段文字「夏禹，名曰文命。禹之父曰...」主要講述了父帝與禹鯀的關聯。它揭示了當時政治局勢下的特定風貌。\\n【詞義與名物】在此，我們必須特別注意「禹鯀」與「顓頊」的時代含義。這些字眼不僅僅是字面上的意思，更包含了傳統禮法與社會結構的深層內涵。\\n【史家寄託】透過對父帝的描寫，作者寄寓了深沉的歷史反思。這段敘述不僅是客觀紀錄，更隱含了對國家興亡與人事變遷的警世意味。"}},{"id":"shiji_ch-2_p-2","chapterId":"shiji_ch-2","order":2,"canonicalText":"當帝堯之時，鴻水滔天，浩浩懷山襄陵，下民其憂。堯求能治水者，群臣四嶽皆曰鯀可。堯曰：「鯀為人負命毀族，不可。」四嶽曰：「等之未有賢於鯀者，願帝試之。」於是堯聽四嶽，用鯀治水。九年而水不息，功用不成。","sentenceIds":["shiji_ch-2_p-2_s-1","shiji_ch-2_p-2_s-2","shiji_ch-2_p-2_s-3","shiji_ch-2_p-2_s-4","shiji_ch-2_p-2_s-5","shiji_ch-2_p-2_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"用現代漢語來說：當帝堯的時，鴻水滔天，浩浩懷山襄陵，下民他憂。堯求能治水的人們，羣臣子四嶽都說鯀可。堯說：鯀為人負命毀族，不可。四嶽說：等的未有賢於鯀的人，願帝試的。於是堯聽四嶽，用鯀治水。九年並且水不息，功用不成。於是帝堯於是求人，更得舜。舜登用，攝行天子的政，廵狩。行視鯀的治水無狀，於是殛鯀於羽山用死。天下人都用舜的誅為是。於是舜舉鯀子禹，並且使續鯀的業。","analysis":"【主題與背景】針對鯀堯的現象，這段文獻「當帝堯之時，鴻水滔天，浩...」提供了深刻的視角。其背後的歷史情境，凸顯了各方勢力對於國家治理的多元思考。\\n【詞義與名物】文中的「鯀堯」代表了當時特有的社會階層或制度規範，而「水於」則具體指涉了相關的器物與理念。這些詞彙精準呈現了古人的生活實態。\\n【史家寄託】藉由分析鯀堯與是舜的互動，本段傳達了作者對歷史規律的洞察。這正是古人「以史為鑑」精神的具體展現，具有深遠的教育意義。"}},{"id":"shiji_ch-2_p-3","chapterId":"shiji_ch-2","order":3,"canonicalText":"堯崩，帝舜問四嶽曰：「有能成美堯之事者使居官？」皆曰：「伯禹為司空，可成美堯之功。」舜曰：「嗟，然！」乃命禹：「女平水土，維予之時，其懋哉！」禹拜稽首，讓於契、后稷、皋陶。舜曰：「往矣，汝諧！」","sentenceIds":["shiji_ch-2_p-3_s-1","shiji_ch-2_p-3_s-2","shiji_ch-2_p-3_s-3","shiji_ch-2_p-3_s-4","shiji_ch-2_p-3_s-5","shiji_ch-2_p-3_s-6","shiji_ch-2_p-3_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"帝堯駕崩後，帝舜詢問四方部落首領（四嶽）說：有誰能成就並發揚堯的偉大事業，讓他來擔任重臣？大家齊聲回答說：伯禹擔任司空，可以成就堯的偉大功業。舜感嘆地說：啊，對啊！於是舜就任命大禹說：你去平治水土，這正是我們最關鍵的時刻，你要好好努力啊！大禹跪拜叩頭，想把這個職位讓給契、后稷和皋陶。舜說：去吧，你最合適！","analysis":"【訓詁與名物】「四嶽」是古代掌管四方諸侯的官職或部落首領。「伯禹」即大禹。「司空」是古代掌管水土、營建等工程的官職。「嗟，然」是感嘆與贊同之詞。「女」通「汝」，你。「懋」指勉勵、努力。「稽首」是古代最敬之禮，以頭觸地。「讓」指辭讓、推辭。「諧」在此指適合、能勝任。\\n【章法與結構】本段透過對話生動地描繪了權力交接與人事任命的過程。首先是舜與四嶽的問答，凸顯了禹的威望與眾望所歸；接著是舜對禹的直接任命與期許；最後是禹的謙讓與舜的堅持（「往矣，汝諧！」）。層次分明，節奏緊湊，寥寥數語便刻畫出君臣之間的互動。\\n【思想與義理】這段記載深刻體現了儒家所推崇的上古聖王時代的政治理想。舜在用人時並非獨斷專行，而是徵詢「四嶽」的意見，展現了民主協商的色彩；而大禹在面對重任時，並非貪婪接受，而是謙遜地讓給其他賢臣（契、后稷、皋陶），展現了高尚的「讓賢」美德。最後舜的堅定任命，則確立了治水救民作為當時國家的首要任務。君明臣賢、相互推讓，構成了中國古代政治的最高道德典範。"}},{"id":"shiji_ch-2_p-4","chapterId":"shiji_ch-2","order":4,"canonicalText":"禹為人敏給克勤；其德不違，其仁可親，其言可信；聲為律，身為度，稱以出；亹亹穆穆，為綱為紀。","sentenceIds":["shiji_ch-2_p-4_s-1","shiji_ch-2_p-4_s-2","shiji_ch-2_p-4_s-3","shiji_ch-2_p-4_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"其大意是：禹為人們敏給克勤；他德不違，他仁可親，他言可信；聲為律，身為度，稱用出；亹亹穆穆，為綱為紀。","analysis":"【主題與背景】針對為可的現象，這段文獻「禹為人敏給克勤；其德不違...」提供了深刻的視角。其背後的歷史情境，凸顯了各方勢力對於國家治理的多元思考。\\n【詞義與名物】文中的「為可」代表了當時特有的社會階層或制度規範，而「亹穆」則具體指涉了相關的器物與理念。這些詞彙精準呈現了古人的生活實態。\\n【史家寄託】透過對為可的描寫，作者寄寓了深沉的歷史反思。這段敘述不僅是客觀紀錄，更隱含了對國家興亡與人事變遷的警世意味。"}},{"id":"shiji_ch-2_p-5","chapterId":"shiji_ch-2","order":5,"canonicalText":"禹乃遂與益、后稷奉帝命，命諸侯百姓興人徒以傅土，行山表木，定高山大川。禹傷先人父鯀功之不成受誅，乃勞身焦思，居外十三年，過家門不敢入。薄衣食，致孝於鬼神。卑宮室，致費於溝淢。陸行乘車，水行乘船，泥行乘橇，山行乘檋。左準繩，右規矩，載四時，以開九州，通九道，陂九澤，度九山。","sentenceIds":["shiji_ch-2_p-5_s-1","shiji_ch-2_p-5_s-2","shiji_ch-2_p-5_s-3","shiji_ch-2_p-5_s-4","shiji_ch-2_p-5_s-5","shiji_ch-2_p-5_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"大禹於是與伯益、后稷共同奉行帝舜的神聖命令，號令天下諸侯與萬民徵集發動民工徒役全力整治水土；巡行崇山峻嶺豎立木樁標記地形標高（行山表木），測量勘定各大高山與江河水系！大禹內心深為父親鯀治水不成反遭極刑處決而無比痛心哀傷（傷父鯀功不成受誅），於是不惜極度勞累自己的身軀、殫精竭慮苦思冥想（勞身焦思），長年奔波風餐露宿居住在野外整整十三年之久，三次經過自己的家門口也顧不上進去探望一眼（三過家門不敢入）！他日常喫穿極其粗劣簡陋（薄衣食），卻將祭祀鬼神祖先的祭品置辦得無比豐盛虔誠；自己居住的房屋極度矮小簡陋（卑宮室），卻把全部財富資金毫不吝惜地投入到農田水利與排灌溝渠建設之中（致費於溝淢）！陸地行軍乘坐馬車，水上巡視乘坐木船，泥濘沼澤行走乘坐泥橇，攀登高山行走腳踩帶鐵齒的登山木屐（山行乘檋）！左手拿著測量水準的準繩，右手握著畫圓畫方的規矩儀器，順應四時物候規律，全面開闢天下九州、疏通九條國家幹線交通水道、修築九大蓄水湖泊堤防、精確勘測丈量九大名山！","analysis":"【題解與大禹治水三過家門不敢入水陸四樴開九州】本段為中華民族自強不息、鞠躬盡瘁奉獻精神最偉大之歷史圖騰——大禹十三年治水三過家門不入、薄衣食卑宮室致費溝淢、乘車船橇檋！\\n【詞義訓詁】「居外十三年過家門不敢入」：三過家門而不入之千古奉獻典故；「溝淢」：淢，音緒，農田排水溝渠；「橇」：泥沼滑行工具；「檋」：音局，底安鐵齒便於登山之木屐（古代登山鞋）；「左準繩右規矩」：古代精密測繪工具。"}},{"id":"shiji_ch-2_p-6","chapterId":"shiji_ch-2","order":6,"canonicalText":"禹行自冀州始。冀州：既載壺口，治梁及岐。既修太原，至於嶽陽。覃懷致功，至於衡漳。其土白壤。賦中上錯，田上中。常山、衛、洹既治，漳水既道。其貢漆絲，篚織文。治夾右碣石，入於海。","sentenceIds":["shiji_ch-2_p-6_s-1","shiji_ch-2_p-6_s-2","shiji_ch-2_p-6_s-3","shiji_ch-2_p-6_s-4","shiji_ch-2_p-6_s-5","shiji_ch-2_p-6_s-6","shiji_ch-2_p-6_s-7","shiji_ch-2_p-6_s-8","shiji_ch-2_p-6_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"禹行自冀州始。冀州：旣載壺口，治梁及岐。旣修太原，至在嶽陽。覃懷致功，至於衡漳。他土白壤。賦上上錯，田中中，常、衞旣從，大陸旣為。鳥夷皮服。夾右碣石，入在海。","analysis":"【主題與背景】本段「禹行自冀州始。冀州：旣載...」立足於當時的時代脈絡，集中探討了旣冀相關的核心議題。這反映出在歷史演變中，社會制度與思想的激烈碰撞。\\n【詞義與名物】在此，我們必須特別注意「州至」與「上中」的時代含義。這些字眼不僅僅是字面上的意思，更包含了傳統禮法與社會結構的深層內涵。\\n【史家寄託】這不僅是一段關於州至的歷史記載，更體現了史學家對旣冀現象的深刻批判。字裡行間流露出對理想政治與社會秩序的嚮往。"}},{"id":"shiji_ch-2_p-7","chapterId":"shiji_ch-2","order":7,"canonicalText":"濟、河維沇州：九河既道，雷夏既澤，雍、沮會同，桑土既蠶，於是民得下丘居土。其土黑墳，草繇木條。田中下，賦貞，作十有三載乃同。其貢漆絲，篚織文。浮於濟、漯，通於河。","sentenceIds":["shiji_ch-2_p-7_s-1","shiji_ch-2_p-7_s-2","shiji_ch-2_p-7_s-3","shiji_ch-2_p-7_s-4","shiji_ch-2_p-7_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"用現代漢語來說：濟、河維沇州：九河旣道，雷夏旣澤，雍、沮會同，桑土旣蠶，於是民得下丘居土。他土黑墳，草繇木條。田中下，賦貞，作十有三年於是同。他貢漆絲，他篚織文。浮於濟、漯，通於河。","analysis":"【主題與背景】在春秋戰國至秦漢的歷史進程中，本段文字「濟、河維沇州：九河旣道，...」主要講述了河旣與土於的關聯。它揭示了當時政治局勢下的特定風貌。\\n【詞義與名物】文中的「河旣」代表了當時特有的社會階層或制度規範，而「土於」則具體指涉了相關的器物與理念。這些詞彙精準呈現了古人的生活實態。\\n【史家寄託】藉由分析河旣與濟同的互動，本段傳達了作者對歷史規律的洞察。這正是古人「以史為鑑」精神的具體展現，具有深遠的教育意義。"}},{"id":"shiji_ch-2_p-8","chapterId":"shiji_ch-2","order":8,"canonicalText":"海岱維青州：堣夷既略，濰、淄其道。其土白墳，海濱廣潟，厥田斥鹵。田上下，賦中上。厥貢鹽絺，海物惟錯，岱畎絲枲鉛松怪石，萊夷為牧，篚檿絲。浮於汶，達於濟。","sentenceIds":["shiji_ch-2_p-8_s-1","shiji_ch-2_p-8_s-2","shiji_ch-2_p-8_s-3","shiji_ch-2_p-8_s-4","shiji_ch-2_p-8_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"其大意是：海岱維青州：堣夷旣略，濰、淄旣道。他土白墳，海濵廣潟，厥田斥鹵。田上下，賦中上。厥貢鹽絺，海物維錯，岱畎絲、枲、鈆、松、怪石，萊夷為牧，他篚酓絲。浮於汶，通於濟。","analysis":"【主題與背景】本段「海岱維青州：堣夷旣略，濰...」立足於當時的時代脈絡，集中探討了海岱相關的核心議題。這反映出在歷史演變中，社會制度與思想的激烈碰撞。\\n【詞義與名物】在此，我們必須特別注意「維夷」與「旣厥」的時代含義。這些字眼不僅僅是字面上的意思，更包含了傳統禮法與社會結構的深層內涵。\\n【史家寄託】這不僅是一段關於維夷的歷史記載，更體現了史學家對海岱現象的深刻批判。字裡行間流露出對理想政治與社會秩序的嚮往。"}},{"id":"shiji_ch-2_p-9","chapterId":"shiji_ch-2","order":9,"canonicalText":"海岱及淮維徐州：淮、沂其治，蒙、羽其藝。大野既都，東原底平。其土赤埴墳，草木漸包。其田上中，賦中中。厥貢維土五色，羽畎夏翟，嶧陽孤桐，泗濱浮磬，淮夷蠙珠蚳魚。浮於淮、泗，達於河。","sentenceIds":["shiji_ch-2_p-9_s-1","shiji_ch-2_p-9_s-2","shiji_ch-2_p-9_s-3","shiji_ch-2_p-9_s-4","shiji_ch-2_p-9_s-5","shiji_ch-2_p-9_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"其大意是：海岱及淮維徐州：淮、沂他治，蒙、羽他藝。大野旣都，東原厎平。他土赤埴墳，草木漸包。他田上中，賦中中。貢維土五色，羽畎夏翟，嶧陽孤桐，泗濵浮磬，淮夷蠙珠臮魚，他篚玄纖縞。浮在淮、泗，通在河。","analysis":"【主題與背景】在春秋戰國至秦漢的歷史進程中，本段文字「海岱及淮維徐州：淮、沂其...」主要講述了淮中與維羽的關聯。它揭示了當時政治局勢下的特定風貌。\\n【詞義與名物】作者使用了「淮中」等關鍵字眼，這在古代文獻中通常用來描述特定的歷史名物。透過「維羽」的使用，文章進一步勾勒出當時的文化特色。\\n【史家寄託】透過對淮中的描寫，作者寄寓了深沉的歷史反思。這段敘述不僅是客觀紀錄，更隱含了對國家興亡與人事變遷的警世意味。"}},{"id":"shiji_ch-2_p-10","chapterId":"shiji_ch-2","order":10,"canonicalText":"淮海維揚州：彭蠡既都，陽鳥所居。三江既入，震澤致定。竹箭既布。其草惟夭，其木惟喬，其土塗泥。田下下，賦下上雜。厥貢惟金三品，瑤、琨、竹箭，齒、革、羽、毛，島夷卉服，厥篚織貝，厥包橘、柚，錫貢。沿於江、海，達於淮、泗。","sentenceIds":["shiji_ch-2_p-10_s-1","shiji_ch-2_p-10_s-2","shiji_ch-2_p-10_s-3","shiji_ch-2_p-10_s-4","shiji_ch-2_p-10_s-5","shiji_ch-2_p-10_s-6","shiji_ch-2_p-10_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"其大意是：淮海維揚州：彭蠡旣都，陽鳥所居。三江旣入，震澤致定。竹箭旣布。他草惟夭，他木惟喬，他土塗泥。田下下，賦下上上雜。貢金三品，瑤、琨、竹箭，齒、革、羽、旄，島夷卉服，他篚織貝，他包橘、柚錫貢。均江海，通淮、泗。","analysis":"【主題與背景】本段「淮海維揚州：彭蠡旣都，陽...」立足於當時的時代脈絡，集中探討了旣下相關的核心議題。這反映出在歷史演變中，社會制度與思想的激烈碰撞。\\n【詞義與名物】作者使用了「旣下」等關鍵字眼，這在古代文獻中通常用來描述特定的歷史名物。透過「淮海」的使用，文章進一步勾勒出當時的文化特色。\\n【史家寄託】透過對旣下的描寫，作者寄寓了深沉的歷史反思。這段敘述不僅是客觀紀錄，更隱含了對國家興亡與人事變遷的警世意味。"}},{"id":"shiji_ch-2_p-11","chapterId":"shiji_ch-2","order":11,"canonicalText":"荊及衡陽維荊州：江、漢朝宗於海。九江甚中，沱、涔已道，雲土、夢為治。其土塗泥。田下中，賦上下。厥貢羽、毛、齒、革，金三品，杶、幹、栝、柏，礪、砥、砮、丹，維箘、簵、楛，三國致貢：其名包匜菁茅，厥篚玄纁，編瑀，九江納錫大龜。浮於江、沱、涔、漢，逾於洛，至於南河。","sentenceIds":["shiji_ch-2_p-11_s-1","shiji_ch-2_p-11_s-2","shiji_ch-2_p-11_s-3","shiji_ch-2_p-11_s-4","shiji_ch-2_p-11_s-5","shiji_ch-2_p-11_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"其大意是：荊及衡陽維荊州：江、漢朝宗在海。九江甚中，沱、涔已道，雲土、夢為治。他土塗泥。田下中，賦上下。貢羽、旄、齒、革，金三品，杶、榦、栝、柏，礪、砥、砮、丹，維箘簵、楛，三國家致貢他名，包匭菁茅，他篚玄纁璣組，九江入賜大龜。浮於江、沱，涔於漢，踰在雒，至在南河。","analysis":"【主題與背景】本段「荊及衡陽維荊州：江、漢朝...」立足於當時的時代脈絡，集中探討了江荊相關的核心議題。這反映出在歷史演變中，社會制度與思想的激烈碰撞。\\n【詞義與名物】作者使用了「江荊」等關鍵字眼，這在古代文獻中通常用來描述特定的歷史名物。透過「維漢」的使用，文章進一步勾勒出當時的文化特色。\\n【史家寄託】這不僅是一段關於維漢的歷史記載，更體現了史學家對江荊現象的深刻批判。字裡行間流露出對理想政治與社會秩序的嚮往。"}},{"id":"shiji_ch-2_p-12","chapterId":"shiji_ch-2","order":12,"canonicalText":"荊河惟豫州：伊、雒、瀍、澗既入於河，滎播既都，道荷澤，被明都。其土壤，下土墳壚。田中上，賦上中。厥貢漆、枲，絺、紵，厥篚纖、纊，錫貢磬錯。浮於洛，達於河。","sentenceIds":["shiji_ch-2_p-12_s-1","shiji_ch-2_p-12_s-2","shiji_ch-2_p-12_s-3","shiji_ch-2_p-12_s-4","shiji_ch-2_p-12_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"荊河惟豫州：伊、雒、瀍、澗旣入於河，滎播旣都，道荷澤，被明都。他土壤，下土墳壚。田中上，賦雜上中。貢漆、絲、絺、紵，他篚纖絮，錫貢磬錯。浮於雒，達於河。","analysis":"【主題與背景】針對河於的現象，這段文獻「荊河惟豫州：伊、雒、瀍、...」提供了深刻的視角。其背後的歷史情境，凸顯了各方勢力對於國家治理的多元思考。\\n【詞義與名物】文中的「河於」代表了當時特有的社會階層或制度規範，而「雒旣」則具體指涉了相關的器物與理念。這些詞彙精準呈現了古人的生活實態。\\n【史家寄託】這不僅是一段關於雒旣的歷史記載，更體現了史學家對河於現象的深刻批判。字裡行間流露出對理想政治與社會秩序的嚮往。"}},{"id":"shiji_ch-2_p-13","chapterId":"shiji_ch-2","order":13,"canonicalText":"華陽黑水惟梁州：汶、嶓既藝，沱、涔既道，蔡、蒙旅平，和夷厎績。其土青驪。田下上，賦下中三錯。厥貢璆、鐵、銀、鏤、砮、磬，熊、羆、狐、狸、織皮，西傾因桓是來，浮於潛，逾於沔，入於渭，亂於河。","sentenceIds":["shiji_ch-2_p-13_s-1","shiji_ch-2_p-13_s-2","shiji_ch-2_p-13_s-3","shiji_ch-2_p-13_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"用現代漢語來說：華陽黑水惟梁州：汶、嶓旣蓺，沱、涔旣道，蔡、蒙旅平，和夷厎績。他土青驪。田下上，賦下中三錯。貢璆、鐵、銀、鏤、砮、磬，熊、羆、狐、貍、織皮。西傾因桓是來，浮在潛，踰在沔，入在渭，亂在河。","analysis":"【主題與背景】本段「華陽黑水惟梁州：汶、嶓旣...」立足於當時的時代脈絡，集中探討了旣下相關的核心議題。這反映出在歷史演變中，社會制度與思想的激烈碰撞。\\n【詞義與名物】在此，我們必須特別注意「華陽」與「黑水」的時代含義。這些字眼不僅僅是字面上的意思，更包含了傳統禮法與社會結構的深層內涵。\\n【史家寄託】這不僅是一段關於華陽的歷史記載，更體現了史學家對旣下現象的深刻批判。字裡行間流露出對理想政治與社會秩序的嚮往。"}},{"id":"shiji_ch-2_p-14","chapterId":"shiji_ch-2","order":14,"canonicalText":"黑水西河惟雍州：弱水既西，涇屬渭汭。漆、沮既從，灃水所同。荊、岐已旅，終南、敦物至於鳥鼠。原隰底績，至於都野。三危既度，三苗大序。其土黃壤。田上上，賦中下。厥貢球、琳、琅玕。浮於積石，至於龍門西河，會於渭汭。","sentenceIds":["shiji_ch-2_p-14_s-1","shiji_ch-2_p-14_s-2","shiji_ch-2_p-14_s-3","shiji_ch-2_p-14_s-4","shiji_ch-2_p-14_s-5","shiji_ch-2_p-14_s-6","shiji_ch-2_p-14_s-7","shiji_ch-2_p-14_s-8","shiji_ch-2_p-14_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"其大意是：黑水西河惟雍州：弱水旣西，涇屬渭汭。漆、沮旣從，灃水所同。荊、岐已旅，終南、敦物至在鳥鼠。原隰厎績，至在都野。三危旣度，三苗大序。他土黃壤。田上上，賦中下。貢璆、琳、琅玕。浮於積石，至於龍門西河，會在渭汭。織皮昆侖、析支、渠搜，西戎即序。","analysis":"【主題與背景】針對西水的現象，這段文獻「黑水西河惟雍州：弱水旣西...」提供了深刻的視角。其背後的歷史情境，凸顯了各方勢力對於國家治理的多元思考。\\n【詞義與名物】文中的「西水」代表了當時特有的社會階層或制度規範，而「旣至」則具體指涉了相關的器物與理念。這些詞彙精準呈現了古人的生活實態。\\n【史家寄託】這不僅是一段關於旣至的歷史記載，更體現了史學家對西水現象的深刻批判。字裡行間流露出對理想政治與社會秩序的嚮往。"}},{"id":"shiji_ch-2_p-15","chapterId":"shiji_ch-2","order":15,"canonicalText":"道九山：汧及岐至於荊山，踰於河；壺口、雷首至於太嶽；砥柱、析城至於王屋；太行、常山至於碣石，入於海；西傾、朱圉、鳥鼠至於太華；熊耳、外方、桐柏至於負尾；嶓冢至於荊山；內方至於大別；汶山之陽至於衡山，過九江，至於敷淺原。","sentenceIds":["shiji_ch-2_p-15_s-1","shiji_ch-2_p-15_s-2","shiji_ch-2_p-15_s-3","shiji_ch-2_p-15_s-4","shiji_ch-2_p-15_s-5","shiji_ch-2_p-15_s-6","shiji_ch-2_p-15_s-7","shiji_ch-2_p-15_s-8","shiji_ch-2_p-15_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"其大意是：道九山：汧及岐至在荊山，踰在河；壺口、雷首至在太嶽；砥柱、析城至在王屋；太行、常山至在碣石，入在海；西傾、朱圉、鳥鼠至在太華；熊耳、外方、桐柏至在負尾；道嶓冢，至在荊山；內方至在大別；汶山的陽至在衡山，過九江，至在敷淺原。","analysis":"【主題與背景】本段「道九山：汧及岐至於荊山，...」立足於當時的時代脈絡，集中探討了至山相關的核心議題。這反映出在歷史演變中，社會制度與思想的激烈碰撞。\\n【詞義與名物】在此，我們必須特別注意「太道」與「九荊」的時代含義。這些字眼不僅僅是字面上的意思，更包含了傳統禮法與社會結構的深層內涵。\\n【史家寄託】這不僅是一段關於太道的歷史記載，更體現了史學家對至山現象的深刻批判。字裡行間流露出對理想政治與社會秩序的嚮往。"}},{"id":"shiji_ch-2_p-16","chapterId":"shiji_ch-2","order":16,"canonicalText":"道九川：弱水至於合黎，餘波入於流沙。道黑水，至於三危，入於南海。道河積石，至於龍門，南至華陰，東至砥柱，又東至盟津，過洛汭，至於大伾，北過降水，至於大陸，北播為九河，同為逆河，入於海。道沇水，東為濟，入於河，泆為滎，東出陶丘北，又東至於荷澤，東南會於汶，又東北入於海。道淮自桐柏，東會於泗、沂，東入於海。道江自岷山，東別為沱，又東至於澧，過九江，至於東陵，東迤北會於匯，東為中江，入於海。","sentenceIds":["shiji_ch-2_p-16_s-1","shiji_ch-2_p-16_s-2","shiji_ch-2_p-16_s-3","shiji_ch-2_p-16_s-4","shiji_ch-2_p-16_s-5","shiji_ch-2_p-16_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"道九川：弱水至於合黎，餘波入於流沙。道黑水，至在三危，入在南海。道河積石，至在龍門，南至華陰，東至砥柱，又東至在盟津，東過雒汭，至在大邳，北過降水，至在大陸，北播為九河，同為逆河，入在海。嶓冢道瀁，東流為漢，又東為蒼浪的水，過三澨，入在大別，南入在江，東匯澤為彭蠡，東為北江，入在海。汶山道江，東別為沱，又東至在醴，過九江，至在東陵，東迆北會在匯，東為中江，入在海。道沇水，東為濟，入在河，泆為滎，東出陶丘北，又東至在荷，又東北會在汶，又東北入在海。道淮自桐栢，東會在泗、沂，東入在海。道渭自鳥鼠同穴，東會在灃，又東北至在涇，東過漆、沮，入在河。道雒自熊耳，東北會在澗、瀍，又東會在伊，東北入在河。","analysis":"【主題與背景】針對東至的現象，這段文獻「道九川：弱水至於合黎，餘...」提供了深刻的視角。其背後的歷史情境，凸顯了各方勢力對於國家治理的多元思考。\\n【詞義與名物】文中的「東至」代表了當時特有的社會階層或制度規範，而「入北」則具體指涉了相關的器物與理念。這些詞彙精準呈現了古人的生活實態。\\n【史家寄託】這不僅是一段關於入北的歷史記載，更體現了史學家對東至現象的深刻批判。字裡行間流露出對理想政治與社會秩序的嚮往。"}},{"id":"shiji_ch-2_p-17","chapterId":"shiji_ch-2","order":17,"canonicalText":"於是九州攸同，四奧既居，九山刊旅，九川滌原，九澤既陂，四海會同。六府甚修，眾土交正，致慎財賦，鹹則三壤，成賦中邦。錫土姓，祗臺德先，不距朕行。","sentenceIds":["shiji_ch-2_p-17_s-1","shiji_ch-2_p-17_s-2","shiji_ch-2_p-17_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"其大意是：於是九州攸同，四奧旣居，九山栞旅，九川滌原，九澤旣陂，四海會同。六府甚修，衆土交正，致慎財賦，鹹那麼三壤成賦。中國家賜土姓：祗臺德先，不距朕行。","analysis":"【主題與背景】在春秋戰國至秦漢的歷史進程中，本段文字「於是九州攸同，四奧旣居，...」主要講述了九同與四旣的關聯。它揭示了當時政治局勢下的特定風貌。\\n【詞義與名物】文中的「九同」代表了當時特有的社會階層或制度規範，而「四旣」則具體指涉了相關的器物與理念。這些詞彙精準呈現了古人的生活實態。\\n【史家寄託】透過對九同的描寫，作者寄寓了深沉的歷史反思。這段敘述不僅是客觀紀錄，更隱含了對國家興亡與人事變遷的警世意味。"}},{"id":"shiji_ch-2_p-18","chapterId":"shiji_ch-2","order":18,"canonicalText":"令天子之國以外五百里甸服：百里賦納總，二百里納銍，三百里納秸服，四百里粟，五百里米。甸服外五百里侯服：百里採，二百里男邦，三百里諸侯。侯服外五百里綏服：三百里揆文教，二百里奮武衛。綏服外五百里要服：三百里夷，二百里蔡。要服外五百里荒服：三百里蠻，二百里流。","sentenceIds":["shiji_ch-2_p-18_s-1","shiji_ch-2_p-18_s-2","shiji_ch-2_p-18_s-3","shiji_ch-2_p-18_s-4","shiji_ch-2_p-18_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"其大意是：令天子的國家用外五百里甸服：百里賦納緫，二百里納銍，三百里納秸服，四百里粟，五百里米。甸服外五百里侯服：百里採，二百里任國，三百里諸侯。侯服外五百里綏服：三百里揆文教，二百里奮武衞。綏服外五百里要服：三百里夷，二百里蔡。要服外五百里荒服：三百里蠻，二百里流。","analysis":"【主題與背景】在春秋戰國至秦漢的歷史進程中，本段文字「令天子之國以外五百里甸服...」主要講述了百里與服五的關聯。它揭示了當時政治局勢下的特定風貌。\\n【詞義與名物】在此，我們必須特別注意「服五」與「外二」的時代含義。這些字眼不僅僅是字面上的意思，更包含了傳統禮法與社會結構的深層內涵。\\n【史家寄託】這不僅是一段關於服五的歷史記載，更體現了史學家對百里現象的深刻批判。字裡行間流露出對理想政治與社會秩序的嚮往。"}},{"id":"shiji_ch-2_p-19","chapterId":"shiji_ch-2","order":19,"canonicalText":"東漸於海，西被於流沙，朔、南暨：聲教訖於四海。於是帝錫禹玄圭，以告成功於天下。天下於是太平治。","sentenceIds":["shiji_ch-2_p-19_s-1","shiji_ch-2_p-19_s-2","shiji_ch-2_p-19_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"中華文明的大一統疆域與德政：向東浸潤延伸至浩瀚大海，向西覆蓋遍及廣袤流沙沙漠，向北（朔方）與向南無不全面抵達：王道的威德聲望與道德教化徹底通達傳遍四海極端邊陲！在這神聖歷史時刻，帝舜親自向大禹賜予象徵無上治水大功的玄色玉圭（玄圭），以此向全天下黎民百姓正式宣告平定水土偉業大功告成！天下自此步入政治清明、江山永固的盛世太平大治！","analysis":"【題解與背景】\\n本段選自《史記》〈夏本紀〉第 48 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「東漸於海西被於流沙朔南暨聲教訖於四海於是帝錫……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「東」、「漸」、「海」、「西」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《史記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"shiji_ch-2_p-20","chapterId":"shiji_ch-2","order":20,"canonicalText":"皋陶作士以理民。帝舜朝，禹、伯夷、皋陶相與語帝前。皋陶述其謀曰：「信其道德，謀明輔和。」禹曰：「然，如何？」皋陶曰：「於！慎其修身思長，敦序九族，眾明高翼，近者大興，遠者往迎。」禹拜美言，曰：「然。」皋陶曰：「於！在知人，在安民。」禹曰：「籲！皆若此，唯帝其難之。知人則哲，能官人；安民則惠，黎庶懷之。能哲而惠，何憂乎驩兜，何遷乎三苗，何畏乎巧言令色孔壬？」","sentenceIds":["shiji_ch-2_p-20_s-1","shiji_ch-2_p-20_s-2","shiji_ch-2_p-20_s-3","shiji_ch-2_p-20_s-4","shiji_ch-2_p-20_s-5","shiji_ch-2_p-20_s-6","shiji_ch-2_p-20_s-7","shiji_ch-2_p-20_s-8","shiji_ch-2_p-20_s-9","shiji_ch-2_p-20_s-10","shiji_ch-2_p-20_s-11","shiji_ch-2_p-20_s-12","shiji_ch-2_p-20_s-13","shiji_ch-2_p-20_s-14","shiji_ch-2_p-20_s-15"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"皋陶出任最高司法長官（作士）治理教化萬民。在帝舜召開的朝會上，大禹、伯夷與皋陶在帝舜面前共同研討國家治理大略。皋陶闡述他的治國謀略道：堅定篤信道德的力量，決策明智清醒，輔佐的大臣協調和睦！大禹問道：講得好，具體應當如何落實呢？皋陶說：啊！最關鍵在於統治者必須日夜審慎修養自身品德、深謀遠慮（慎修身思長），篤厚整飭團結九族親屬；滿朝賢臣明智高瞻遠矚相互輔佐（眾明高翼），這樣近處的百姓自然萬民歸心欣欣向榮，遠方的部族自會主動前來投奔歸附！大禹下拜讚賞這番美德善言道：確實如此！皋陶進一步指出：啊！最高治理的核心，全在於能夠精準識別人臉人心（在知人），全在於能夠讓黎民百姓安居樂業（在安民）！大禹感慨萬分地說道：唉！如果真能完全做到這兩點，縱然是古代至高聖帝堯舜也會感到極端不易啊！能夠真正知人善任，就是最至高的大智大哲（知人則哲），就能給每個人安排最合適的官位（能官人）；能夠讓百姓安居樂業，就是最浩瀚的仁慈恩惠（安民則惠），普天下的黎民百姓無不打心底裡由衷感恩懷念！如果統治者真能做到睿哲通達而且惠澤黎民，又何必憂慮讙兜作亂呢？何必強制流放三苗呢？又何必畏懼那些巧言令色、偽善極惡的奸佞小人孔壬呢？","analysis":"【題解與背景】\\n本段選自《史記》〈夏本紀〉第 49 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「皋陶作士以理民帝舜朝禹伯夷皋陶相與語帝前皋陶……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「皋」、「陶」、「作」、「士」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《史記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"shiji_ch-2_p-21","chapterId":"shiji_ch-2","order":21,"canonicalText":"帝舜謂禹曰：「女亦昌言。」禹拜曰：「於，予何言！予思日孳孳。」皋陶難禹曰：「何謂孳孳？」禹曰：「鴻水滔天，浩浩懷山襄陵，下民皆惑於水。予陸行乘車，水行乘舟，泥行乘橇，山行乘檋，行山刊木。與益予眾庶稻鮮食。以予導九川致四海，振興麟鳳，益稷播奏庶艱食鮮食。懋遷有無化居。蒸民乃粒，萬國作乂。」皋陶曰：「然，此而美也。」","sentenceIds":["shiji_ch-2_p-21_s-1","shiji_ch-2_p-21_s-2","shiji_ch-2_p-21_s-3","shiji_ch-2_p-21_s-4","shiji_ch-2_p-21_s-5","shiji_ch-2_p-21_s-6","shiji_ch-2_p-21_s-7","shiji_ch-2_p-21_s-8","shiji_ch-2_p-21_s-9","shiji_ch-2_p-21_s-10","shiji_ch-2_p-21_s-11","shiji_ch-2_p-21_s-12"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"帝舜謂禹說：女亦昌言。禹拜說：於，予何言！予思日孳孳。臯陶難禹說：何謂孳孳？禹說：鴻水滔天，浩浩懷山襄陵，下民都服於水。予陸行乘車，水行乘舟，泥行乘橇，山行乘檋，行山栞木。和益予衆庶稻鮮食。用決九川致四海，浚畎澮致的川。和稷予衆庶難得的食。食少，調有餘補不足，徙居。衆民於是定，萬國家為治。臯陶說：然，此並且美啊。","analysis":"【主題與背景】本段「帝舜謂禹曰：「女亦昌言。...」立足於當時的時代脈絡，集中探討了予行相關的核心議題。這反映出在歷史演變中，社會制度與思想的激烈碰撞。\\n【詞義與名物】在此，我們必須特別注意「禹孳」與「乘水」的時代含義。這些字眼不僅僅是字面上的意思，更包含了傳統禮法與社會結構的深層內涵。\\n【史家寄託】這不僅是一段關於禹孳的歷史記載，更體現了史學家對予行現象的深刻批判。字裡行間流露出對理想政治與社會秩序的嚮往。"}},{"id":"shiji_ch-2_p-22","chapterId":"shiji_ch-2","order":22,"canonicalText":"禹曰：「於，帝！慎乃在位，安爾止。輔德，天下大應。清意以昭待上帝命，天其重命用休。」帝曰：「籲！臣哉，臣哉！臣作朕股肱耳目。予欲左右有民，女隨；予欲宣力四方，女為；予欲觀古人之象，日月星辰，山龍華蟲作會，宗彝藻火粉米黼黻，希繡，以五采彰施於五色，作服，女明之；予欲聞六律五聲八音，察神人以歌，女聽。予違，汝弼，汝無面從退有後言。敬四鄰，庶頑讒說，若不在時，侯以明之，撻以記之，書用識之，欲並生故也。德懋懋官，功懋懋賞。萬邦黎獻，共帝祥。惟德時敘，罔或逆亂。」","sentenceIds":["shiji_ch-2_p-22_s-1","shiji_ch-2_p-22_s-2","shiji_ch-2_p-22_s-3","shiji_ch-2_p-22_s-4","shiji_ch-2_p-22_s-5","shiji_ch-2_p-22_s-6","shiji_ch-2_p-22_s-7","shiji_ch-2_p-22_s-8","shiji_ch-2_p-22_s-9","shiji_ch-2_p-22_s-10","shiji_ch-2_p-22_s-11","shiji_ch-2_p-22_s-12","shiji_ch-2_p-22_s-13","shiji_ch-2_p-22_s-14","shiji_ch-2_p-22_s-15","shiji_ch-2_p-22_s-16","shiji_ch-2_p-22_s-17"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"大禹進一步向帝舜進諫道：啊，陛下！請您審慎對待自己所肩負的天子大位，安守於最純粹的王道仁德之中！以身作則弘揚崇高美德，天下黎民自會無比熱烈地起而響應！保持心志的極致純潔清澈，以此光明磊落承接皇天上帝的神聖天命，上天必定會反覆降下無窮的美好福祉與祥瑞！帝舜感慨讚嘆道：唉！大臣啊，真正的大臣啊！諸位賢臣正是寡人的胳膊大腿（股肱）與眼睛耳朵（耳目）啊！寡人想要護佑安撫天下萬民，你們便緊密跟隨輔佐；寡人想要將政令德教宣示傳播於四方，你們便全力貫徹實施；寡人想要考察古代聖王的禮制服飾圖像——日、月、星辰、羣山、蛟龍、錦雉等繡制在朝服之上，宗廟祭尊、水草、烈火、白米、黑白相間的斧形黼紋、青黑相間的黻紋，以五彩斑斕的絲線刺繡施加在五色禮服之上，制定各級官員法定服制，你們便將其彰明宣示天下；寡人想要聆聽六律、五聲、八音的和諧樂章，體察神明與黎民的真情謳歌，你們便替寡人傾聽採納！當寡人出現過失差錯之際，你們應當直言匡正糾偏輔弼（汝弼），你們絕不可當面阿諛順從退朝後卻私下妄加非議抱怨（無面從退有後言）！恭敬對待四方鄰邦，對於那些愚頑不化、散佈讒言毀謗的刁民，若不能順應道德法令，便通過射禮考察彰明他們的德行，用刑杖敲擊記過鞭策他們，用官方檔案登載記錄他們的罪過，這都是為了能夠讓他們改過自新共同生存繁衍啊！德行崇高的官員應當勉勵晉升其官爵（德懋懋官），戰功卓著的將士應當勉勵重重賞賜（功懋懋賞）！天下萬邦的賢能豪傑（黎獻），共同輔佐成就天子的祥和盛世！只要道德按時推行確立，天下就絕不會有任何叛亂違逆之事發生！","analysis":"【題解與股肱耳目十二章服無面從退有後言】帝舜論君臣一體（股肱耳目）、制定古代天子「十二章服制度（日月星辰山龍華蟲宗彝藻火粉米黼黻）」、嚴厲告誡群臣「無面從退有後言」！\\n【詞義訓詁】「股肱耳目」：大臣為君主之肢體官能；「十二章服」：中國古代最高等級天子冕服之十二種神聖圖案體系；「無面從退有後言」：反對當面迎合奉承、背後議論非議之千古諫言；「德懋懋官，功懋懋賞」：勉勵重用有德之人、重賞有功之臣。"}},{"id":"shiji_ch-2_p-23","chapterId":"shiji_ch-2","order":23,"canonicalText":"帝曰：「毋若丹朱傲，維慢遊是好，毋水行舟，朋淫於家，用絕其世。予不能順是。」禹曰：「予辛壬癸甲，娶塗山，辛壬癸甲，生啟，予不子，以故能成水土功。輔成五服，至於五千裏，州十二師，外薄四海，鹹建五長，各守其職，莫敢不敬。」","sentenceIds":["shiji_ch-2_p-23_s-1","shiji_ch-2_p-23_s-2","shiji_ch-2_p-23_s-3","shiji_ch-2_p-23_s-4","shiji_ch-2_p-23_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"用現代漢語來說：帝說：毋若丹朱傲，維慢遊是好，毋水行舟，朋淫在家，用絕他世。予不能順是。禹說：予辛壬娶塗山，癸甲，生啟予不子，用故能成水土功。輔成五服，至在五千裏，州十二師，外薄四海，鹹建五長，各道有功。苗頑不即功，帝他念哉。帝說：道我德，於是女功序的啊。","analysis":"【主題與背景】本段「帝曰：「毋若丹朱傲，維慢...」立足於當時的時代脈絡，集中探討了功帝相關的核心議題。這反映出在歷史演變中，社會制度與思想的激烈碰撞。\\n【詞義與名物】文中的「功帝」代表了當時特有的社會階層或制度規範，而「予不」則具體指涉了相關的器物與理念。這些詞彙精準呈現了古人的生活實態。\\n【史家寄託】藉由分析功帝與五毋的互動，本段傳達了作者對歷史規律的洞察。這正是古人「以史為鑑」精神的具體展現，具有深遠的教育意義。"}},{"id":"shiji_ch-2_p-24","chapterId":"shiji_ch-2","order":24,"canonicalText":"皋陶於是敬禹之德，令民皆則禹。不如言，刑從之。舜德大明。","sentenceIds":["shiji_ch-2_p-24_s-1","shiji_ch-2_p-24_s-2","shiji_ch-2_p-24_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"皋陶因此十分敬重禹的德行，便下令全國百姓都要以禹為榜樣。如果不聽從這個命令的，就會用刑罰來處置他。於是，帝舜的德行也因此大放光明。","analysis":"【訓詁與名物】「皋陶」是上古時期的賢臣，相傳為舜帝時的司法官。「則」作動詞用，指效法、以之為榜樣。「不如言」指不聽從命令、不效法禹的德行。「刑從之」指刑罰就會緊隨其後降臨。「大明」指廣泛顯揚、大放光明。\\n【章法與結構】本段文字極度簡潔，邏輯因果關係強烈。第一句敘述皋陶對禹的敬重並推行教化；第二句則帶出法律的強制力作為教化的後盾（不如言，刑從之）；第三句是整個事件的最終結果，即將臣子的功勞與教化的成功，全數歸結於最高統治者帝舜的德明。\\n【思想與義理】這短短十六個字，蘊含了中國古代深厚的「德刑相濟」政治思想。皋陶作為司法官，他推廣禹的道德榜樣（德治），但同時也保留了刑罰的威懾力（法治）。道德的勸導需要法律的保障，刑罰的目的在於輔助道德的推行，兩者不可偏廢。而最終「舜德大明」的結語，則反映了傳統史觀中「臣子有功，歸於君上」的君臣倫理，聖王的德行是透過賢臣的輔佐才得以彰顯天下的。"}},{"id":"shiji_ch-2_p-25","chapterId":"shiji_ch-2","order":25,"canonicalText":"於是夔行樂，祖考至，群后相讓，鳥獸翔舞，簫韶九成，鳳皇來儀，百獸率舞，百官信諧。帝用此作歌，曰：「陟天之命，維時維幾。」乃歌曰：「天可度，時可代，動百工，朕何為哉！」周公作《立政》，言禹之德也。","sentenceIds":["shiji_ch-2_p-25_s-1","shiji_ch-2_p-25_s-2","shiji_ch-2_p-25_s-3","shiji_ch-2_p-25_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"到了這時，樂官夔主持奏響神聖的國家宮廷雅樂，列祖列宗的神靈紛紛降臨享祭（祖考至），四方諸侯群臣彬彬有禮互相謙讓，天地鳥獸歡騰飛翔起舞！當《簫韶》神樂演奏到第九樂章（簫韶九成）之際，神聖的彩鳳凰展翅飛來朝拜儀態萬方（鳳皇來儀），山林百獸相率和諧起舞，滿朝百官真誠信任和睦協調！帝舜因此感動賦作神聖詩歌道：登臨秉承至高上天的神聖天命，必須時刻把握時機、洞察萬事萬物的微妙先兆（維時維幾）！於是帝舜放聲高歌道：天道運行規律可以準確測度，四時節奏可以按時更替，天下百官各司其職生機勃勃，寡人垂拱而治何需多為呢！後來西周周公旦撰寫《尚書・立政》篇，專門極力讚頌弘揚大禹當年的崇高盛德！","analysis":"【題解與背景】\\n本段選自《史記》〈夏本紀〉第 54 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「於是夔行樂祖考至群后相讓鳥獸翔舞簫韶九成鳳皇……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「是」、「夔」、「行」、「樂」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《史記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"shiji_ch-2_p-26","chapterId":"shiji_ch-2","order":26,"canonicalText":"帝舜薦禹於天，為嗣。十七年而帝舜崩。三年喪畢，禹辭闢舜之子商均於陽城。天下諸侯皆去商均而朝禹。禹於是遂即天子位，南面朝天下，國號曰夏後，姓姒氏。","sentenceIds":["shiji_ch-2_p-26_s-1","shiji_ch-2_p-26_s-2","shiji_ch-2_p-26_s-3","shiji_ch-2_p-26_s-4","shiji_ch-2_p-26_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"其大意是：帝舜薦禹於天，為嗣。十七年並且帝舜崩。三年喪畢，禹辭闢舜的子商均於陽城。天下人諸侯都去商均並且朝禹。禹於是遂即天子位，南面朝天下，國家號說夏後，姓姒氏。","analysis":"【主題與背景】針對禹天的現象，這段文獻「帝舜薦禹於天，為嗣。十七...」提供了深刻的視角。其背後的歷史情境，凸顯了各方勢力對於國家治理的多元思考。\\n【詞義與名物】在此，我們必須特別注意「舜於」與「帝年」的時代含義。這些字眼不僅僅是字面上的意思，更包含了傳統禮法與社會結構的深層內涵。\\n【史家寄託】藉由分析禹天與帝年的互動，本段傳達了作者對歷史規律的洞察。這正是古人「以史為鑑」精神的具體展現，具有深遠的教育意義。"}},{"id":"shiji_ch-2_p-27","chapterId":"shiji_ch-2","order":27,"canonicalText":"帝禹立而舉皋陶薦之，且授政焉，而皋陶卒。封皋陶之後於英、六，或在許。而後舉益，任之政。","sentenceIds":["shiji_ch-2_p-27_s-1","shiji_ch-2_p-27_s-2","shiji_ch-2_p-27_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"帝禹即位後，便推舉皋陶，將他推薦給上天，並且把國家政務交給他處理，然而皋陶卻不幸去世了。於是，禹將皋陶的後代分封在英、六兩地，也有人說分封在許地。之後，禹又推舉了伯益，讓他負責處理國家政務。","analysis":"【訓詁與名物】「立」指繼承帝位。「薦之」在此多指古代天子將繼承人推薦給上天的儀式（如堯薦舜於天）。「授政」即將國家大政交給他處理，作為接班人的歷練。「英、六、許」皆為古代諸侯國或地名。「益」即伯益，相傳是協助禹治水有功的賢臣。\\n【章法與結構】本段主要記錄了大禹即位後對於繼承人的安排。行文依時間順序展開，先寫對皋陶的推舉與授權，接著寫皋陶的驟逝與對其後代的撫卹（封地），最後寫因皋陶去世而不得不重新推舉伯益為接班人。敘事平實客觀，充滿史家筆法。\\n【思想與義理】此段記載反映了上古「禪讓制」在具體操作上的歷史細節。大禹雖然憑藉治水之功取得天下，但他並未立即將帝位傳給自己的兒子（啟），而是遵循堯舜以來的傳統，推舉有德有功的賢臣（皋陶、伯益）作為繼承人，並讓他們實際參與國政（授政）。這顯示了在夏朝建立「家天下」之前，禪讓制仍然是當時社會公認的政治傳承正統，而大禹也必須在形式上完成這種公天下的人事佈局。"}},{"id":"shiji_ch-2_p-28","chapterId":"shiji_ch-2","order":28,"canonicalText":"十年，帝禹東巡狩，至於會稽而崩。以天下授益。三年之喪畢，益讓帝禹之子啟，而闢居箕山之陽。禹子啟賢，天下屬意焉。及禹崩，雖授益，益之佐禹日淺，天下未洽。故諸侯皆去益而朝啟，曰：「吾君帝禹之子也。」於是啟遂即天子之位，是為夏后帝啟。","sentenceIds":["shiji_ch-2_p-28_s-1","shiji_ch-2_p-28_s-2","shiji_ch-2_p-28_s-3","shiji_ch-2_p-28_s-4","shiji_ch-2_p-28_s-5","shiji_ch-2_p-28_s-6","shiji_ch-2_p-28_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"在位第十年，大禹親率文武百官向東方巡狩視察，抵達會稽山大會天下諸侯之際不幸病重逝世崩殂。大禹臨終前遵照禪讓體制將天下託付授予伯益。守滿三年國喪之後，伯益主動將天子帝位謙讓給大禹的親生兒子夏啟，自己主動退避居住在箕山的南面。大禹的兒子夏啟才德兼備極其賢能，天下萬民與諸侯早就對夏啟傾心歸附寄予厚望（天下屬意焉）！等到大禹崩逝之際，大禹雖然在名義上將天下委託給了伯益，但伯益輔佐大禹主持政務的時間尚短，在天下的威望與民心基礎尚未融洽穩固。因此天下各路諸侯全部主動離開伯益而爭相前來朝拜夏啟，大家一致由衷高呼：夏啟是我們至尊聖君大禹的親生兒子啊！於是夏啟在天下萬邦擁戴之下順應天命正式登基踐祚即天子大位，這就是歷史上的夏后帝啟！","analysis":"【題解與禹崩會稽授益益讓啟天下諸侯朝啟公天下變家天下】本段為中國政治文明史最關鍵之歷史轉折點——大禹崩於會稽、益讓啟居箕山、天下諸侯朝啟，世襲制（家天下）正式取代原始禪讓制（公天下）！\\n【詞義訓詁】「會稽」：浙江紹興會稽山，大禹大會諸侯計功之所及大禹陵所在地；「益佐禹日淺天下未洽」：分析政權平穩過渡至啟的客觀政治聲望原因；「家天下之始」：中國世襲王朝體制之正式開端。"}},{"id":"shiji_ch-2_p-29","chapterId":"shiji_ch-2","order":29,"canonicalText":"夏后帝啟，禹之子，其母塗山氏之女也。","sentenceIds":["shiji_ch-2_p-29_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"夏朝的君主帝啟，是大禹的兒子，他的母親是塗山氏的女兒。","analysis":"【訓詁與名物】「夏後」是夏朝君主的尊稱，也是夏氏族的稱號。「帝啟」即夏啟，大禹的兒子，中國歷史上第一個世襲制王朝（夏朝）的實質建立者。「塗山氏」為上古時期的部族名，相傳大禹治水時曾在此娶妻。\\n【章法與結構】這是一句極為精簡的史傳家譜式記錄。僅僅十九個字，便交代了新任帝王的稱號（夏后帝啟）、父系血緣（禹之子）以及母系背景（塗山氏之女），文字乾淨俐落，毫無冗詞贅字。\\n【思想與義理】這短短一句話，在中國政治史上具有劃時代的意義。它標誌著上古時期「傳賢不傳子」的「公天下」禪讓制度正式終結，取而代之的是「傳子不傳賢」的「家天下」世襲制度的確立。大禹之子啟繼承帝位，將國家最高權力牢牢鎖定在單一家族的血脈之中，這不僅是夏朝建立的標誌，更奠定了其後中國長達四千多年封建王朝世襲繼承的根本政治模式。"}},{"id":"shiji_ch-2_p-30","chapterId":"shiji_ch-2","order":30,"canonicalText":"有扈氏不服，啟伐之，大戰於甘。將戰，作甘誓，乃召六卿申之。啟曰：「嗟！六事之人，予誓告女：有扈氏威侮五行，怠棄三正，天用剿絕其命，今予唯恭行天之罰。左不攻於左，汝不恭命；右不攻於右，汝不恭命；御非其馬之正，汝不恭命。用命，賞於祖；不用命，戮於社，予則帑僇汝。」遂滅有扈氏。天下鹹朝。","sentenceIds":["shiji_ch-2_p-30_s-1","shiji_ch-2_p-30_s-2","shiji_ch-2_p-30_s-3","shiji_ch-2_p-30_s-4","shiji_ch-2_p-30_s-5","shiji_ch-2_p-30_s-6","shiji_ch-2_p-30_s-7","shiji_ch-2_p-30_s-8","shiji_ch-2_p-30_s-9","shiji_ch-2_p-30_s-10","shiji_ch-2_p-30_s-11"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"同姓封國有扈氏不服從夏啟繼位稱帝，夏啟親率王師大軍前往討伐，雙方在甘地擺開戰場展開決戰（大戰於甘）。在決戰即將打響之際，夏啟作出了著名的戰前動員誓師軍令《甘誓》，召集全軍六軍統帥六卿重申軍紀號令！夏啟莊嚴宣誓道：嗟！統率全軍六軍的各位將領勇士們（六事之人），寡人在此向你們發出嚴正誓言宣告：有扈氏公然藐視踐踏天地五行之理（威侮五行），怠惰廢棄了敬順四時的天文歷法政令（怠棄三正），皇天上帝因此決定徹底剿滅斷絕他的天命氣數！如今寡人親臨前線，只是恭敬奉行上天的神聖天罰而已！戰車左側的射手如果不奮勇向左側敵軍射擊，就是不遵從軍令；戰車右側的持戈甲士如果不奮勇向右側敵軍搏殺，就是不遵從軍令；戰車中間的馭手如果不能端正駕馭戰車戰馬奔馳前進，就是不遵從軍令！凡是服從軍令英勇殺敵者，寡人將在祖廟神位前重重賞賜封爵；凡是不服從軍令臨陣退縮者，寡人將在社稷神壇前當眾斬首處死，並將你們的妻子兒女全部籍沒貶為奴隸（予則帑僇汝）！夏啟親自指揮大軍一舉全殲滅亡了叛亂的有扈氏！天下四方諸侯無不心悅誠服全部前來朝覲臣服！","analysis":"【題解與背景】\\n本段選自《史記》〈夏本紀〉第 59 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「有扈氏不服啟伐之大戰於甘將戰作甘誓乃召六……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「有」、「扈」、「氏」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《史記》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：shiji_ch-2_p-30）。"}},{"id":"shiji_ch-2_p-31","chapterId":"shiji_ch-2","order":31,"canonicalText":"夏后帝啟崩，子帝太康立。帝太康失國，昆弟五人，須於洛汭，作五子之歌。","sentenceIds":["shiji_ch-2_p-31_s-1","shiji_ch-2_p-31_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"夏后帝啟崩，子帝太康立。帝太康失國家，昆弟五人們，須在洛汭，作五子的歌。","analysis":"【主題與背景】在春秋戰國至秦漢的歷史進程中，本段文字「夏后帝啟崩，子帝太康立。...」主要講述了帝子與太康的關聯。它揭示了當時政治局勢下的特定風貌。\\n【詞義與名物】文中的「帝子」代表了當時特有的社會階層或制度規範，而「太康」則具體指涉了相關的器物與理念。這些詞彙精準呈現了古人的生活實態。\\n【史家寄託】藉由分析帝子與五夏的互動，本段傳達了作者對歷史規律的洞察。這正是古人「以史為鑑」精神的具體展現，具有深遠的教育意義。"}},{"id":"shiji_ch-2_p-32","chapterId":"shiji_ch-2","order":32,"canonicalText":"太康崩，弟中康立，是為帝中康。帝中康時，羲、和湎淫，廢時亂日。胤往徵之，作胤徵。","sentenceIds":["shiji_ch-2_p-32_s-1","shiji_ch-2_p-32_s-2","shiji_ch-2_p-32_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"其大意是：太康崩，弟中康立，是為帝中康。帝中康時，羲、和湎淫，廢時亂日。胤徃徵的，作胤徵。","analysis":"【主題與背景】針對康中的現象，這段文獻「太康崩，弟中康立，是為帝...」提供了深刻的視角。其背後的歷史情境，凸顯了各方勢力對於國家治理的多元思考。\\n【詞義與名物】作者使用了「康中」等關鍵字眼，這在古代文獻中通常用來描述特定的歷史名物。透過「帝時」的使用，文章進一步勾勒出當時的文化特色。\\n【史家寄託】這不僅是一段關於帝時的歷史記載，更體現了史學家對康中現象的深刻批判。字裡行間流露出對理想政治與社會秩序的嚮往。"}},{"id":"shiji_ch-2_p-33","chapterId":"shiji_ch-2","order":33,"canonicalText":"中康崩，子帝相立。帝相崩，子帝少康立。帝少康崩，子帝予立。帝予崩，子帝槐立。帝槐崩，子帝芒立。帝芒崩，子帝泄立。帝泄崩，子帝不降立。帝不降崩，弟帝扃立。帝扃崩，子帝廑立。帝廑崩，立不降之子孔甲，是為帝孔甲。孔甲立，好方鬼神，事淫亂。夏后氏德衰，諸侯畔之。","sentenceIds":["shiji_ch-2_p-33_s-1","shiji_ch-2_p-33_s-2","shiji_ch-2_p-33_s-3","shiji_ch-2_p-33_s-4","shiji_ch-2_p-33_s-5","shiji_ch-2_p-33_s-6","shiji_ch-2_p-33_s-7","shiji_ch-2_p-33_s-8","shiji_ch-2_p-33_s-9","shiji_ch-2_p-33_s-10","shiji_ch-2_p-33_s-11","shiji_ch-2_p-33_s-12"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"中康崩，子帝相立。帝相崩，子帝少康立。帝少康崩，子帝予立。帝予崩，子帝槐立。帝槐崩，子帝芒立。帝芒崩，子帝泄立。帝泄崩，子帝不降立。帝不降崩，弟帝扃立。帝扃崩，子帝厪立。帝厪崩，立帝不降的子孔甲，是為帝孔甲。帝孔甲立，好方鬼神，事淫亂。夏后氏德衰，諸侯畔的。天降龍二，有雌雄，孔甲不能食，未得豢龍氏。陶唐旣衰，他後有劉累，學擾龍在豢龍氏，用事孔甲。孔甲賜的姓說御龍氏，受豕韋的後。龍一雌死，用食夏後。夏後使求，懼並且遷去。","analysis":"【主題與背景】在春秋戰國至秦漢的歷史進程中，本段文字「中康崩，子帝相立。帝相崩...」主要講述了帝立與崩子的關聯。它揭示了當時政治局勢下的特定風貌。\\n【詞義與名物】在此，我們必須特別注意「崩子」與「孔甲」的時代含義。這些字眼不僅僅是字面上的意思，更包含了傳統禮法與社會結構的深層內涵。\\n【史家寄託】這不僅是一段關於崩子的歷史記載，更體現了史學家對帝立現象的深刻批判。字裡行間流露出對理想政治與社會秩序的嚮往。"}},{"id":"shiji_ch-2_p-34","chapterId":"shiji_ch-2","order":34,"canonicalText":"孔甲崩，子帝皋立。帝皋崩，子帝發立。帝發崩，子帝履癸立，是為桀。帝桀之時，自孔甲以來而諸侯多畔夏，桀不務德而武傷百姓，百姓弗堪。乃召湯而囚之夏臺，已而釋之。湯修德，諸侯皆歸湯，湯遂率師以伐夏桀。桀走鳴條，遂放而死。桀謂人曰：「吾悔不遂殺湯於夏臺，使至此。」湯乃踐天子位，代夏，是為商湯。","sentenceIds":["shiji_ch-2_p-34_s-1","shiji_ch-2_p-34_s-2","shiji_ch-2_p-34_s-3","shiji_ch-2_p-34_s-4","shiji_ch-2_p-34_s-5","shiji_ch-2_p-34_s-6","shiji_ch-2_p-34_s-7","shiji_ch-2_p-34_s-8","shiji_ch-2_p-34_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"帝孔甲崩逝之後，兒子帝皋繼位；帝皋崩逝，兒子帝發繼位；帝發崩逝之後，兒子帝履癸即位，這就是歷史上著名的暴君夏桀！夏桀在位之時，由於自孔甲以來天下諸侯大多已背叛夏朝，夏桀不僅不肯修養道德以挽回人心，反而肆無忌憚崇尚暴虐武力殘害屠殺黎民百姓（武傷百姓），天下百姓痛苦萬狀不堪忍受！夏桀曾將商部落首領商湯召入朝中並無端關押在夏臺監獄之中（囚之夏臺），不久後迫於壓力將商湯釋放回國。商湯回國之後大修道德仁政、撫恤百姓，天下諸侯紛紛前來投奔歸附商湯！商湯順應民心天命，毅然率領諸侯聯軍大舉出兵討伐夏桀（商湯伐夏）！雙方在鳴條展開決戰，夏桀全軍覆沒倉皇逃奔鳴條，最終被流放放逐在南巢孤獨死去！夏桀臨死前懊悔地對身邊人說：我真後悔當年沒有在夏臺監獄中直接殺掉商湯，以至於落得今天這個身敗名裂的下場！商湯在天下萬民擁戴之下正式登基踐祚即天子位，正式取代夏朝，這就是偉大的商湯開創商王朝！","analysis":"【題解與背景】\\n本段選自《史記》〈夏本紀〉第 63 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「孔甲崩子帝皋立帝皋崩子帝發立帝發崩子帝履癸立……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「孔」、「甲」、「崩」、「子」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《史記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"shiji_ch-2_p-35","chapterId":"shiji_ch-2","order":35,"canonicalText":"太史公曰：禹為姒姓，其後分封，用國為姓，故有夏后氏、有扈氏、有男氏、斟尋氏、彤城氏、褒氏、費氏、杞氏、繒氏、辛氏、冥氏、斟氏、戈氏。杞、繒，夏後也。春秋之時，杞為微國，然其存者千有餘歲。自禹至桀，凡十四世，十七君，四百餘歲。夏之興也以德，其衰也以淫，天命無常，唯德是輔，此百王之大戒也。","sentenceIds":["shiji_ch-2_p-35_s-1","shiji_ch-2_p-35_s-2","shiji_ch-2_p-35_s-3","shiji_ch-2_p-35_s-4","shiji_ch-2_p-35_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"},{"label":"維基文庫《史記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98"}],"readingAid":{"translation":"其大意是：太史公說：禹為姒姓，他後分封，用國家為姓，故有夏后氏、有扈氏、有男氏、斟尋氏、彤城氏、襃氏、費氏、杞氏、繒氏、辛氏、冥氏、斟氏、戈氏。孔子正夏時，學的人們多傳夏小正雲。自虞、夏時，貢賦備了。或言禹會諸侯江南，計功並且崩，因葬焉，命說會稽。會稽的人，會計啊。","analysis":"【主題與背景】針對氏夏的現象，這段文獻「太史公曰：禹為姒姓，其後...」提供了深刻的視角。其背後的歷史情境，凸顯了各方勢力對於國家治理的多元思考。\\n【詞義與名物】作者使用了「氏夏」等關鍵字眼，這在古代文獻中通常用來描述特定的歷史名物。透過「會有」的使用，文章進一步勾勒出當時的文化特色。\\n【史家寄託】藉由分析氏夏與禹為的互動，本段傳達了作者對歷史規律的洞察。這正是古人「以史為鑑」精神的具體展現，具有深遠的教育意義。"}}],"sentences":[{"id":"shiji_ch-1_p-1_s-1","passageId":"shiji_ch-1_p-1","order":1,"canonicalText":"黃帝者，少典之子，姓公孫，名曰軒轅。","chunks":[["黃帝者，少典之子，姓公孫，名曰軒轅。","zh-Hant"]]},{"id":"shiji_ch-1_p-1_s-2","passageId":"shiji_ch-1_p-1","order":2,"canonicalText":"生而神靈，弱而能言，幼而徇齊，長而敦敏，成而聰明。","chunks":[["生而神靈，弱而能言，幼而徇齊，長而敦敏，成而聰明。","zh-Hant"]]},{"id":"shiji_ch-1_p-2_s-1","passageId":"shiji_ch-1_p-2","order":1,"canonicalText":"軒轅之時，神農氏世衰。","chunks":[["軒轅之時，神農氏世衰。","zh-Hant"]]},{"id":"shiji_ch-1_p-2_s-2","passageId":"shiji_ch-1_p-2","order":2,"canonicalText":"諸侯相侵伐，暴虐百姓，而神農氏弗能徵。","chunks":[["諸侯相侵伐，暴虐百姓，而神農氏弗能徵。","zh-Hant"]]},{"id":"shiji_ch-1_p-2_s-3","passageId":"shiji_ch-1_p-2","order":3,"canonicalText":"於是軒轅乃習用干戈，以徵不享，諸侯鹹來賓從。","chunks":[["於是軒轅乃習用干戈，以徵不享，諸侯鹹來賓從。","zh-Hant"]]},{"id":"shiji_ch-1_p-2_s-4","passageId":"shiji_ch-1_p-2","order":4,"canonicalText":"而蚩尤最為暴，莫能伐。","chunks":[["而蚩尤最為暴，莫能伐。","zh-Hant"]]},{"id":"shiji_ch-1_p-2_s-5","passageId":"shiji_ch-1_p-2","order":5,"canonicalText":"炎帝欲侵陵諸侯，諸侯鹹歸軒轅。","chunks":[["炎帝欲侵陵諸侯，諸侯鹹歸軒轅。","zh-Hant"]]},{"id":"shiji_ch-1_p-2_s-6","passageId":"shiji_ch-1_p-2","order":6,"canonicalText":"軒轅乃修德振兵，治五氣，蓺五種，撫萬民，度四方，教熊羆貔貅貙虎，以與炎帝戰於阪泉之野。","chunks":[["軒轅乃修德振兵，治五氣，藝五種，撫萬民，度四方，教熊羆貔貅貙虎，以與炎帝戰於阪泉之野。","zh-Hant"]]},{"id":"shiji_ch-1_p-2_s-7","passageId":"shiji_ch-1_p-2","order":7,"canonicalText":"三戰，然後得其志。","chunks":[["三戰然後得其志。","zh-Hant"]]},{"id":"shiji_ch-1_p-2_s-8","passageId":"shiji_ch-1_p-2","order":8,"canonicalText":"蚩尤作亂，不用帝命。","chunks":[["蚩尤作亂，不用帝命。","zh-Hant"]]},{"id":"shiji_ch-1_p-2_s-9","passageId":"shiji_ch-1_p-2","order":9,"canonicalText":"於是黃帝乃徵師諸侯，與蚩尤戰於涿鹿之野，遂禽殺蚩尤。","chunks":[["於是黃帝乃徵師諸侯，與蚩尤戰於涿鹿之野，遂禽殺蚩尤。","zh-Hant"]]},{"id":"shiji_ch-1_p-2_s-10","passageId":"shiji_ch-1_p-2","order":10,"canonicalText":"而諸侯鹹尊軒轅為天子，代神農氏，是為黃帝。","chunks":[["而諸侯鹹尊軒轅為天子，代神農氏，是為黃帝。","zh-Hant"]]},{"id":"shiji_ch-1_p-2_s-11","passageId":"shiji_ch-1_p-2","order":11,"canonicalText":"天下有不順者，黃帝從而徵之，平者去之，披山通道，未嘗寧居。","chunks":[["天下有不順者，黃帝從而徵之，平者去之，披山通道，未嘗寧居。","zh-Hant"]]},{"id":"shiji_ch-1_p-4_s-1","passageId":"shiji_ch-1_p-4","order":1,"canonicalText":"黃帝二十五子，其得姓者十四人。","chunks":[["黃帝二十五子，其得姓者十四人。","zh-Hant"]]},{"id":"shiji_ch-1_p-6_s-1","passageId":"shiji_ch-1_p-6","order":1,"canonicalText":"帝顓頊高陽者，黃帝之孫而昌意之子也。","chunks":[["帝顓頊高陽者，黃帝之孫而昌意之子也。","zh-Hant"]]},{"id":"shiji_ch-1_p-6_s-2","passageId":"shiji_ch-1_p-6","order":2,"canonicalText":"靜淵以有謀，疏通而知事；","chunks":[["靜淵以有謀，疏通而知事；","zh-Hant"]]},{"id":"shiji_ch-1_p-6_s-3","passageId":"shiji_ch-1_p-6","order":3,"canonicalText":"養材以任地，載時以象天，依鬼神以制義，治氣以教化，潔誠以祭祀。","chunks":[["養材以任地，載時以象天，依鬼神以制義，治氣以教化，絜誠以祭祀。","zh-Hant"]]},{"id":"shiji_ch-1_p-6_s-4","passageId":"shiji_ch-1_p-6","order":4,"canonicalText":"北至於幽陵，南至於交阯，西至於流沙，東至於蟠木。","chunks":[["北至於幽陵，南至於交阯，西至於流沙，東至於蟠木。","zh-Hant"]]},{"id":"shiji_ch-1_p-6_s-5","passageId":"shiji_ch-1_p-6","order":5,"canonicalText":"動靜之物，大小之神，日月所照，莫不祗勵。","chunks":[["動靜之物，大小之神，日月所照，莫不砥屬。","zh-Hant"]]},{"id":"shiji_ch-1_p-7_s-1","passageId":"shiji_ch-1_p-7","order":1,"canonicalText":"帝顓頊生子曰窮蟬。","chunks":[["帝顓頊生子曰窮蟬。","zh-Hant"]]},{"id":"shiji_ch-1_p-7_s-2","passageId":"shiji_ch-1_p-7","order":2,"canonicalText":"顓頊崩，而玄囂之孫高辛立，是為帝嚳。","chunks":[["顓頊崩，而玄囂之孫高辛立，是為帝嚳。","zh-Hant"]]},{"id":"shiji_ch-1_p-8_s-1","passageId":"shiji_ch-1_p-8","order":1,"canonicalText":"帝嚳高辛者，黃帝之曾孫也。","chunks":[["帝嚳高辛者，黃帝之曾孫也。","zh-Hant"]]},{"id":"shiji_ch-1_p-8_s-2","passageId":"shiji_ch-1_p-8","order":2,"canonicalText":"高辛父曰蟜極，蟜極父曰玄囂，玄囂父曰黃帝。","chunks":[["高辛父曰蟜極，蟜極父曰玄囂，玄囂父曰黃帝。","zh-Hant"]]},{"id":"shiji_ch-1_p-8_s-3","passageId":"shiji_ch-1_p-8","order":3,"canonicalText":"自玄囂與蟜極皆不得在位，至高辛即帝位。","chunks":[["自玄囂與蟜極皆不得在位，至高辛即帝位。","zh-Hant"]]},{"id":"shiji_ch-1_p-8_s-4","passageId":"shiji_ch-1_p-8","order":4,"canonicalText":"高辛於顓頊為族子。","chunks":[["高辛於顓頊為族子。","zh-Hant"]]},{"id":"shiji_ch-1_p-10_s-1","passageId":"shiji_ch-1_p-10","order":1,"canonicalText":"帝嚳娶陳鋒氏女，生放勛。","chunks":[["帝嚳娶陳鋒氏女，生放勛。","zh-Hant"]]},{"id":"shiji_ch-1_p-10_s-2","passageId":"shiji_ch-1_p-10","order":2,"canonicalText":"娶娵訾氏女，生摯。","chunks":[["娶娵訾氏女，生摯。","zh-Hant"]]},{"id":"shiji_ch-1_p-10_s-3","passageId":"shiji_ch-1_p-10","order":3,"canonicalText":"帝嚳崩，而摯代立。","chunks":[["帝嚳崩，而摯代立。","zh-Hant"]]},{"id":"shiji_ch-1_p-10_s-4","passageId":"shiji_ch-1_p-10","order":4,"canonicalText":"帝摯立，不善（崩），而弟放勛立，是為帝堯。","chunks":[["帝摯立，不善（崩），而弟放勛立，是為帝堯。","zh-Hant"]]},{"id":"shiji_ch-1_p-11_s-1","passageId":"shiji_ch-1_p-11","order":1,"canonicalText":"帝堯者，放勛。","chunks":[["帝堯者，放勛。","zh-Hant"]]},{"id":"shiji_ch-1_p-11_s-2","passageId":"shiji_ch-1_p-11","order":2,"canonicalText":"其仁如天，其知如神。","chunks":[["其仁如天，其知如神。","zh-Hant"]]},{"id":"shiji_ch-1_p-11_s-3","passageId":"shiji_ch-1_p-11","order":3,"canonicalText":"就之如日，望之如雲。","chunks":[["就之如日，望之如雲。","zh-Hant"]]},{"id":"shiji_ch-1_p-11_s-4","passageId":"shiji_ch-1_p-11","order":4,"canonicalText":"富而不驕，貴而不舒。","chunks":[["富而不驕，貴而不舒。","zh-Hant"]]},{"id":"shiji_ch-1_p-11_s-5","passageId":"shiji_ch-1_p-11","order":5,"canonicalText":"黃收純衣，彤車乘白馬。","chunks":[["黃收純衣，彤車乘白馬。","zh-Hant"]]},{"id":"shiji_ch-1_p-11_s-6","passageId":"shiji_ch-1_p-11","order":6,"canonicalText":"能明馴德，以親九族。","chunks":[["能明馴德，以親九族。","zh-Hant"]]},{"id":"shiji_ch-1_p-11_s-7","passageId":"shiji_ch-1_p-11","order":7,"canonicalText":"九族既睦，便章百姓。","chunks":[["九族既睦，便章百姓。","zh-Hant"]]},{"id":"shiji_ch-1_p-11_s-8","passageId":"shiji_ch-1_p-11","order":8,"canonicalText":"百姓昭明，合和萬國。","chunks":[["百姓昭明，合和萬國。","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-1","passageId":"shiji_ch-1_p-13","order":1,"canonicalText":"堯曰：「誰可順此事？","chunks":[["堯曰：「誰可順此事？","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-2","passageId":"shiji_ch-1_p-13","order":2,"canonicalText":"」放齊曰：「嗣子丹朱開明。","chunks":[["」放齊曰：「嗣子丹朱開明。","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-3","passageId":"shiji_ch-1_p-13","order":3,"canonicalText":"」堯曰：「籲！","chunks":[["」堯曰：「籲！","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-4","passageId":"shiji_ch-1_p-13","order":4,"canonicalText":"頑兇，不用。","chunks":[["頑兇，不用。","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-5","passageId":"shiji_ch-1_p-13","order":5,"canonicalText":"」堯又曰：「誰可者？","chunks":[["」堯又曰：「誰可者？","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-6","passageId":"shiji_ch-1_p-13","order":6,"canonicalText":"」讙兜曰：「便窮共工，部聚用事，可。","chunks":[["」讙兜曰：「共工旁聚布功，可用。","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-7","passageId":"shiji_ch-1_p-13","order":7,"canonicalText":"」堯曰：「共工善言而意色，恭天，欺慢，不可。","chunks":[["」堯曰：「共工善言，其用僻，似恭漫天，不可。","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-8","passageId":"shiji_ch-1_p-13","order":8,"canonicalText":"」堯又曰：「嗟，四嶽，湯湯洪水滔天，浩浩懷山襄陵，下民其憂，有能使治者？","chunks":[["」堯又曰：「嗟，四嶽，湯湯洪水滔天，浩浩懷山襄陵，下民其憂，有能使治者？","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-9","passageId":"shiji_ch-1_p-13","order":9,"canonicalText":"」皆曰鯀可。","chunks":[["」皆曰鯀可。","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-10","passageId":"shiji_ch-1_p-13","order":10,"canonicalText":"堯曰：「鯀負命毀族，不可。","chunks":[["堯曰：「鯀負命毀族，不可。","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-11","passageId":"shiji_ch-1_p-13","order":11,"canonicalText":"」嶽曰：「異哉，試不可用而已。","chunks":[["」嶽曰：「異哉，試不可用而已。","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-12","passageId":"shiji_ch-1_p-13","order":12,"canonicalText":"」堯乃聽嶽，用鯀治水。","chunks":[["」堯於是聽嶽用鯀。","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-13","passageId":"shiji_ch-1_p-13","order":13,"canonicalText":"九年而水不息，功用不成。","chunks":[["九歲，功用不成。","zh-Hant"]]},{"id":"shiji_ch-1_p-17_s-1","passageId":"shiji_ch-1_p-17","order":1,"canonicalText":"讙兜進言共工，堯曰不可而試之工師，共工果淫闢。","chunks":[["讙兜進言共工，堯曰不可而試之工師，共工果淫闢。","zh-Hant"]]},{"id":"shiji_ch-1_p-17_s-2","passageId":"shiji_ch-1_p-17","order":2,"canonicalText":"四嶽舉鯀治鴻水，堯以為不可，嶽彊請試之，試之而無功，故百姓不便。","chunks":[["四嶽舉鯀治鴻水，堯以為不可，嶽彊請試之，試之而無功，故百姓不便。","zh-Hant"]]},{"id":"shiji_ch-1_p-17_s-3","passageId":"shiji_ch-1_p-17","order":3,"canonicalText":"三苗在江淮、荊州數為亂。","chunks":[["三苗在江淮、荊州數為亂。","zh-Hant"]]},{"id":"shiji_ch-1_p-17_s-4","passageId":"shiji_ch-1_p-17","order":4,"canonicalText":"於是舜歸而言於帝，請流共工於幽陵，以變北狄；","chunks":[["於是舜歸而言於帝，請流共工於幽陵，以變北狄；","zh-Hant"]]},{"id":"shiji_ch-1_p-17_s-5","passageId":"shiji_ch-1_p-17","order":5,"canonicalText":"放驩兜於崇山，以變南蠻；","chunks":[["放讙兜於崇山，以變南蠻；","zh-Hant"]]},{"id":"shiji_ch-1_p-17_s-6","passageId":"shiji_ch-1_p-17","order":6,"canonicalText":"遷三苗於三危，以變西戎；","chunks":[["遷三苗於三危，以變西戎；","zh-Hant"]]},{"id":"shiji_ch-1_p-17_s-7","passageId":"shiji_ch-1_p-17","order":7,"canonicalText":"殛鯀於羽山，以變東夷：四罪而天下鹹服。","chunks":[["殛鯀於羽山，以變東夷：四罪而天下鹹服。","zh-Hant"]]},{"id":"shiji_ch-1_p-19_s-1","passageId":"shiji_ch-1_p-19","order":1,"canonicalText":"虞舜者，名曰重華。","chunks":[["虞舜者，名曰重華。","zh-Hant"]]},{"id":"shiji_ch-1_p-19_s-2","passageId":"shiji_ch-1_p-19","order":2,"canonicalText":"重華父曰瞽叟，瞽叟父曰橋牛，橋牛父曰句望，句望父曰敬康，敬康父曰窮蟬，窮蟬父曰帝顓頊，顓頊父曰昌意：以至舜七世矣。","chunks":[["重華父曰瞽叟，瞽叟父曰橋牛，橋牛父曰句望，句望父曰敬康，敬康父曰窮蟬，窮蟬父曰帝顓頊，顓頊父曰昌意：以至舜七世矣。","zh-Hant"]]},{"id":"shiji_ch-1_p-19_s-3","passageId":"shiji_ch-1_p-19","order":3,"canonicalText":"自從窮蟬以至順，皆微為庶人。","chunks":[["自從窮蟬以至帝舜，皆微為庶人。","zh-Hant"]]},{"id":"shiji_ch-1_p-20_s-1","passageId":"shiji_ch-1_p-20","order":1,"canonicalText":"舜父瞽叟盲，而舜母死，瞽叟更娶妻而生象，象傲。","chunks":[["舜父瞽叟盲，而舜母死，瞽叟更娶妻而生象，象傲。","zh-Hant"]]},{"id":"shiji_ch-1_p-20_s-2","passageId":"shiji_ch-1_p-20","order":2,"canonicalText":"瞽叟愛後妻子，常欲殺舜，舜避逃；","chunks":[["瞽叟愛後妻子，常欲殺舜，舜避逃；","zh-Hant"]]},{"id":"shiji_ch-1_p-20_s-3","passageId":"shiji_ch-1_p-20","order":3,"canonicalText":"及有小過，則受罪。","chunks":[["及有小過，則受罪。","zh-Hant"]]},{"id":"shiji_ch-1_p-20_s-4","passageId":"shiji_ch-1_p-20","order":4,"canonicalText":"順事父及後母與弟，日乾乾，便便，匪懈。","chunks":[["順事父及後母與弟，日以篤謹，匪有解。","zh-Hant"]]},{"id":"shiji_ch-1_p-21_s-1","passageId":"shiji_ch-1_p-21","order":1,"canonicalText":"舜，冀州之人也。","chunks":[["舜，冀州之人也。","zh-Hant"]]},{"id":"shiji_ch-1_p-21_s-2","passageId":"shiji_ch-1_p-21","order":2,"canonicalText":"舜耕歷山，漁雷澤，陶河濱，作什器於壽丘，就時於負夏。","chunks":[["舜耕歷山，漁雷澤，陶河濱，作什器於壽丘，就時於負夏。","zh-Hant"]]},{"id":"shiji_ch-1_p-21_s-3","passageId":"shiji_ch-1_p-21","order":3,"canonicalText":"舜父瞽叟頑，母嚚，弟象傲，皆欲殺舜。","chunks":[["舜父瞽叟頑，母嚚，弟象傲，皆欲殺舜。","zh-Hant"]]},{"id":"shiji_ch-1_p-21_s-4","passageId":"shiji_ch-1_p-21","order":4,"canonicalText":"舜順適不失子道，兄弟孝慈。","chunks":[["舜順適不失子道，兄弟孝慈。","zh-Hant"]]},{"id":"shiji_ch-1_p-21_s-5","passageId":"shiji_ch-1_p-21","order":5,"canonicalText":"欲殺，不可得；","chunks":[["欲殺，不可得；","zh-Hant"]]},{"id":"shiji_ch-1_p-21_s-6","passageId":"shiji_ch-1_p-21","order":6,"canonicalText":"即求，嘗在側。","chunks":[["即求，嘗在側。","zh-Hant"]]},{"id":"shiji_ch-1_p-23_s-1","passageId":"shiji_ch-1_p-23","order":1,"canonicalText":"昔高陽氏有才子八人，世得其利，謂之「八愷」。","chunks":[["昔高陽氏有才子八人，世得其利，謂之「八愷」。","zh-Hant"]]},{"id":"shiji_ch-1_p-23_s-2","passageId":"shiji_ch-1_p-23","order":2,"canonicalText":"高辛氏有才子八人，世謂之「八元」。","chunks":[["高辛氏有才子八人，世謂之「八元」。","zh-Hant"]]},{"id":"shiji_ch-1_p-23_s-3","passageId":"shiji_ch-1_p-23","order":3,"canonicalText":"此十六族者，世濟其美，不隕其名。","chunks":[["此十六族者，世濟其美，不隕其名。","zh-Hant"]]},{"id":"shiji_ch-1_p-23_s-4","passageId":"shiji_ch-1_p-23","order":4,"canonicalText":"至帝堯，堯未能舉。","chunks":[["至於堯，堯未能舉。","zh-Hant"]]},{"id":"shiji_ch-1_p-23_s-5","passageId":"shiji_ch-1_p-23","order":5,"canonicalText":"舜舉八愷，使主后土，以揆百事，莫不時序。","chunks":[["舜舉八愷，使主后土，以揆百事，莫不時序。","zh-Hant"]]},{"id":"shiji_ch-1_p-23_s-6","passageId":"shiji_ch-1_p-23","order":6,"canonicalText":"舉八元，使布五教於四方，父義，母慈，兄友，弟恭，子孝，內平外成。","chunks":[["舉八元，使布五教於四方，父義，母慈，兄友，弟恭，子孝，內平外成。","zh-Hant"]]},{"id":"shiji_ch-1_p-27_s-1","passageId":"shiji_ch-1_p-27","order":1,"canonicalText":"舜年二十以孝聞，年三十堯舉之，年五十攝行天子事，年五十八堯崩，年六十一代堯踐帝位。","chunks":[["舜年二十以孝聞，年三十堯舉之，年五十攝行天子事，年五十八堯崩，年六十一代堯踐帝位。","zh-Hant"]]},{"id":"shiji_ch-1_p-27_s-2","passageId":"shiji_ch-1_p-27","order":2,"canonicalText":"踐帝位三十九年，南巡狩，崩於蒼梧之野。","chunks":[["踐帝位三十九年，南巡狩，崩於蒼梧之野。","zh-Hant"]]},{"id":"shiji_ch-1_p-27_s-3","passageId":"shiji_ch-1_p-27","order":3,"canonicalText":"葬於江南九嶷，是為零陵。","chunks":[["葬於江南九疑，是為零陵。","zh-Hant"]]},{"id":"shiji_ch-1_p-27_s-4","passageId":"shiji_ch-1_p-27","order":4,"canonicalText":"舜之踐帝位，載天子旗，往朝父瞽叟，夔夔齋慄，顧問敬肅，如子道。","chunks":[["舜之踐帝位，載天子旗，往朝父瞽叟，夔夔唯謹，如子道。","zh-Hant"]]},{"id":"shiji_ch-1_p-27_s-5","passageId":"shiji_ch-1_p-27","order":5,"canonicalText":"封弟象為諸侯。","chunks":[["封弟象為諸侯。","zh-Hant"]]},{"id":"shiji_ch-1_p-27_s-6","passageId":"shiji_ch-1_p-27","order":6,"canonicalText":"舜子商均亦不肖，舜乃預薦禹於天。","chunks":[["舜子商均亦不肖，舜乃豫薦禹於天。","zh-Hant"]]},{"id":"shiji_ch-1_p-27_s-7","passageId":"shiji_ch-1_p-27","order":7,"canonicalText":"十七年而崩。","chunks":[["十七年而崩。","zh-Hant"]]},{"id":"shiji_ch-1_p-27_s-8","passageId":"shiji_ch-1_p-27","order":8,"canonicalText":"三年喪畢，禹亦乃讓商均，如舜讓丹朱之故。","chunks":[["三年喪畢，禹亦乃讓舜子，如舜讓堯子。","zh-Hant"]]},{"id":"shiji_ch-1_p-27_s-9","passageId":"shiji_ch-1_p-27","order":9,"canonicalText":"諸侯歸之，然後禹踐天子位。","chunks":[["諸侯歸之，然後禹踐天子位。","zh-Hant"]]},{"id":"shiji_ch-1_p-27_s-10","passageId":"shiji_ch-1_p-27","order":10,"canonicalText":"堯子丹朱，舜子商均，皆有疆土，以奉先祀。","chunks":[["堯子丹朱，舜子商均，皆有疆土，以奉先祀。","zh-Hant"]]},{"id":"shiji_ch-1_p-27_s-11","passageId":"shiji_ch-1_p-27","order":11,"canonicalText":"服其服，禮樂如之。","chunks":[["服其服，禮樂如之。","zh-Hant"]]},{"id":"shiji_ch-1_p-27_s-12","passageId":"shiji_ch-1_p-27","order":12,"canonicalText":"以客見天子，天子弗臣，示不敢專也。","chunks":[["以客見天子，天子弗臣，示不敢專也。","zh-Hant"]]},{"id":"shiji_ch-1_p-28_s-1","passageId":"shiji_ch-1_p-28","order":1,"canonicalText":"自黃帝至舜、禹，皆同姓而異其國號，以章明德。","chunks":[["自黃帝至舜、禹，皆同姓而異其國號，以章明德。","zh-Hant"]]},{"id":"shiji_ch-1_p-28_s-2","passageId":"shiji_ch-1_p-28","order":2,"canonicalText":"故黃帝為有熊，帝顓頊為高陽，帝嚳為高辛，帝堯為陶唐，帝舜為有虞。","chunks":[["故黃帝為有熊，帝顓頊為高陽，帝嚳為高辛，帝堯為陶唐，帝舜為有虞。","zh-Hant"]]},{"id":"shiji_ch-1_p-28_s-3","passageId":"shiji_ch-1_p-28","order":3,"canonicalText":"帝禹為夏後而別氏，姓姒氏。","chunks":[["帝禹為夏後而別氏，姓姒氏。","zh-Hant"]]},{"id":"shiji_ch-1_p-28_s-4","passageId":"shiji_ch-1_p-28","order":4,"canonicalText":"契為商，姓子氏。","chunks":[["契為商，姓子氏。","zh-Hant"]]},{"id":"shiji_ch-1_p-28_s-5","passageId":"shiji_ch-1_p-28","order":5,"canonicalText":"棄為周，姓姬氏。","chunks":[["棄為周，姓姬氏。","zh-Hant"]]},{"id":"shiji_ch-1_p-29_s-1","passageId":"shiji_ch-1_p-29","order":1,"canonicalText":"太史公曰：學者多稱五帝，尚矣。","chunks":[["太史公曰：學者多稱五帝，尚矣。","zh-Hant"]]},{"id":"shiji_ch-1_p-29_s-2","passageId":"shiji_ch-1_p-29","order":2,"canonicalText":"然尚書獨載堯以來；","chunks":[["然尚書獨載堯以來；","zh-Hant"]]},{"id":"shiji_ch-1_p-29_s-3","passageId":"shiji_ch-1_p-29","order":3,"canonicalText":"而百家言黃帝，其文不雅馴，薦紳先生難言之。","chunks":[["而百家言黃帝，其文不雅馴，薦紳先生難言之。","zh-Hant"]]},{"id":"shiji_ch-1_p-29_s-4","passageId":"shiji_ch-1_p-29","order":4,"canonicalText":"孔子所傳宰予問五帝德及帝系姓，儒者或不傳。","chunks":[["孔子所傳宰予問五帝德及帝系姓，儒者或不傳。","zh-Hant"]]},{"id":"shiji_ch-1_p-29_s-5","passageId":"shiji_ch-1_p-29","order":5,"canonicalText":"餘嘗西至空桐，北過涿鹿，東漸於海，南浮江淮矣，至長老皆各往往稱黃帝、堯、舜之處，風教固殊焉，總之不離古文者近是。","chunks":[["餘嘗西至空桐，北過涿鹿，東漸於海，南浮江淮矣，至長老皆各往往稱黃帝、堯、舜之處，風教固殊焉，總之不離古文者近是。","zh-Hant"]]},{"id":"shiji_ch-1_p-29_s-6","passageId":"shiji_ch-1_p-29","order":6,"canonicalText":"予觀春秋、國語，其發明五帝德、帝系姓章矣，顧弟弗深考，其所表見皆不虛。","chunks":[["予觀春秋、國語，其發明五帝德、帝系姓章矣，顧弟弗深考，其所表見皆不虛。","zh-Hant"]]},{"id":"shiji_ch-1_p-29_s-7","passageId":"shiji_ch-1_p-29","order":7,"canonicalText":"書缺有間矣，其軼乃時時見於他說。","chunks":[["書缺有閒矣，其軼乃時時見於他說。","zh-Hant"]]},{"id":"shiji_ch-1_p-29_s-8","passageId":"shiji_ch-1_p-29","order":8,"canonicalText":"非好學深思，心知其意，固難為淺見寡聞者道也。","chunks":[["非好學深思，心知其意，固難為淺見寡聞道也。","zh-Hant"]]},{"id":"shiji_ch-1_p-29_s-9","passageId":"shiji_ch-1_p-29","order":9,"canonicalText":"餘並論次，擇其言尤雅者，故著為本紀書首。","chunks":[["餘並論次，擇其言尤雅者，故著為本紀書首。","zh-Hant"]]},{"id":"shiji_ch-2_p-1_s-1","passageId":"shiji_ch-2_p-1","order":1,"canonicalText":"夏禹，名曰文命。","chunks":[["夏禹，名曰文命。","zh-Hant"]]},{"id":"shiji_ch-2_p-1_s-2","passageId":"shiji_ch-2_p-1","order":2,"canonicalText":"禹之父曰鯀，鯀之父曰帝顓頊，顓頊之父曰昌意，昌意之父曰黃帝。","chunks":[["禹之父曰鯀，鯀之父曰帝顓頊，顓頊之父曰昌意，昌意之父曰黃帝。","zh-Hant"]]},{"id":"shiji_ch-2_p-1_s-3","passageId":"shiji_ch-2_p-1","order":3,"canonicalText":"禹者，黃帝之玄孫而帝顓頊之孫也。","chunks":[["禹者，黃帝之玄孫而帝顓頊之孫也。","zh-Hant"]]},{"id":"shiji_ch-2_p-1_s-4","passageId":"shiji_ch-2_p-1","order":4,"canonicalText":"禹之曾大父昌意及父鯀皆不得在帝位，為人臣。","chunks":[["禹之曾大父昌意及父鯀皆不得在帝位，為人臣。","zh-Hant"]]},{"id":"shiji_ch-2_p-3_s-1","passageId":"shiji_ch-2_p-3","order":1,"canonicalText":"堯崩，帝舜問四嶽曰：「有能成美堯之事者使居官？","chunks":[["堯崩，帝舜問四嶽曰：「有能成美堯之事者使居官？","zh-Hant"]]},{"id":"shiji_ch-2_p-3_s-2","passageId":"shiji_ch-2_p-3","order":2,"canonicalText":"」皆曰：「伯禹為司空，可成美堯之功。","chunks":[["」皆曰：「伯禹為司空，可成美堯之功。","zh-Hant"]]},{"id":"shiji_ch-2_p-3_s-3","passageId":"shiji_ch-2_p-3","order":3,"canonicalText":"」舜曰：「嗟，然！","chunks":[["」舜曰：「嗟，然！","zh-Hant"]]},{"id":"shiji_ch-2_p-3_s-4","passageId":"shiji_ch-2_p-3","order":4,"canonicalText":"」乃命禹：「女平水土，維予之時，其懋哉！","chunks":[["」命禹：「女平水土，維是勉之。","zh-Hant"]]},{"id":"shiji_ch-2_p-3_s-5","passageId":"shiji_ch-2_p-3","order":5,"canonicalText":"」禹拜稽首，讓於契、后稷、皋陶。","chunks":[["」禹拜稽首，讓於契、后稷、皋陶。","zh-Hant"]]},{"id":"shiji_ch-2_p-3_s-6","passageId":"shiji_ch-2_p-3","order":6,"canonicalText":"舜曰：「往矣，汝諧！","chunks":[["舜曰：「女其往視爾事矣。","zh-Hant"]]},{"id":"shiji_ch-2_p-3_s-7","passageId":"shiji_ch-2_p-3","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"shiji_ch-2_p-4_s-1","passageId":"shiji_ch-2_p-4","order":1,"canonicalText":"禹為人敏給克勤；","chunks":[["禹為人敏給克勤；","zh-Hant"]]},{"id":"shiji_ch-2_p-4_s-2","passageId":"shiji_ch-2_p-4","order":2,"canonicalText":"其德不違，其仁可親，其言可信；","chunks":[["其德不違，其仁可親，其言可信；","zh-Hant"]]},{"id":"shiji_ch-2_p-4_s-3","passageId":"shiji_ch-2_p-4","order":3,"canonicalText":"聲為律，身為度，稱以出；","chunks":[["聲為律，身為度，稱以出；","zh-Hant"]]},{"id":"shiji_ch-2_p-4_s-4","passageId":"shiji_ch-2_p-4","order":4,"canonicalText":"亹亹穆穆，為綱為紀。","chunks":[["亹亹穆穆，為綱為紀。","zh-Hant"]]},{"id":"shiji_ch-2_p-7_s-1","passageId":"shiji_ch-2_p-7","order":1,"canonicalText":"濟、河維沇州：九河既道，雷夏既澤，雍、沮會同，桑土既蠶，於是民得下丘居土。","chunks":[["濟、河維沇州：九河既道，雷夏既澤，雍、沮會同，桑土既蠶，於是民得下丘居土。","zh-Hant"]]},{"id":"shiji_ch-2_p-7_s-2","passageId":"shiji_ch-2_p-7","order":2,"canonicalText":"其土黑墳，草繇木條。","chunks":[["其土黑墳，草繇木條。","zh-Hant"]]},{"id":"shiji_ch-2_p-7_s-3","passageId":"shiji_ch-2_p-7","order":3,"canonicalText":"田中下，賦貞，作十有三載乃同。","chunks":[["田中下，賦貞，作十有三年乃同。","zh-Hant"]]},{"id":"shiji_ch-2_p-7_s-4","passageId":"shiji_ch-2_p-7","order":4,"canonicalText":"其貢漆絲，篚織文。","chunks":[["其貢漆絲，其篚織文。","zh-Hant"]]},{"id":"shiji_ch-2_p-7_s-5","passageId":"shiji_ch-2_p-7","order":5,"canonicalText":"浮於濟、漯，通於河。","chunks":[["浮於濟、漯，通於河。","zh-Hant"]]},{"id":"shiji_ch-2_p-8_s-1","passageId":"shiji_ch-2_p-8","order":1,"canonicalText":"海岱維青州：堣夷既略，濰、淄其道。","chunks":[["海岱維青州：堣夷既略，濰、淄其道。","zh-Hant"]]},{"id":"shiji_ch-2_p-8_s-2","passageId":"shiji_ch-2_p-8","order":2,"canonicalText":"其土白墳，海濱廣潟，厥田斥鹵。","chunks":[["其土白墳，海濱廣潟，厥田斥鹵。","zh-Hant"]]},{"id":"shiji_ch-2_p-8_s-3","passageId":"shiji_ch-2_p-8","order":3,"canonicalText":"田上下，賦中上。","chunks":[["田上下，賦中上。","zh-Hant"]]},{"id":"shiji_ch-2_p-8_s-4","passageId":"shiji_ch-2_p-8","order":4,"canonicalText":"厥貢鹽絺，海物惟錯，岱畎絲枲鉛松怪石，萊夷為牧，篚檿絲。","chunks":[["厥貢鹽絺，海物維錯，岱畎絲、枲、鉛、松、怪石，萊夷為牧，其篚酓絲。","zh-Hant"]]},{"id":"shiji_ch-2_p-8_s-5","passageId":"shiji_ch-2_p-8","order":5,"canonicalText":"浮於汶，達於濟。","chunks":[["浮於汶，通於濟。","zh-Hant"]]},{"id":"shiji_ch-2_p-9_s-1","passageId":"shiji_ch-2_p-9","order":1,"canonicalText":"海岱及淮維徐州：淮、沂其治，蒙、羽其藝。","chunks":[["海岱及淮維徐州：淮、沂其治，蒙、羽其藝。","zh-Hant"]]},{"id":"shiji_ch-2_p-9_s-2","passageId":"shiji_ch-2_p-9","order":2,"canonicalText":"大野既都，東原底平。","chunks":[["大野既都，東原底平。","zh-Hant"]]},{"id":"shiji_ch-2_p-9_s-3","passageId":"shiji_ch-2_p-9","order":3,"canonicalText":"其土赤埴墳，草木漸包。","chunks":[["其土赤埴墳，草木漸包。","zh-Hant"]]},{"id":"shiji_ch-2_p-9_s-4","passageId":"shiji_ch-2_p-9","order":4,"canonicalText":"其田上中，賦中中。","chunks":[["其田上中，賦中中。","zh-Hant"]]},{"id":"shiji_ch-2_p-9_s-5","passageId":"shiji_ch-2_p-9","order":5,"canonicalText":"厥貢維土五色，羽畎夏翟，嶧陽孤桐，泗濱浮磬，淮夷蠙珠蚳魚。","chunks":[["貢維土五色，羽畎夏狄，嶧陽孤桐，泗濱浮磬，淮夷蠙珠臮魚，其篚玄纖縞。","zh-Hant"]]},{"id":"shiji_ch-2_p-9_s-6","passageId":"shiji_ch-2_p-9","order":6,"canonicalText":"浮於淮、泗，達於河。","chunks":[["浮於淮、泗，通於河。","zh-Hant"]]},{"id":"shiji_ch-2_p-10_s-1","passageId":"shiji_ch-2_p-10","order":1,"canonicalText":"淮海維揚州：彭蠡既都，陽鳥所居。","chunks":[["淮海維揚州：彭蠡既都，陽鳥所居。","zh-Hant"]]},{"id":"shiji_ch-2_p-10_s-2","passageId":"shiji_ch-2_p-10","order":2,"canonicalText":"三江既入，震澤致定。","chunks":[["三江既入，震澤致定。","zh-Hant"]]},{"id":"shiji_ch-2_p-10_s-3","passageId":"shiji_ch-2_p-10","order":3,"canonicalText":"竹箭既布。","chunks":[["竹箭既布。","zh-Hant"]]},{"id":"shiji_ch-2_p-10_s-4","passageId":"shiji_ch-2_p-10","order":4,"canonicalText":"其草惟夭，其木惟喬，其土塗泥。","chunks":[["其草惟夭，其木惟喬，其土塗泥。","zh-Hant"]]},{"id":"shiji_ch-2_p-10_s-5","passageId":"shiji_ch-2_p-10","order":5,"canonicalText":"田下下，賦下上雜。","chunks":[["田下下，賦下上上雜。","zh-Hant"]]},{"id":"shiji_ch-2_p-10_s-6","passageId":"shiji_ch-2_p-10","order":6,"canonicalText":"厥貢惟金三品，瑤、琨、竹箭，齒、革、羽、毛，島夷卉服，厥篚織貝，厥包橘、柚，錫貢。","chunks":[["貢金三品，瑤、琨、竹箭，齒、革、羽、旄，島夷卉服，其篚織貝，其包橘、柚錫貢。","zh-Hant"]]},{"id":"shiji_ch-2_p-10_s-7","passageId":"shiji_ch-2_p-10","order":7,"canonicalText":"沿於江、海，達於淮、泗。","chunks":[["均江海，通淮、泗。","zh-Hant"]]},{"id":"shiji_ch-2_p-11_s-1","passageId":"shiji_ch-2_p-11","order":1,"canonicalText":"荊及衡陽維荊州：江、漢朝宗於海。","chunks":[["荊及衡陽維荊州：江、漢朝宗於海。","zh-Hant"]]},{"id":"shiji_ch-2_p-11_s-2","passageId":"shiji_ch-2_p-11","order":2,"canonicalText":"九江甚中，沱、涔已道，雲土、夢為治。","chunks":[["九江甚中，沱、涔已道，雲土、夢為治。","zh-Hant"]]},{"id":"shiji_ch-2_p-11_s-3","passageId":"shiji_ch-2_p-11","order":3,"canonicalText":"其土塗泥。","chunks":[["其土塗泥。","zh-Hant"]]},{"id":"shiji_ch-2_p-11_s-4","passageId":"shiji_ch-2_p-11","order":4,"canonicalText":"田下中，賦上下。","chunks":[["田下中，賦上下。","zh-Hant"]]},{"id":"shiji_ch-2_p-11_s-5","passageId":"shiji_ch-2_p-11","order":5,"canonicalText":"厥貢羽、毛、齒、革，金三品，杶、幹、栝、柏，礪、砥、砮、丹，維箘、簵、楛，三國致貢：其名包匜菁茅，厥篚玄纁，編瑀，九江納錫大龜。","chunks":[["貢羽、旄、齒、革，金三品，杶、榦、栝、柏，礪、砥、砮、丹，維箘簬、楛，三國致貢其名，包匭菁茅，其篚玄纁璣組，九江入賜大龜。","zh-Hant"]]},{"id":"shiji_ch-2_p-11_s-6","passageId":"shiji_ch-2_p-11","order":6,"canonicalText":"浮於江、沱、涔、漢，逾於洛，至於南河。","chunks":[["浮於江、沱、涔、（於）漢，踰於雒，至於南河。","zh-Hant"]]},{"id":"shiji_ch-2_p-12_s-1","passageId":"shiji_ch-2_p-12","order":1,"canonicalText":"荊河惟豫州：伊、雒、瀍、澗既入於河，滎播既都，道荷澤，被明都。","chunks":[["荊河惟豫州：伊、雒、瀍、澗既入於河，滎播既都，道荷澤，被明都。","zh-Hant"]]},{"id":"shiji_ch-2_p-12_s-2","passageId":"shiji_ch-2_p-12","order":2,"canonicalText":"其土壤，下土墳壚。","chunks":[["其土壤，下土墳壚。","zh-Hant"]]},{"id":"shiji_ch-2_p-12_s-3","passageId":"shiji_ch-2_p-12","order":3,"canonicalText":"田中上，賦上中。","chunks":[["田中上，賦雜上中。","zh-Hant"]]},{"id":"shiji_ch-2_p-12_s-4","passageId":"shiji_ch-2_p-12","order":4,"canonicalText":"厥貢漆、枲，絺、紵，厥篚纖、纊，錫貢磬錯。","chunks":[["貢漆、絲、絺、紵，其篚纖絮，錫貢磬錯。","zh-Hant"]]},{"id":"shiji_ch-2_p-12_s-5","passageId":"shiji_ch-2_p-12","order":5,"canonicalText":"浮於洛，達於河。","chunks":[["浮於雒，達於河。","zh-Hant"]]},{"id":"shiji_ch-2_p-15_s-1","passageId":"shiji_ch-2_p-15","order":1,"canonicalText":"道九山：汧及岐至於荊山，踰於河；","chunks":[["道九山：汧及岐至於荊山，踰於河；","zh-Hant"]]},{"id":"shiji_ch-2_p-15_s-2","passageId":"shiji_ch-2_p-15","order":2,"canonicalText":"壺口、雷首至於太嶽；","chunks":[["壺口、雷首至於太嶽；","zh-Hant"]]},{"id":"shiji_ch-2_p-15_s-3","passageId":"shiji_ch-2_p-15","order":3,"canonicalText":"砥柱、析城至於王屋；","chunks":[["砥柱、析城至於王屋；","zh-Hant"]]},{"id":"shiji_ch-2_p-15_s-4","passageId":"shiji_ch-2_p-15","order":4,"canonicalText":"太行、常山至於碣石，入於海；","chunks":[["太行、常山至於碣石，入於海；","zh-Hant"]]},{"id":"shiji_ch-2_p-15_s-5","passageId":"shiji_ch-2_p-15","order":5,"canonicalText":"西傾、朱圉、鳥鼠至於太華；","chunks":[["西傾、朱圉、鳥鼠至於太華；","zh-Hant"]]},{"id":"shiji_ch-2_p-15_s-6","passageId":"shiji_ch-2_p-15","order":6,"canonicalText":"熊耳、外方、桐柏至於負尾；","chunks":[["熊耳、外方、桐柏至於負尾；","zh-Hant"]]},{"id":"shiji_ch-2_p-15_s-7","passageId":"shiji_ch-2_p-15","order":7,"canonicalText":"嶓冢至於荊山；","chunks":[["道嶓冢，至於荊山；","zh-Hant"]]},{"id":"shiji_ch-2_p-15_s-8","passageId":"shiji_ch-2_p-15","order":8,"canonicalText":"內方至於大別；","chunks":[["內方至於大別；","zh-Hant"]]},{"id":"shiji_ch-2_p-15_s-9","passageId":"shiji_ch-2_p-15","order":9,"canonicalText":"汶山之陽至於衡山，過九江，至於敷淺原。","chunks":[["汶山之陽至衡山，過九江，至於敷淺原。","zh-Hant"]]},{"id":"shiji_ch-2_p-18_s-1","passageId":"shiji_ch-2_p-18","order":1,"canonicalText":"令天子之國以外五百里甸服：百里賦納總，二百里納銍，三百里納秸服，四百里粟，五百里米。","chunks":[["令天子之國以外五百里甸服：百里賦納總，二百里納銍，三百里納秸服，四百里粟，五百里米。","zh-Hant"]]},{"id":"shiji_ch-2_p-18_s-2","passageId":"shiji_ch-2_p-18","order":2,"canonicalText":"甸服外五百里侯服：百里採，二百里男邦，三百里諸侯。","chunks":[["甸服外五百里侯服：百里採，二百里任國，三百里諸侯。","zh-Hant"]]},{"id":"shiji_ch-2_p-18_s-3","passageId":"shiji_ch-2_p-18","order":3,"canonicalText":"侯服外五百里綏服：三百里揆文教，二百里奮武衛。","chunks":[["侯服外五百里綏服：三百里揆文教，二百里奮武衛。","zh-Hant"]]},{"id":"shiji_ch-2_p-18_s-4","passageId":"shiji_ch-2_p-18","order":4,"canonicalText":"綏服外五百里要服：三百里夷，二百里蔡。","chunks":[["綏服外五百里要服：三百里夷，二百里蔡。","zh-Hant"]]},{"id":"shiji_ch-2_p-18_s-5","passageId":"shiji_ch-2_p-18","order":5,"canonicalText":"要服外五百里荒服：三百里蠻，二百里流。","chunks":[["要服外五百里荒服：三百里蠻，二百里流。","zh-Hant"]]},{"id":"shiji_ch-2_p-19_s-1","passageId":"shiji_ch-2_p-19","order":1,"canonicalText":"東漸於海，西被於流沙，朔、南暨：聲教訖於四海。","chunks":[["東漸於海，西被於流沙，朔、南暨：聲教訖於四海。","zh-Hant"]]},{"id":"shiji_ch-2_p-19_s-2","passageId":"shiji_ch-2_p-19","order":2,"canonicalText":"於是帝錫禹玄圭，以告成功於天下。","chunks":[["於是帝錫禹玄圭，以告成功於天下。","zh-Hant"]]},{"id":"shiji_ch-2_p-19_s-3","passageId":"shiji_ch-2_p-19","order":3,"canonicalText":"天下於是太平治。","chunks":[["天下於是太平治。","zh-Hant"]]},{"id":"shiji_ch-2_p-24_s-1","passageId":"shiji_ch-2_p-24","order":1,"canonicalText":"皋陶於是敬禹之德，令民皆則禹。","chunks":[["皋陶於是敬禹之德，令民皆則禹。","zh-Hant"]]},{"id":"shiji_ch-2_p-24_s-2","passageId":"shiji_ch-2_p-24","order":2,"canonicalText":"不如言，刑從之。","chunks":[["不如言，刑從之。","zh-Hant"]]},{"id":"shiji_ch-2_p-24_s-3","passageId":"shiji_ch-2_p-24","order":3,"canonicalText":"舜德大明。","chunks":[["舜德大明。","zh-Hant"]]},{"id":"shiji_ch-2_p-26_s-1","passageId":"shiji_ch-2_p-26","order":1,"canonicalText":"帝舜薦禹於天，為嗣。","chunks":[["帝舜薦禹於天，為嗣。","zh-Hant"]]},{"id":"shiji_ch-2_p-26_s-2","passageId":"shiji_ch-2_p-26","order":2,"canonicalText":"十七年而帝舜崩。","chunks":[["十七年而帝舜崩。","zh-Hant"]]},{"id":"shiji_ch-2_p-26_s-3","passageId":"shiji_ch-2_p-26","order":3,"canonicalText":"三年喪畢，禹辭闢舜之子商均於陽城。","chunks":[["三年喪畢，禹辭闢舜之子商均於陽城。","zh-Hant"]]},{"id":"shiji_ch-2_p-26_s-4","passageId":"shiji_ch-2_p-26","order":4,"canonicalText":"天下諸侯皆去商均而朝禹。","chunks":[["天下諸侯皆去商均而朝禹。","zh-Hant"]]},{"id":"shiji_ch-2_p-26_s-5","passageId":"shiji_ch-2_p-26","order":5,"canonicalText":"禹於是遂即天子位，南面朝天下，國號曰夏後，姓姒氏。","chunks":[["禹於是遂即天子位，南面朝天下，國號曰夏後，姓姒氏。","zh-Hant"]]},{"id":"shiji_ch-2_p-27_s-1","passageId":"shiji_ch-2_p-27","order":1,"canonicalText":"帝禹立而舉皋陶薦之，且授政焉，而皋陶卒。","chunks":[["帝禹立而舉皋陶薦之，且授政焉，而皋陶卒。","zh-Hant"]]},{"id":"shiji_ch-2_p-27_s-2","passageId":"shiji_ch-2_p-27","order":2,"canonicalText":"封皋陶之後於英、六，或在許。","chunks":[["封皋陶之後於英、六，或在許。","zh-Hant"]]},{"id":"shiji_ch-2_p-27_s-3","passageId":"shiji_ch-2_p-27","order":3,"canonicalText":"而後舉益，任之政。","chunks":[["而後舉益，任之政。","zh-Hant"]]},{"id":"shiji_ch-2_p-28_s-1","passageId":"shiji_ch-2_p-28","order":1,"canonicalText":"十年，帝禹東巡狩，至於會稽而崩。","chunks":[["十年，帝禹東巡狩，至於會稽而崩。","zh-Hant"]]},{"id":"shiji_ch-2_p-28_s-2","passageId":"shiji_ch-2_p-28","order":2,"canonicalText":"以天下授益。","chunks":[["以天下授益。","zh-Hant"]]},{"id":"shiji_ch-2_p-28_s-3","passageId":"shiji_ch-2_p-28","order":3,"canonicalText":"三年之喪畢，益讓帝禹之子啟，而闢居箕山之陽。","chunks":[["三年之喪畢，益讓帝禹之子啟，而闢居箕山之陽。","zh-Hant"]]},{"id":"shiji_ch-2_p-28_s-4","passageId":"shiji_ch-2_p-28","order":4,"canonicalText":"禹子啟賢，天下屬意焉。","chunks":[["禹子啟賢，天下屬意焉。","zh-Hant"]]},{"id":"shiji_ch-2_p-28_s-5","passageId":"shiji_ch-2_p-28","order":5,"canonicalText":"及禹崩，雖授益，益之佐禹日淺，天下未洽。","chunks":[["及禹崩，雖授益，益之佐禹日淺，天下未洽。","zh-Hant"]]},{"id":"shiji_ch-2_p-28_s-6","passageId":"shiji_ch-2_p-28","order":6,"canonicalText":"故諸侯皆去益而朝啟，曰：「吾君帝禹之子也。","chunks":[["故諸侯皆去益而朝啟，曰：「吾君帝禹之子也」。","zh-Hant"]]},{"id":"shiji_ch-2_p-28_s-7","passageId":"shiji_ch-2_p-28","order":7,"canonicalText":"」於是啟遂即天子之位，是為夏后帝啟。","chunks":[["於是啟遂即天子之位，是為夏后帝啟。","zh-Hant"]]},{"id":"shiji_ch-2_p-29_s-1","passageId":"shiji_ch-2_p-29","order":1,"canonicalText":"夏后帝啟，禹之子，其母塗山氏之女也。","chunks":[["夏后帝啟，禹之子，其母塗山氏之女也。","zh-Hant"]]},{"id":"shiji_ch-2_p-30_s-1","passageId":"shiji_ch-2_p-30","order":1,"canonicalText":"有扈氏不服，啟伐之，大戰於甘。","chunks":[["有扈氏不服，啟伐之，大戰於甘。","zh-Hant"]]},{"id":"shiji_ch-2_p-30_s-2","passageId":"shiji_ch-2_p-30","order":2,"canonicalText":"將戰，作甘誓，乃召六卿申之。","chunks":[["將戰，作甘誓，乃召六卿申之。","zh-Hant"]]},{"id":"shiji_ch-2_p-30_s-3","passageId":"shiji_ch-2_p-30","order":3,"canonicalText":"啟曰：「嗟！","chunks":[["啟曰：「嗟！","zh-Hant"]]},{"id":"shiji_ch-2_p-30_s-4","passageId":"shiji_ch-2_p-30","order":4,"canonicalText":"六事之人，予誓告女：有扈氏威侮五行，怠棄三正，天用剿絕其命，今予唯恭行天之罰。","chunks":[["六事之人，予誓告女：有扈氏威侮五行，怠棄三正，天用勦絕其命。","zh-Hant"]]},{"id":"shiji_ch-2_p-30_s-5","passageId":"shiji_ch-2_p-30","order":5,"canonicalText":"左不攻於左，汝不恭命；","chunks":[["今予維共行天之罰。","zh-Hant"]]},{"id":"shiji_ch-2_p-30_s-6","passageId":"shiji_ch-2_p-30","order":6,"canonicalText":"右不攻於右，汝不恭命；","chunks":[["左不攻於左，右不攻於右，女不共命。","zh-Hant"]]},{"id":"shiji_ch-2_p-30_s-7","passageId":"shiji_ch-2_p-30","order":7,"canonicalText":"御非其馬之正，汝不恭命。","chunks":[["御非其馬之政，女不共命。","zh-Hant"]]},{"id":"shiji_ch-2_p-30_s-8","passageId":"shiji_ch-2_p-30","order":8,"canonicalText":"用命，賞於祖；","chunks":[["用命，賞於祖；","zh-Hant"]]},{"id":"shiji_ch-2_p-30_s-9","passageId":"shiji_ch-2_p-30","order":9,"canonicalText":"不用命，戮於社，予則帑僇汝。","chunks":[["不用命，僇於社，予則帑僇女。","zh-Hant"]]},{"id":"shiji_ch-2_p-30_s-10","passageId":"shiji_ch-2_p-30","order":10,"canonicalText":"」遂滅有扈氏。","chunks":[["」遂滅有扈氏。","zh-Hant"]]},{"id":"shiji_ch-2_p-30_s-11","passageId":"shiji_ch-2_p-30","order":11,"canonicalText":"天下鹹朝。","chunks":[["天下鹹朝。","zh-Hant"]]},{"id":"shiji_ch-2_p-31_s-1","passageId":"shiji_ch-2_p-31","order":1,"canonicalText":"夏后帝啟崩，子帝太康立。","chunks":[["夏后帝啟崩，子帝太康立。","zh-Hant"]]},{"id":"shiji_ch-2_p-31_s-2","passageId":"shiji_ch-2_p-31","order":2,"canonicalText":"帝太康失國，昆弟五人，須於洛汭，作五子之歌。","chunks":[["帝太康失國，昆弟五人，須於洛汭，作五子之歌。","zh-Hant"]]},{"id":"shiji_ch-2_p-32_s-1","passageId":"shiji_ch-2_p-32","order":1,"canonicalText":"太康崩，弟中康立，是為帝中康。","chunks":[["太康崩，弟中康立，是為帝中康。","zh-Hant"]]},{"id":"shiji_ch-2_p-32_s-2","passageId":"shiji_ch-2_p-32","order":2,"canonicalText":"帝中康時，羲、和湎淫，廢時亂日。","chunks":[["帝中康時，羲、和湎淫，廢時亂日。","zh-Hant"]]},{"id":"shiji_ch-2_p-32_s-3","passageId":"shiji_ch-2_p-32","order":3,"canonicalText":"胤往徵之，作胤徵。","chunks":[["胤往徵之，作胤徵。","zh-Hant"]]},{"id":"shiji_ch-2_p-35_s-1","passageId":"shiji_ch-2_p-35","order":1,"canonicalText":"太史公曰：禹為姒姓，其後分封，用國為姓，故有夏后氏、有扈氏、有男氏、斟尋氏、彤城氏、褒氏、費氏、杞氏、繒氏、辛氏、冥氏、斟氏、戈氏。","chunks":[["太史公曰：禹為姒姓，其後分封，用國為姓，故有夏后氏、有扈氏、有男氏、斟尋氏、彤城氏、褒氏、費氏、杞氏、繒氏、辛氏、冥氏、斟（氏）戈氏。","zh-Hant"]]},{"id":"shiji_ch-2_p-35_s-2","passageId":"shiji_ch-2_p-35","order":2,"canonicalText":"杞、繒，夏後也。","chunks":[["孔子正夏時，學者多傳夏小正雲。","zh-Hant"]]},{"id":"shiji_ch-2_p-35_s-3","passageId":"shiji_ch-2_p-35","order":3,"canonicalText":"春秋之時，杞為微國，然其存者千有餘歲。","chunks":[["自虞、夏時，貢賦備矣。","zh-Hant"]]},{"id":"shiji_ch-2_p-35_s-4","passageId":"shiji_ch-2_p-35","order":4,"canonicalText":"自禹至桀，凡十四世，十七君，四百餘歲。","chunks":[["或言禹會諸侯江南，計功而崩，因葬焉，命曰會稽。","zh-Hant"]]},{"id":"shiji_ch-2_p-35_s-5","passageId":"shiji_ch-2_p-35","order":5,"canonicalText":"夏之興也以德，其衰也以淫，天命無常，唯德是輔，此百王之大戒也。","chunks":[["會稽者，會計也。","zh-Hant"]]},{"id":"shiji_ch-1_p-3_s-1","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-3","order":1,"canonicalText":"東至於海，登丸山，及岱宗。","chunks":[]},{"id":"shiji_ch-1_p-3_s-2","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-3","order":2,"canonicalText":"西至於空桐，登雞頭。","chunks":[]},{"id":"shiji_ch-1_p-3_s-3","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-3","order":3,"canonicalText":"南至於江，登熊、湘。","chunks":[]},{"id":"shiji_ch-1_p-3_s-4","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-3","order":4,"canonicalText":"北逐葷粥，合符釜山，而邑於涿鹿之阿。","chunks":[]},{"id":"shiji_ch-1_p-3_s-5","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-3","order":5,"canonicalText":"遷徙往來無常處，以師兵為營衛。","chunks":[]},{"id":"shiji_ch-1_p-3_s-6","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-3","order":6,"canonicalText":"官名皆以雲命，為雲師。","chunks":[]},{"id":"shiji_ch-1_p-3_s-7","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-3","order":7,"canonicalText":"置左右大監，監於萬國。","chunks":[]},{"id":"shiji_ch-1_p-3_s-8","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-3","order":8,"canonicalText":"萬國和，而鬼神山川公卿壇墠及西泰躋召，所從古以來。","chunks":[]},{"id":"shiji_ch-1_p-5_s-1","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-5","order":1,"canonicalText":"黃帝居於軒轅之丘，而娶於西陵之女，是為嫘祖。","chunks":[]},{"id":"shiji_ch-1_p-5_s-2","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-5","order":2,"canonicalText":"嫘祖為黃帝正妃，生二子，其後皆有天下：其一曰玄囂，是為青陽，青陽降居江水；","chunks":[]},{"id":"shiji_ch-1_p-5_s-3","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-5","order":3,"canonicalText":"其二曰昌意，降居若水。","chunks":[]},{"id":"shiji_ch-1_p-5_s-4","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-5","order":4,"canonicalText":"昌意娶蜀山氏女，曰昌僕，生高陽，高陽有聖德。","chunks":[]},{"id":"shiji_ch-1_p-5_s-5","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-5","order":5,"canonicalText":"黃帝崩，葬橋山。","chunks":[]},{"id":"shiji_ch-1_p-5_s-6","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-5","order":6,"canonicalText":"其孫昌意之子高陽立，是為帝顓頊也。","chunks":[]},{"id":"shiji_ch-1_p-9_s-1","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-9","order":1,"canonicalText":"高辛生而神靈，自言其名。","chunks":[]},{"id":"shiji_ch-1_p-9_s-2","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-9","order":2,"canonicalText":"普施利物，不於其身。","chunks":[]},{"id":"shiji_ch-1_p-9_s-3","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-9","order":3,"canonicalText":"聰以知遠，明以察微。","chunks":[]},{"id":"shiji_ch-1_p-9_s-4","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-9","order":4,"canonicalText":"順天之義，知民之急。","chunks":[]},{"id":"shiji_ch-1_p-9_s-5","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-9","order":5,"canonicalText":"仁而威，惠而信，修身而天下服。","chunks":[]},{"id":"shiji_ch-1_p-9_s-6","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-9","order":6,"canonicalText":"取地之財而節用之，撫教萬民而利誨之，歷日月而迎送之，明鬼神而敬事之。","chunks":[]},{"id":"shiji_ch-1_p-9_s-7","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-9","order":7,"canonicalText":"其德莫大焉。","chunks":[]},{"id":"shiji_ch-1_p-12_s-1","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-12","order":1,"canonicalText":"乃命羲、和，敬順昊天，數法日月星辰，敬授民時。","chunks":[]},{"id":"shiji_ch-1_p-12_s-2","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-12","order":2,"canonicalText":"分命羲仲，居鬱夷，曰暘谷。","chunks":[]},{"id":"shiji_ch-1_p-12_s-3","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-12","order":3,"canonicalText":"敬道日出，便程東作。","chunks":[]},{"id":"shiji_ch-1_p-12_s-4","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-12","order":4,"canonicalText":"日中，星鳥，以殷仲春。","chunks":[]},{"id":"shiji_ch-1_p-12_s-5","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-12","order":5,"canonicalText":"厥民析，鳥獸孳尾。","chunks":[]},{"id":"shiji_ch-1_p-12_s-6","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-12","order":6,"canonicalText":"申命羲叔，居南交。","chunks":[]},{"id":"shiji_ch-1_p-12_s-7","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-12","order":7,"canonicalText":"便程南為，敬致。","chunks":[]},{"id":"shiji_ch-1_p-12_s-8","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-12","order":8,"canonicalText":"日永，星火，以正仲夏。","chunks":[]},{"id":"shiji_ch-1_p-12_s-9","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-12","order":9,"canonicalText":"厥民因，鳥獸希革。","chunks":[]},{"id":"shiji_ch-1_p-12_s-10","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-12","order":10,"canonicalText":"申命和仲，居西土，曰昧谷。","chunks":[]},{"id":"shiji_ch-1_p-12_s-11","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-12","order":11,"canonicalText":"敬道日入，便程西成。","chunks":[]},{"id":"shiji_ch-1_p-12_s-12","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-12","order":12,"canonicalText":"夜中，星虛，以正仲秋。","chunks":[]},{"id":"shiji_ch-1_p-12_s-13","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-12","order":13,"canonicalText":"厥民夷易，鳥獸毛毨。","chunks":[]},{"id":"shiji_ch-1_p-12_s-14","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-12","order":14,"canonicalText":"申命和叔，居北方，曰幽都。","chunks":[]},{"id":"shiji_ch-1_p-12_s-15","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-12","order":15,"canonicalText":"便在伏物。","chunks":[]},{"id":"shiji_ch-1_p-12_s-16","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-12","order":16,"canonicalText":"日短，星昴，以正仲冬。","chunks":[]},{"id":"shiji_ch-1_p-12_s-17","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-12","order":17,"canonicalText":"厥民燠，鳥獸氄毛。","chunks":[]},{"id":"shiji_ch-1_p-12_s-18","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-12","order":18,"canonicalText":"歲三百六十六日，以閏月正四時。","chunks":[]},{"id":"shiji_ch-1_p-12_s-19","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-12","order":19,"canonicalText":"信飭百官，眾功皆興。","chunks":[]},{"id":"shiji_ch-1_p-14_s-1","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-14","order":1,"canonicalText":"堯曰：「嗟！","chunks":[]},{"id":"shiji_ch-1_p-14_s-2","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-14","order":2,"canonicalText":"四嶽：朕在位七十載，汝能庸命，踐朕位？","chunks":[]},{"id":"shiji_ch-1_p-14_s-3","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-14","order":3,"canonicalText":"」嶽應曰：「鄙德忝帝位。","chunks":[]},{"id":"shiji_ch-1_p-14_s-4","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-14","order":4,"canonicalText":"」堯曰：「悉舉貴戚及疏遠隱匿者。","chunks":[]},{"id":"shiji_ch-1_p-14_s-5","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-14","order":5,"canonicalText":"」眾皆言於堯曰：「有矜在民間，曰虞舜。","chunks":[]},{"id":"shiji_ch-1_p-14_s-6","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-14","order":6,"canonicalText":"」堯曰：「然，朕聞之。","chunks":[]},{"id":"shiji_ch-1_p-14_s-7","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-14","order":7,"canonicalText":"其何如？","chunks":[]},{"id":"shiji_ch-1_p-14_s-8","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-14","order":8,"canonicalText":"」嶽曰：「盲者子。","chunks":[]},{"id":"shiji_ch-1_p-14_s-9","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-14","order":9,"canonicalText":"父頑，母嚚，弟傲，能和以孝，烝烝治，不格姦。","chunks":[]},{"id":"shiji_ch-1_p-14_s-10","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-14","order":10,"canonicalText":"」","chunks":[]},{"id":"shiji_ch-1_p-15_s-1","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-15","order":1,"canonicalText":"堯善之，乃使舜慎和五典，五典能從。","chunks":[]},{"id":"shiji_ch-1_p-15_s-2","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-15","order":2,"canonicalText":"乃遍入百官，百官時序。","chunks":[]},{"id":"shiji_ch-1_p-15_s-3","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-15","order":3,"canonicalText":"賓於四門，四門穆穆，諸侯遠方賓客皆敬。","chunks":[]},{"id":"shiji_ch-1_p-15_s-4","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-15","order":4,"canonicalText":"堯乃試舜五典百官，皆修。","chunks":[]},{"id":"shiji_ch-1_p-16_s-1","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-16","order":1,"canonicalText":"於是帝堯老，命舜攝行天子之政，以觀天命。","chunks":[]},{"id":"shiji_ch-1_p-16_s-2","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-16","order":2,"canonicalText":"舜乃在璿璣玉衡，以齊七政。","chunks":[]},{"id":"shiji_ch-1_p-16_s-3","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-16","order":3,"canonicalText":"遂類於上帝，禋於六宗，望於山川，遍於羣神。","chunks":[]},{"id":"shiji_ch-1_p-16_s-4","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-16","order":4,"canonicalText":"輯五瑞，擇吉月日，見四嶽諸牧，班瑞。","chunks":[]},{"id":"shiji_ch-1_p-18_s-1","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-18","order":1,"canonicalText":"堯立七十年得舜，二十年而老，令舜攝行天子之政，薦之於天。","chunks":[]},{"id":"shiji_ch-1_p-18_s-2","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-18","order":2,"canonicalText":"堯闢位凡二十八年而崩。","chunks":[]},{"id":"shiji_ch-1_p-18_s-3","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-18","order":3,"canonicalText":"百姓悲哀，如喪考妣。","chunks":[]},{"id":"shiji_ch-1_p-18_s-4","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-18","order":4,"canonicalText":"三年，四方莫舉樂，以思堯。","chunks":[]},{"id":"shiji_ch-1_p-18_s-5","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-18","order":5,"canonicalText":"堯知子丹朱之不肖，不足授天下，於是乃權授舜。","chunks":[]},{"id":"shiji_ch-1_p-18_s-6","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-18","order":6,"canonicalText":"授舜，則天下得其利而丹朱病；","chunks":[]},{"id":"shiji_ch-1_p-18_s-7","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-18","order":7,"canonicalText":"授丹朱，則天下病而丹朱得其利。","chunks":[]},{"id":"shiji_ch-1_p-18_s-8","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-18","order":8,"canonicalText":"堯曰：「終不以天下之病而利一人」，而卒以此天下授舜。","chunks":[]},{"id":"shiji_ch-1_p-18_s-9","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-18","order":9,"canonicalText":"堯崩，三年之喪畢，舜讓闢丹朱於南河之南。","chunks":[]},{"id":"shiji_ch-1_p-18_s-10","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-18","order":10,"canonicalText":"諸侯朝覲者不之丹朱而之舜，獄訟者不之丹朱而之舜，謳歌者不謳歌丹朱而謳歌舜。","chunks":[]},{"id":"shiji_ch-1_p-18_s-11","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-18","order":11,"canonicalText":"舜曰：「天也夫！","chunks":[]},{"id":"shiji_ch-1_p-18_s-12","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-18","order":12,"canonicalText":"」乃之中國踐天子位，是為帝舜。","chunks":[]},{"id":"shiji_ch-1_p-22_s-1","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-22","order":1,"canonicalText":"舜年二十以孝聞。","chunks":[]},{"id":"shiji_ch-1_p-22_s-2","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-22","order":2,"canonicalText":"三十而帝堯問可用者，四嶽鹹薦虞舜，曰可。","chunks":[]},{"id":"shiji_ch-1_p-22_s-3","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-22","order":3,"canonicalText":"於是堯乃以二女妻舜以觀其內，使九男與處以觀其外。","chunks":[]},{"id":"shiji_ch-1_p-22_s-4","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-22","order":4,"canonicalText":"舜居媯汭，內行彌謹。","chunks":[]},{"id":"shiji_ch-1_p-22_s-5","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-22","order":5,"canonicalText":"堯二女不敢以貴驕事舜親戚，甚有婦道。","chunks":[]},{"id":"shiji_ch-1_p-22_s-6","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-22","order":6,"canonicalText":"堯九男皆益敦。","chunks":[]},{"id":"shiji_ch-1_p-22_s-7","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-22","order":7,"canonicalText":"舜耕歷山，歷山之人皆讓畔；","chunks":[]},{"id":"shiji_ch-1_p-22_s-8","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-22","order":8,"canonicalText":"漁雷澤，雷澤上人皆讓居；","chunks":[]},{"id":"shiji_ch-1_p-22_s-9","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-22","order":9,"canonicalText":"陶河濱，河濱器皆不苦窳。","chunks":[]},{"id":"shiji_ch-1_p-22_s-10","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-22","order":10,"canonicalText":"一年而所居成聚，二年成邑，三年成都。","chunks":[]},{"id":"shiji_ch-1_p-22_s-11","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-22","order":11,"canonicalText":"堯乃賜舜紵衣，與琴，為築倉廩，予牛羊。","chunks":[]},{"id":"shiji_ch-1_p-22_s-12","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-22","order":12,"canonicalText":"瞽叟尚復欲殺之，使舜上塗廩，瞽叟從下縱火焚廩。","chunks":[]},{"id":"shiji_ch-1_p-22_s-13","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-22","order":13,"canonicalText":"舜乃以兩笠自扞而下，去，得不死。","chunks":[]},{"id":"shiji_ch-1_p-22_s-14","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-22","order":14,"canonicalText":"後瞽叟又使舜穿井，舜穿井為匿空旁出。","chunks":[]},{"id":"shiji_ch-1_p-22_s-15","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-22","order":15,"canonicalText":"舜既入深，瞽叟與象共下土實井，舜從匿空出，去。","chunks":[]},{"id":"shiji_ch-1_p-22_s-16","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-22","order":16,"canonicalText":"瞽叟、象喜，以舜為已死。","chunks":[]},{"id":"shiji_ch-1_p-22_s-17","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-22","order":17,"canonicalText":"象曰：「本謀者象。","chunks":[]},{"id":"shiji_ch-1_p-22_s-18","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-22","order":18,"canonicalText":"」象與其父母分，於是曰：「舜妻堯二女，與琴，象取之。","chunks":[]},{"id":"shiji_ch-1_p-22_s-19","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-22","order":19,"canonicalText":"牛羊倉廩予父母。","chunks":[]},{"id":"shiji_ch-1_p-22_s-20","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-22","order":20,"canonicalText":"」象往入舜宮，舜在牀琴。","chunks":[]},{"id":"shiji_ch-1_p-22_s-21","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-22","order":21,"canonicalText":"象忪忪，恥相見。","chunks":[]},{"id":"shiji_ch-1_p-22_s-22","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-22","order":22,"canonicalText":"舜曰：「我思爾吏正！","chunks":[]},{"id":"shiji_ch-1_p-22_s-23","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-22","order":23,"canonicalText":"」舜復事瞽叟愛弟彌謹。","chunks":[]},{"id":"shiji_ch-1_p-24_s-1","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-24","order":1,"canonicalText":"昔帝鴻氏有不才子，掩義隱賊，好行兇慝，天下謂之渾沌。","chunks":[]},{"id":"shiji_ch-1_p-24_s-2","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-24","order":2,"canonicalText":"少暤氏有不才子，毀信惡忠，崇飾惡言，天下謂之窮奇。","chunks":[]},{"id":"shiji_ch-1_p-24_s-3","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-24","order":3,"canonicalText":"顓頊氏有不才子，不可教訓，不知話言，天下謂之檮杌。","chunks":[]},{"id":"shiji_ch-1_p-24_s-4","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-24","order":4,"canonicalText":"此三族世憂之。","chunks":[]},{"id":"shiji_ch-1_p-24_s-5","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-24","order":5,"canonicalText":"至帝堯，堯未能去。","chunks":[]},{"id":"shiji_ch-1_p-24_s-6","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-24","order":6,"canonicalText":"縉雲氏有不才子，貪於飲食，冒於貨賄，天下謂之饕餮，天下惡之，比之三兇。","chunks":[]},{"id":"shiji_ch-1_p-24_s-7","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-24","order":7,"canonicalText":"舜賓於四門，乃流四兇族，遷於四裔，以禦螭魅，於是四門闢，言毋兇人也。","chunks":[]},{"id":"shiji_ch-1_p-25_s-1","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-25","order":1,"canonicalText":"舜入於大麓，烈風雷雨不迷，堯乃知舜之足授天下。","chunks":[]},{"id":"shiji_ch-1_p-25_s-2","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-25","order":2,"canonicalText":"堯老，使舜攝行天子政，巡狩。","chunks":[]},{"id":"shiji_ch-1_p-25_s-3","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-25","order":3,"canonicalText":"舜得舉用事二十年，而堯使攝政。","chunks":[]},{"id":"shiji_ch-1_p-25_s-4","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-25","order":4,"canonicalText":"攝政八年而堯崩。","chunks":[]},{"id":"shiji_ch-1_p-25_s-5","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-25","order":5,"canonicalText":"三年喪畢，讓丹朱，天下歸舜。","chunks":[]},{"id":"shiji_ch-1_p-26_s-1","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-26","order":1,"canonicalText":"此二十二人鹹成厥功：皋陶為大理，平，民各伏得其實；","chunks":[]},{"id":"shiji_ch-1_p-26_s-2","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-26","order":2,"canonicalText":"伯夷主禮，上下鹹讓；","chunks":[]},{"id":"shiji_ch-1_p-26_s-3","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-26","order":3,"canonicalText":"垂主工師，百工緻功；","chunks":[]},{"id":"shiji_ch-1_p-26_s-4","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-26","order":4,"canonicalText":"益主虞，山澤闢；","chunks":[]},{"id":"shiji_ch-1_p-26_s-5","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-26","order":5,"canonicalText":"棄主稷，百穀熟；","chunks":[]},{"id":"shiji_ch-1_p-26_s-6","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-26","order":6,"canonicalText":"契主司徒，百姓親；","chunks":[]},{"id":"shiji_ch-1_p-26_s-7","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-26","order":7,"canonicalText":"龍主賓客，遠人至；","chunks":[]},{"id":"shiji_ch-1_p-26_s-8","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-26","order":8,"canonicalText":"十二牧行而九州莫敢闢違；","chunks":[]},{"id":"shiji_ch-1_p-26_s-9","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-26","order":9,"canonicalText":"唯禹之功為大，披九山，通九川，陂九澤，決九河，定九州，各以其職來貢，不失厥宜。","chunks":[]},{"id":"shiji_ch-1_p-26_s-10","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-26","order":10,"canonicalText":"方五千裏，至於荒服。","chunks":[]},{"id":"shiji_ch-1_p-26_s-11","chapterId":"shiji_ch-1","passageId":"shiji_ch-1_p-26","order":11,"canonicalText":"南撫交阯、北發，西戎、析支、渠廋、氐、羌，北山戎、發、息慎，東長、鳥夷，四海之內鹹戴帝舜之功。","chunks":[]},{"id":"shiji_ch-2_p-2_s-1","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-2","order":1,"canonicalText":"當帝堯之時，鴻水滔天，浩浩懷山襄陵，下民其憂。","chunks":[]},{"id":"shiji_ch-2_p-2_s-2","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-2","order":2,"canonicalText":"堯求能治水者，群臣四嶽皆曰鯀可。","chunks":[]},{"id":"shiji_ch-2_p-2_s-3","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-2","order":3,"canonicalText":"堯曰：「鯀為人負命毀族，不可。","chunks":[]},{"id":"shiji_ch-2_p-2_s-4","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-2","order":4,"canonicalText":"」四嶽曰：「等之未有賢於鯀者，願帝試之。","chunks":[]},{"id":"shiji_ch-2_p-2_s-5","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-2","order":5,"canonicalText":"」於是堯聽四嶽，用鯀治水。","chunks":[]},{"id":"shiji_ch-2_p-2_s-6","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-2","order":6,"canonicalText":"九年而水不息，功用不成。","chunks":[]},{"id":"shiji_ch-2_p-5_s-1","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-5","order":1,"canonicalText":"禹乃遂與益、后稷奉帝命，命諸侯百姓興人徒以傅土，行山表木，定高山大川。","chunks":[]},{"id":"shiji_ch-2_p-5_s-2","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-5","order":2,"canonicalText":"禹傷先人父鯀功之不成受誅，乃勞身焦思，居外十三年，過家門不敢入。","chunks":[]},{"id":"shiji_ch-2_p-5_s-3","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-5","order":3,"canonicalText":"薄衣食，致孝於鬼神。","chunks":[]},{"id":"shiji_ch-2_p-5_s-4","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-5","order":4,"canonicalText":"卑宮室，致費於溝淢。","chunks":[]},{"id":"shiji_ch-2_p-5_s-5","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-5","order":5,"canonicalText":"陸行乘車，水行乘船，泥行乘橇，山行乘檋。","chunks":[]},{"id":"shiji_ch-2_p-5_s-6","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-5","order":6,"canonicalText":"左準繩，右規矩，載四時，以開九州，通九道，陂九澤，度九山。","chunks":[]},{"id":"shiji_ch-2_p-6_s-1","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-6","order":1,"canonicalText":"禹行自冀州始。","chunks":[]},{"id":"shiji_ch-2_p-6_s-2","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-6","order":2,"canonicalText":"冀州：既載壺口，治梁及岐。","chunks":[]},{"id":"shiji_ch-2_p-6_s-3","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-6","order":3,"canonicalText":"既修太原，至於嶽陽。","chunks":[]},{"id":"shiji_ch-2_p-6_s-4","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-6","order":4,"canonicalText":"覃懷致功，至於衡漳。","chunks":[]},{"id":"shiji_ch-2_p-6_s-5","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-6","order":5,"canonicalText":"其土白壤。","chunks":[]},{"id":"shiji_ch-2_p-6_s-6","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-6","order":6,"canonicalText":"賦中上錯，田上中。","chunks":[]},{"id":"shiji_ch-2_p-6_s-7","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-6","order":7,"canonicalText":"常山、衛、洹既治，漳水既道。","chunks":[]},{"id":"shiji_ch-2_p-6_s-8","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-6","order":8,"canonicalText":"其貢漆絲，篚織文。","chunks":[]},{"id":"shiji_ch-2_p-6_s-9","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-6","order":9,"canonicalText":"治夾右碣石，入於海。","chunks":[]},{"id":"shiji_ch-2_p-13_s-1","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-13","order":1,"canonicalText":"華陽黑水惟梁州：汶、嶓既藝，沱、涔既道，蔡、蒙旅平，和夷厎績。","chunks":[]},{"id":"shiji_ch-2_p-13_s-2","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-13","order":2,"canonicalText":"其土青驪。","chunks":[]},{"id":"shiji_ch-2_p-13_s-3","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-13","order":3,"canonicalText":"田下上，賦下中三錯。","chunks":[]},{"id":"shiji_ch-2_p-13_s-4","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-13","order":4,"canonicalText":"厥貢璆、鐵、銀、鏤、砮、磬，熊、羆、狐、狸、織皮，西傾因桓是來，浮於潛，逾於沔，入於渭，亂於河。","chunks":[]},{"id":"shiji_ch-2_p-14_s-1","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-14","order":1,"canonicalText":"黑水西河惟雍州：弱水既西，涇屬渭汭。","chunks":[]},{"id":"shiji_ch-2_p-14_s-2","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-14","order":2,"canonicalText":"漆、沮既從，灃水所同。","chunks":[]},{"id":"shiji_ch-2_p-14_s-3","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-14","order":3,"canonicalText":"荊、岐已旅，終南、敦物至於鳥鼠。","chunks":[]},{"id":"shiji_ch-2_p-14_s-4","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-14","order":4,"canonicalText":"原隰底績，至於都野。","chunks":[]},{"id":"shiji_ch-2_p-14_s-5","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-14","order":5,"canonicalText":"三危既度，三苗大序。","chunks":[]},{"id":"shiji_ch-2_p-14_s-6","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-14","order":6,"canonicalText":"其土黃壤。","chunks":[]},{"id":"shiji_ch-2_p-14_s-7","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-14","order":7,"canonicalText":"田上上，賦中下。","chunks":[]},{"id":"shiji_ch-2_p-14_s-8","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-14","order":8,"canonicalText":"厥貢球、琳、琅玕。","chunks":[]},{"id":"shiji_ch-2_p-14_s-9","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-14","order":9,"canonicalText":"浮於積石，至於龍門西河，會於渭汭。","chunks":[]},{"id":"shiji_ch-2_p-16_s-1","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-16","order":1,"canonicalText":"道九川：弱水至於合黎，餘波入於流沙。","chunks":[]},{"id":"shiji_ch-2_p-16_s-2","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-16","order":2,"canonicalText":"道黑水，至於三危，入於南海。","chunks":[]},{"id":"shiji_ch-2_p-16_s-3","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-16","order":3,"canonicalText":"道河積石，至於龍門，南至華陰，東至砥柱，又東至盟津，過洛汭，至於大伾，北過降水，至於大陸，北播為九河，同為逆河，入於海。","chunks":[]},{"id":"shiji_ch-2_p-16_s-4","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-16","order":4,"canonicalText":"道沇水，東為濟，入於河，泆為滎，東出陶丘北，又東至於荷澤，東南會於汶，又東北入於海。","chunks":[]},{"id":"shiji_ch-2_p-16_s-5","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-16","order":5,"canonicalText":"道淮自桐柏，東會於泗、沂，東入於海。","chunks":[]},{"id":"shiji_ch-2_p-16_s-6","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-16","order":6,"canonicalText":"道江自岷山，東別為沱，又東至於澧，過九江，至於東陵，東迤北會於匯，東為中江，入於海。","chunks":[]},{"id":"shiji_ch-2_p-17_s-1","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-17","order":1,"canonicalText":"於是九州攸同，四奧既居，九山刊旅，九川滌原，九澤既陂，四海會同。","chunks":[]},{"id":"shiji_ch-2_p-17_s-2","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-17","order":2,"canonicalText":"六府甚修，眾土交正，致慎財賦，鹹則三壤，成賦中邦。","chunks":[]},{"id":"shiji_ch-2_p-17_s-3","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-17","order":3,"canonicalText":"錫土姓，祗臺德先，不距朕行。","chunks":[]},{"id":"shiji_ch-2_p-20_s-1","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-20","order":1,"canonicalText":"皋陶作士以理民。","chunks":[]},{"id":"shiji_ch-2_p-20_s-2","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-20","order":2,"canonicalText":"帝舜朝，禹、伯夷、皋陶相與語帝前。","chunks":[]},{"id":"shiji_ch-2_p-20_s-3","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-20","order":3,"canonicalText":"皋陶述其謀曰：「信其道德，謀明輔和。","chunks":[]},{"id":"shiji_ch-2_p-20_s-4","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-20","order":4,"canonicalText":"」禹曰：「然，如何？","chunks":[]},{"id":"shiji_ch-2_p-20_s-5","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-20","order":5,"canonicalText":"」皋陶曰：「於！","chunks":[]},{"id":"shiji_ch-2_p-20_s-6","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-20","order":6,"canonicalText":"慎其修身思長，敦序九族，眾明高翼，近者大興，遠者往迎。","chunks":[]},{"id":"shiji_ch-2_p-20_s-7","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-20","order":7,"canonicalText":"」禹拜美言，曰：「然。","chunks":[]},{"id":"shiji_ch-2_p-20_s-8","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-20","order":8,"canonicalText":"」皋陶曰：「於！","chunks":[]},{"id":"shiji_ch-2_p-20_s-9","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-20","order":9,"canonicalText":"在知人，在安民。","chunks":[]},{"id":"shiji_ch-2_p-20_s-10","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-20","order":10,"canonicalText":"」禹曰：「籲！","chunks":[]},{"id":"shiji_ch-2_p-20_s-11","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-20","order":11,"canonicalText":"皆若此，唯帝其難之。","chunks":[]},{"id":"shiji_ch-2_p-20_s-12","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-20","order":12,"canonicalText":"知人則哲，能官人；","chunks":[]},{"id":"shiji_ch-2_p-20_s-13","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-20","order":13,"canonicalText":"安民則惠，黎庶懷之。","chunks":[]},{"id":"shiji_ch-2_p-20_s-14","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-20","order":14,"canonicalText":"能哲而惠，何憂乎驩兜，何遷乎三苗，何畏乎巧言令色孔壬？","chunks":[]},{"id":"shiji_ch-2_p-20_s-15","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-20","order":15,"canonicalText":"」","chunks":[]},{"id":"shiji_ch-2_p-21_s-1","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-21","order":1,"canonicalText":"帝舜謂禹曰：「女亦昌言。","chunks":[]},{"id":"shiji_ch-2_p-21_s-2","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-21","order":2,"canonicalText":"」禹拜曰：「於，予何言！","chunks":[]},{"id":"shiji_ch-2_p-21_s-3","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-21","order":3,"canonicalText":"予思日孳孳。","chunks":[]},{"id":"shiji_ch-2_p-21_s-4","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-21","order":4,"canonicalText":"」皋陶難禹曰：「何謂孳孳？","chunks":[]},{"id":"shiji_ch-2_p-21_s-5","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-21","order":5,"canonicalText":"」禹曰：「鴻水滔天，浩浩懷山襄陵，下民皆惑於水。","chunks":[]},{"id":"shiji_ch-2_p-21_s-6","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-21","order":6,"canonicalText":"予陸行乘車，水行乘舟，泥行乘橇，山行乘檋，行山刊木。","chunks":[]},{"id":"shiji_ch-2_p-21_s-7","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-21","order":7,"canonicalText":"與益予眾庶稻鮮食。","chunks":[]},{"id":"shiji_ch-2_p-21_s-8","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-21","order":8,"canonicalText":"以予導九川致四海，振興麟鳳，益稷播奏庶艱食鮮食。","chunks":[]},{"id":"shiji_ch-2_p-21_s-9","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-21","order":9,"canonicalText":"懋遷有無化居。","chunks":[]},{"id":"shiji_ch-2_p-21_s-10","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-21","order":10,"canonicalText":"蒸民乃粒，萬國作乂。","chunks":[]},{"id":"shiji_ch-2_p-21_s-11","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-21","order":11,"canonicalText":"」皋陶曰：「然，此而美也。","chunks":[]},{"id":"shiji_ch-2_p-21_s-12","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-21","order":12,"canonicalText":"」","chunks":[]},{"id":"shiji_ch-2_p-22_s-1","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-22","order":1,"canonicalText":"禹曰：「於，帝！","chunks":[]},{"id":"shiji_ch-2_p-22_s-2","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-22","order":2,"canonicalText":"慎乃在位，安爾止。","chunks":[]},{"id":"shiji_ch-2_p-22_s-3","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-22","order":3,"canonicalText":"輔德，天下大應。","chunks":[]},{"id":"shiji_ch-2_p-22_s-4","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-22","order":4,"canonicalText":"清意以昭待上帝命，天其重命用休。","chunks":[]},{"id":"shiji_ch-2_p-22_s-5","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-22","order":5,"canonicalText":"」帝曰：「籲！","chunks":[]},{"id":"shiji_ch-2_p-22_s-6","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-22","order":6,"canonicalText":"臣哉，臣哉！","chunks":[]},{"id":"shiji_ch-2_p-22_s-7","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-22","order":7,"canonicalText":"臣作朕股肱耳目。","chunks":[]},{"id":"shiji_ch-2_p-22_s-8","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-22","order":8,"canonicalText":"予欲左右有民，女隨；","chunks":[]},{"id":"shiji_ch-2_p-22_s-9","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-22","order":9,"canonicalText":"予欲宣力四方，女為；","chunks":[]},{"id":"shiji_ch-2_p-22_s-10","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-22","order":10,"canonicalText":"予欲觀古人之象，日月星辰，山龍華蟲作會，宗彝藻火粉米黼黻，希繡，以五采彰施於五色，作服，女明之；","chunks":[]},{"id":"shiji_ch-2_p-22_s-11","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-22","order":11,"canonicalText":"予欲聞六律五聲八音，察神人以歌，女聽。","chunks":[]},{"id":"shiji_ch-2_p-22_s-12","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-22","order":12,"canonicalText":"予違，汝弼，汝無面從退有後言。","chunks":[]},{"id":"shiji_ch-2_p-22_s-13","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-22","order":13,"canonicalText":"敬四鄰，庶頑讒說，若不在時，侯以明之，撻以記之，書用識之，欲並生故也。","chunks":[]},{"id":"shiji_ch-2_p-22_s-14","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-22","order":14,"canonicalText":"德懋懋官，功懋懋賞。","chunks":[]},{"id":"shiji_ch-2_p-22_s-15","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-22","order":15,"canonicalText":"萬邦黎獻，共帝祥。","chunks":[]},{"id":"shiji_ch-2_p-22_s-16","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-22","order":16,"canonicalText":"惟德時敘，罔或逆亂。","chunks":[]},{"id":"shiji_ch-2_p-22_s-17","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-22","order":17,"canonicalText":"」","chunks":[]},{"id":"shiji_ch-2_p-23_s-1","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-23","order":1,"canonicalText":"帝曰：「毋若丹朱傲，維慢遊是好，毋水行舟，朋淫於家，用絕其世。","chunks":[]},{"id":"shiji_ch-2_p-23_s-2","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-23","order":2,"canonicalText":"予不能順是。","chunks":[]},{"id":"shiji_ch-2_p-23_s-3","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-23","order":3,"canonicalText":"」禹曰：「予辛壬癸甲，娶塗山，辛壬癸甲，生啟，予不子，以故能成水土功。","chunks":[]},{"id":"shiji_ch-2_p-23_s-4","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-23","order":4,"canonicalText":"輔成五服，至於五千裏，州十二師，外薄四海，鹹建五長，各守其職，莫敢不敬。","chunks":[]},{"id":"shiji_ch-2_p-23_s-5","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-23","order":5,"canonicalText":"」","chunks":[]},{"id":"shiji_ch-2_p-25_s-1","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-25","order":1,"canonicalText":"於是夔行樂，祖考至，群后相讓，鳥獸翔舞，簫韶九成，鳳皇來儀，百獸率舞，百官信諧。","chunks":[]},{"id":"shiji_ch-2_p-25_s-2","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-25","order":2,"canonicalText":"帝用此作歌，曰：「陟天之命，維時維幾。","chunks":[]},{"id":"shiji_ch-2_p-25_s-3","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-25","order":3,"canonicalText":"」乃歌曰：「天可度，時可代，動百工，朕何為哉！","chunks":[]},{"id":"shiji_ch-2_p-25_s-4","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-25","order":4,"canonicalText":"」周公作《立政》，言禹之德也。","chunks":[]},{"id":"shiji_ch-2_p-33_s-1","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-33","order":1,"canonicalText":"中康崩，子帝相立。","chunks":[]},{"id":"shiji_ch-2_p-33_s-2","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-33","order":2,"canonicalText":"帝相崩，子帝少康立。","chunks":[]},{"id":"shiji_ch-2_p-33_s-3","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-33","order":3,"canonicalText":"帝少康崩，子帝予立。","chunks":[]},{"id":"shiji_ch-2_p-33_s-4","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-33","order":4,"canonicalText":"帝予崩，子帝槐立。","chunks":[]},{"id":"shiji_ch-2_p-33_s-5","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-33","order":5,"canonicalText":"帝槐崩，子帝芒立。","chunks":[]},{"id":"shiji_ch-2_p-33_s-6","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-33","order":6,"canonicalText":"帝芒崩，子帝泄立。","chunks":[]},{"id":"shiji_ch-2_p-33_s-7","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-33","order":7,"canonicalText":"帝泄崩，子帝不降立。","chunks":[]},{"id":"shiji_ch-2_p-33_s-8","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-33","order":8,"canonicalText":"帝不降崩，弟帝扃立。","chunks":[]},{"id":"shiji_ch-2_p-33_s-9","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-33","order":9,"canonicalText":"帝扃崩，子帝廑立。","chunks":[]},{"id":"shiji_ch-2_p-33_s-10","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-33","order":10,"canonicalText":"帝廑崩，立不降之子孔甲，是為帝孔甲。","chunks":[]},{"id":"shiji_ch-2_p-33_s-11","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-33","order":11,"canonicalText":"孔甲立，好方鬼神，事淫亂。","chunks":[]},{"id":"shiji_ch-2_p-33_s-12","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-33","order":12,"canonicalText":"夏后氏德衰，諸侯畔之。","chunks":[]},{"id":"shiji_ch-2_p-34_s-1","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-34","order":1,"canonicalText":"孔甲崩，子帝皋立。","chunks":[]},{"id":"shiji_ch-2_p-34_s-2","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-34","order":2,"canonicalText":"帝皋崩，子帝發立。","chunks":[]},{"id":"shiji_ch-2_p-34_s-3","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-34","order":3,"canonicalText":"帝發崩，子帝履癸立，是為桀。","chunks":[]},{"id":"shiji_ch-2_p-34_s-4","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-34","order":4,"canonicalText":"帝桀之時，自孔甲以來而諸侯多畔夏，桀不務德而武傷百姓，百姓弗堪。","chunks":[]},{"id":"shiji_ch-2_p-34_s-5","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-34","order":5,"canonicalText":"乃召湯而囚之夏臺，已而釋之。","chunks":[]},{"id":"shiji_ch-2_p-34_s-6","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-34","order":6,"canonicalText":"湯修德，諸侯皆歸湯，湯遂率師以伐夏桀。","chunks":[]},{"id":"shiji_ch-2_p-34_s-7","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-34","order":7,"canonicalText":"桀走鳴條，遂放而死。","chunks":[]},{"id":"shiji_ch-2_p-34_s-8","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-34","order":8,"canonicalText":"桀謂人曰：「吾悔不遂殺湯於夏臺，使至此。","chunks":[]},{"id":"shiji_ch-2_p-34_s-9","chapterId":"shiji_ch-2","passageId":"shiji_ch-2_p-34","order":9,"canonicalText":"」湯乃踐天子位，代夏，是為商湯。","chunks":[]}]}');export{i as default};
